const DATE_TIME_TRIGGER_RE = /^(dt|[dtD])(-?\d+)$/;
const INCOMPLETE_NEGATIVE_OFFSET_TRIGGER_RE = /(^|[^A-Za-z0-9_])(?:dt|[dtD])-$/;
const WORD_CHAR_RE = /[A-Za-z0-9_]/;
const EM_DASH_REPLACEMENT = "— ";
const POMODOROS_HEADING_RE = /^##\s+Pomodoros(?:\s.*)?$/;
