function parseEmDashTrigger(text) {
  if (!text.endsWith("-")) {
    return null;
  }

  const precedingChar = text.length > 1 ? text[text.length - 2] : "";
  if (precedingChar === "-") {
    return null;
  }

  return {
    kind: "emDash",
    trigger: "-",
    startCh: text.length - 1,
    endCh: text.length,
  };
}

function parseTrigger(textBeforeCursor) {
  const text = String(textBeforeCursor || "");
  const match = TRIGGER_RE.exec(text);

  if (!match) {
    if (INCOMPLETE_NEGATIVE_OFFSET_TRIGGER_RE.test(text)) {
      return null;
    }
    return parseEmDashTrigger(text);
  }

  const trigger = match[2];
  const startCh = text.length - trigger.length;
  const endCh = text.length;

  if (trigger === "ta") {
    return {
      kind: "task",
      trigger,
      startCh,
      endCh,
    };
  }

  const ledgerMatch = LEDGER_TRIGGER_RE.exec(trigger);

  if (!ledgerMatch) {
    const dateTimeMatch = DATE_TIME_TRIGGER_RE.exec(trigger);
    if (!dateTimeMatch) {
      return null;
    }

    const prefix = dateTimeMatch[1];
    const offset = Number.parseInt(dateTimeMatch[2], 10);
    if (!Number.isFinite(offset)) {
      return null;
    }

    let kind = "time";
    if (prefix === "dt") {
      kind = "datetime";
    } else if (prefix === "d") {
      kind = "date";
    } else if (prefix === "D") {
      kind = "datedEntry";
    }

    return {
      kind,
      trigger,
      startCh,
      endCh,
      offset,
    };
  }

  const durationText = ledgerMatch[1] || "";
  const offsetText = ledgerMatch[2];
  const dashPresent = trigger.includes("-");
  const durationMultiplier =
    durationText === "" ? 5 : Number.parseInt(durationText, 10);
  const offsetMultiplier =
    offsetText === undefined
      ? dashPresent
        ? 1
        : 0
      : offsetText === ""
        ? 1
        : Number.parseInt(offsetText, 10);

  if (!Number.isFinite(durationMultiplier) || !Number.isFinite(offsetMultiplier)) {
    return null;
  }

  return {
    kind: "ledgerRange",
    trigger,
    startCh,
    endCh,
    durationMultiplier,
    offsetMultiplier,
    dashPresent,
  };
}

function numericOrDefault(value, fallback) {
  const number = typeof value === "number" ? value : Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function finiteNumberOrNull(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function clampNumber(value, min, max) {
  const safeMin = finiteNumberOrNull(min);
  const safeMax = finiteNumberOrNull(max);
  const lower = safeMin === null ? 0 : safeMin;
  const upper =
    safeMax === null ? Number.POSITIVE_INFINITY : Math.max(lower, safeMax);
  return Math.min(Math.max(Number(value) || 0, lower), upper);
}

function normalizeEditorPosition(position) {
  if (!position) {
    return null;
  }

  const line = Math.floor(numericOrDefault(position.line, Number.NaN));
  const ch = Math.floor(numericOrDefault(position.ch, 0));
  if (!Number.isFinite(line) || line < 0) {
    return null;
  }

  return { line, ch: Math.max(ch, 0) };
}

function normalizeDailyLocation(location) {
  if (!location) {
    return null;
  }

  const cursor = normalizeEditorPosition(
    location.cursor || location.position || location.sourcePosition,
  );
  const scrollTop = finiteNumberOrNull(location.scrollTop);
  const scrollLeft = finiteNumberOrNull(location.scrollLeft);
  if (!cursor && scrollTop === null && scrollLeft === null) {
    return null;
  }

  const normalized = {};
  if (cursor) {
    normalized.cursor = cursor;
  }
  if (scrollTop !== null) {
    normalized.scrollTop = Math.max(0, scrollTop);
  }
  if (scrollLeft !== null) {
    normalized.scrollLeft = Math.max(0, scrollLeft);
  }
  return normalized;
}

function normalizeMinutes(minutes) {
  return ((minutes % DAY_MINUTES) + DAY_MINUTES) % DAY_MINUTES;
}

function formatTime(minutes, style = "compact") {
  const normalized = normalizeMinutes(minutes);
  const hour = Math.floor(normalized / 60);
  const minute = normalized % 60;
  const hourText = String(hour).padStart(2, "0");
  const minuteText = String(minute).padStart(2, "0");

  if (style === "colon") {
    return `${hourText}:${minuteText}`;
  }

  return `${hourText}${minuteText}`;
}

function coerceDate(value) {
  const date =
    value instanceof Date ? new Date(value.getTime()) : new Date(value);
  return Number.isNaN(date.getTime()) ? new Date() : date;
}

function formatLocalDate(value) {
  const date = coerceDate(value);
  const yearText = String(date.getFullYear()).padStart(4, "0");
  const monthText = String(date.getMonth() + 1).padStart(2, "0");
  const dayText = String(date.getDate()).padStart(2, "0");
  return `${yearText}-${monthText}-${dayText}`;
}

function dailyDateFormatTokens(value) {
  const date = coerceDate(value);
  const yearText = String(date.getFullYear()).padStart(4, "0");
  const monthNumber = date.getMonth() + 1;
  const monthText = String(monthNumber).padStart(2, "0");
  const dayNumber = date.getDate();
  const dayText = String(dayNumber).padStart(2, "0");

  return {
    YYYY: yearText,
    YY: yearText.slice(-2),
    MM: monthText,
    DD: dayText,
    M: String(monthNumber),
    D: String(dayNumber),
  };
}

function formatDailyDate(value, format = DEFAULT_DAILY_NOTES_FORMAT) {
  const source = String(format || DEFAULT_DAILY_NOTES_FORMAT);
  const tokens = dailyDateFormatTokens(value);
  let result = "";

  for (let index = 0; index < source.length; ) {
    if (source[index] === "[") {
      const endIndex = source.indexOf("]", index + 1);
      if (endIndex !== -1) {
        result += source.slice(index + 1, endIndex);
        index = endIndex + 1;
        continue;
      }
    }

    const token = DAILY_FORMAT_TOKENS.find((candidate) =>
      source.startsWith(candidate, index),
    );
    if (token) {
      result += tokens[token];
      index += token.length;
      continue;
    }

    result += source[index];
    index += 1;
  }

  return result;
}

function normalizeVaultPath(value) {
  const text = String(value || "")
    .trim()
    .replace(/\\/g, "/")
    .replace(/^\/+/, "");

  if (!text) {
    return "";
  }

  const compactPath = text.replace(/\/+/g, "/").replace(/\/$/, "");
  if (typeof normalizePath === "function") {
    return normalizePath(compactPath).replace(/^\/+/, "");
  }

  return compactPath;
}

function ensureMarkdownExtension(path) {
  const normalized = normalizeVaultPath(path);
  return /\.md$/i.test(normalized) ? normalized : `${normalized}.md`;
}

function joinVaultPath(folder, path) {
  const normalizedPath = normalizeVaultPath(path);
  const normalizedFolder = normalizeVaultPath(folder);

  return normalizedFolder
    ? normalizeVaultPath(`${normalizedFolder}/${normalizedPath}`)
    : normalizedPath;
}

function todayDailyPath(now = new Date(), dailyOptions = {}) {
  const options = dailyOptions || {};
  const path = ensureMarkdownExtension(
    formatDailyDate(now, options.format || DEFAULT_DAILY_NOTES_FORMAT),
  );

  return joinVaultPath(options.folder || "", path);
}

function getDailyNotesOptions(app) {
  const internalPlugins = app && app.internalPlugins;
  const plugin =
    (internalPlugins &&
      internalPlugins.plugins &&
      internalPlugins.plugins[DAILY_NOTES_COMMAND_ID]) ||
    (internalPlugins && typeof internalPlugins.getPluginById === "function"
      ? internalPlugins.getPluginById(DAILY_NOTES_COMMAND_ID)
      : null);
  const instance = plugin && plugin.instance;

  return (instance && instance.options) || {};
}

function sameVaultPath(left, right) {
  return normalizeVaultPath(left) === normalizeVaultPath(right);
}

function getActiveFile(app) {
  const workspace = app && app.workspace;
  if (!workspace || typeof workspace.getActiveFile !== "function") {
    return null;
  }

  return workspace.getActiveFile();
}

function isTodayDailyFile(app, file, options = {}) {
  if (!file || typeof file.path !== "string") {
    return false;
  }

  const dailyPath = todayDailyPath(
    options.now || new Date(),
    options.dailyOptions || getDailyNotesOptions(app),
  );
  return sameVaultPath(file.path, dailyPath);
}

function formatLocalDateTime(value) {
  const date = coerceDate(value);
  const minutes = date.getHours() * 60 + date.getMinutes();
  return `${formatLocalDate(date)} ${formatTime(minutes, "colon")}`;
}

function addLocalMinutes(value, minutes) {
  const date = coerceDate(value);
  date.setMinutes(date.getMinutes() + numericOrDefault(minutes, 0));
  return date;
}

function addLocalDays(value, days) {
  const date = coerceDate(value);
  date.setDate(date.getDate() + numericOrDefault(days, 0));
  return date;
}

function formatOffsetTime(now, offsetMinutes) {
  const date = addLocalMinutes(now, offsetMinutes);
  return formatTime(date.getHours() * 60 + date.getMinutes());
}

function formatOffsetDate(now, offsetDays) {
  return formatLocalDate(addLocalDays(now, offsetDays));
}

function formatOffsetDateTime(now, offsetMinutes) {
  return formatLocalDateTime(addLocalMinutes(now, offsetMinutes));
}

function addMinutes(minutes, delta) {
  return normalizeMinutes(minutes + delta);
}

function validTime(hours, minutes) {
  return (
    Number.isInteger(hours) &&
    Number.isInteger(minutes) &&
    hours >= 0 &&
    hours <= 23 &&
    minutes >= 0 &&
    minutes <= 59
  );
}

function minutesFromParts(hours, minutes) {
  const parsedHours = Number.parseInt(hours, 10);
  const parsedMinutes = Number.parseInt(minutes, 10);

  if (!validTime(parsedHours, parsedMinutes)) {
    return null;
  }

  return parsedHours * 60 + parsedMinutes;
}

function findPomodorosSection(lines) {
  if (!Array.isArray(lines)) {
    return null;
  }

  const headingLine = lines.findIndex((line) =>
    POMODOROS_HEADING_RE.test(String(line || "")),
  );

  if (headingLine === -1) {
    return null;
  }

  let endLine = lines.length - 1;
  for (let line = headingLine + 1; line < lines.length; line += 1) {
    if (LEVEL_TWO_HEADING_RE.test(String(lines[line] || ""))) {
      endLine = line - 1;
      break;
    }
  }

  return {
    headingLine,
    startLine: headingLine + 1,
    endLine,
  };
}

function parseTimeRange(line) {
  const text = String(line || "");
  let match = COLON_TIME_RANGE_RE.exec(text);

  if (match) {
    return rangeFromMatch(match, "colon");
  }

  match = COMPACT_TIME_RANGE_RE.exec(text);
  if (!match) {
    return null;
  }

  return rangeFromMatch(match, "compact");
}

function rangeFromMatch(match, style) {
  const openingBold = match[1] || "";
  const closingBold = match[6] || "";

  if (Boolean(openingBold) !== Boolean(closingBold)) {
    return null;
  }

  const startMinutes = minutesFromParts(match[2], match[3]);
  const endMinutes = minutesFromParts(match[4], match[5]);

  if (startMinutes === null || endMinutes === null) {
    return null;
  }

  return {
    startCh: match.index,
    endCh: match.index + match[0].length,
    startMinutes,
    endMinutes,
    style,
    metadata: match[7] || "",
    bold: Boolean(openingBold),
  };
}

function formatTimeRange(
  startMinutes,
  endMinutes,
  style = "compact",
  metadata = "",
) {
  return `(**${formatTime(startMinutes, style)}-${formatTime(endMinutes, style)}**${metadata || ""})`;
}

function replaceTimeRange(line, range, startMinutes, endMinutes) {
  if (!range) {
    return null;
  }

  const text = String(line || "");
  const newRange = formatTimeRange(
    startMinutes,
    endMinutes,
    range.style,
    range.metadata,
  );
  return text.slice(0, range.startCh) + newRange + text.slice(range.endCh);
}

function durationField(rangeText) {
  const match = DURATION_FIELD_RE.exec(String(rangeText || ""));

  if (!match) {
    return null;
  }

  return {
    startCh: match.index,
    endCh: match.index + match[0].length,
    value: match[1],
  };
}

function legacyStopwatchDuration(rangeText) {
  const match = LEGACY_STOPWATCH_DURATION_RE.exec(String(rangeText || ""));

  if (!match) {
    return null;
  }

  return {
    startCh: match.index,
    endCh: match.index + match[0].length,
    value: match[1],
  };
}

function parseDurationMinutes(value) {
  const text = String(value || "").trim().toLowerCase();
  if (!text) {
    return null;
  }

  const minuteMatch = /^(\d+)\s*m$/.exec(text);
  if (minuteMatch) {
    return Number.parseInt(minuteMatch[1], 10);
  }

  const hourMinuteMatch = /^(?:(\d+)\s*h)?\s*(?:(\d+)\s*m)?$/.exec(text);
  if (!hourMinuteMatch || (!hourMinuteMatch[1] && !hourMinuteMatch[2])) {
    return null;
  }

  const hours = hourMinuteMatch[1]
    ? Number.parseInt(hourMinuteMatch[1], 10)
    : 0;
  const minutes = hourMinuteMatch[2]
    ? Number.parseInt(hourMinuteMatch[2], 10)
    : 0;
  return hours * 60 + minutes;
}

function formatDurationField(minutes) {
  const safeMinutes = Math.max(0, Math.floor(numericOrDefault(minutes, 0)));
  return `[t:: ${safeMinutes}m]`;
}

function rangeDurationMinutes(range) {
  if (!range) {
    return null;
  }

  return normalizeMinutes(range.endMinutes - range.startMinutes);
}

function removeDurationMetadata(metadata) {
  return String(metadata || "")
    .replace(DURATION_FIELD_GLOBAL_RE, "")
    .replace(LEGACY_STOPWATCH_DURATION_GLOBAL_RE, "")
    .replace(/\s+/g, " ")
    .trim();
}

function durationMetadata(minutes, metadata) {
  const rest = removeDurationMetadata(metadata);
  return rest
    ? ` ${formatDurationField(minutes)} ${rest}`
    : ` ${formatDurationField(minutes)}`;
}

function pomodoroDurationMinutes(line, range) {
  if (!range) {
    return null;
  }

  const rangeText = String(line || "").slice(range.startCh, range.endCh);
  const field = durationField(rangeText);
  if (field) {
    const fieldMinutes = parseDurationMinutes(field.value);
    if (fieldMinutes !== null) {
      return fieldMinutes;
    }
  }

  const legacy = legacyStopwatchDuration(rangeText);
  if (legacy) {
    const legacyMinutes = parseDurationMinutes(legacy.value);
    if (legacyMinutes !== null) {
      return legacyMinutes;
    }
  }

  return rangeDurationMinutes(range);
}

function changePomodoroLineUnits(line, units) {
  const range = parseTimeRange(line);

  if (!range) {
    return null;
  }

  const currentMinutes = pomodoroDurationMinutes(line, range);
  if (currentMinutes === null) {
    return null;
  }

  const nextMinutes = Math.max(
    0,
    currentMinutes + numericOrDefault(units, 0) * STEP_MINUTES,
  );
  const metadata = durationMetadata(nextMinutes, range.metadata);
  const nextEndMinutes = addMinutes(range.startMinutes, nextMinutes);
  const text = String(line || "");
  const newRange = formatTimeRange(
    range.startMinutes,
    nextEndMinutes,
    range.style,
    metadata,
  );
  return text.slice(0, range.startCh) + newRange + text.slice(range.endCh);
}

function offsetPomodoroLineRange(line, minutes) {
  const range = parseTimeRange(line);

  if (!range) {
    return null;
  }

  return replaceTimeRange(
    line,
    range,
    addMinutes(range.startMinutes, minutes),
    addMinutes(range.endMinutes, minutes),
  );
}

function parseLedgerLine(line) {
  const text = String(line || "");
  const match = LEDGER_LINE_RE.exec(text);

  if (!match) {
    return null;
  }

  const checkbox = match[2];
  return {
    checkbox,
    completed: checkbox === "x" || checkbox === "X",
    cancelled: checkbox === "-",
    open: checkbox === " " || checkbox === "/",
    inProgress: checkbox === "/",
    unchecked: checkbox === " ",
    range: parseTimeRange(text),
    placeholder: PLACEHOLDER_RE.test(text),
  };
}

function pomodoroItem(line, lineText, entry) {
  return {
    line,
    lineNumber: line,
    lineText,
    entry,
  };
}

function findActivePomodoroItemInSection(lines, section) {
  let latestTimed = null;
  let firstPlaceholder = null;

  for (let line = section.startLine; line <= section.endLine; line += 1) {
    const lineText = String(lines[line] || "");
    const entry = parseLedgerLine(lineText);

    if (!entry || !entry.open) {
      continue;
    }

    const item = pomodoroItem(line, lineText, entry);
    if (entry.range) {
      latestTimed = item;
    } else if (entry.placeholder && !firstPlaceholder) {
      firstPlaceholder = item;
    }
  }

  return latestTimed || firstPlaceholder;
}

function findCompletedPomodoroItemInSection(lines, section) {
  let lastCompleted = null;

  for (let line = section.startLine; line <= section.endLine; line += 1) {
    const lineText = String(lines[line] || "");
    const entry = parseLedgerLine(lineText);

    if (!entry || !entry.completed || (!entry.range && !entry.placeholder)) {
      continue;
    }

    lastCompleted = pomodoroItem(line, lineText, entry);
  }

  return lastCompleted;
}

function getActivePomodoroTarget(lines) {
  const section = findPomodorosSection(lines);

  if (!section) {
    return { target: null, error: "No ## Pomodoros section found" };
  }

  const target = findActivePomodoroItemInSection(lines, section);
  return {
    target,
    error: target ? null : "No active Pomodoro line found",
  };
}

function getJumpPomodoroTarget(lines) {
  const section = findPomodorosSection(lines);

  if (!section) {
    return { target: null, error: "No ## Pomodoros section found" };
  }

  const activeTarget = findActivePomodoroItemInSection(lines, section);
  if (activeTarget) {
    return { target: activeTarget, error: null };
  }

  const completedTarget = findCompletedPomodoroItemInSection(lines, section);
  return {
    target: completedTarget,
    error: completedTarget
      ? null
      : "No active or completed Pomodoro line found",
  };
}

function findActivePomodoroItem(lines) {
  return getActivePomodoroTarget(lines).target;
}

function currentPomodoroLineTarget(lines, section, cursorLine, requireRange) {
  if (
    !Number.isInteger(cursorLine) ||
    cursorLine < section.startLine ||
    cursorLine > section.endLine
  ) {
    return null;
  }

  const lineText = String(lines[cursorLine] || "");
  const entry = parseLedgerLine(lineText);

  if (!entry || (requireRange && !entry.range)) {
    return null;
  }

  return pomodoroItem(cursorLine, lineText, entry);
}

function getEditPomodoroTarget(lines, cursorLine, requireRange = true) {
  const section = findPomodorosSection(lines);

  if (!section) {
    return { target: null, error: "No ## Pomodoros section found" };
  }

  const currentTarget = currentPomodoroLineTarget(
    lines,
    section,
    cursorLine,
    requireRange,
  );
  if (currentTarget) {
    return { target: currentTarget, error: null };
  }

  const activeTarget = findActivePomodoroItemInSection(lines, section);
  if (!activeTarget) {
    return { target: null, error: "No active Pomodoro line found" };
  }

  if (requireRange && !activeTarget.entry.range) {
    return {
      target: null,
      error: "No Pomodoro line with a time range found",
    };
  }

  return { target: activeTarget, error: null };
}

function resolveEditPomodoroTarget(lines, cursorLine, requireRange = true) {
  return getEditPomodoroTarget(lines, cursorLine, requireRange).target;
}

// ---- src/030-snippets.js ----
function computeRange(now, durationMultiplier, offsetMultiplier, dashPresent) {
  const safeDate = coerceDate(now);
  const durationSteps = numericOrDefault(durationMultiplier, 5);
  const offsetSteps = numericOrDefault(offsetMultiplier, dashPresent ? 1 : 0);
  const offsetMinutes = offsetSteps * STEP_MINUTES;
  const durationMinutes = durationSteps * STEP_MINUTES;
  const currentMinutes = safeDate.getHours() * 60 + safeDate.getMinutes();
  const startMinutes = normalizeMinutes(
    Math.ceil((currentMinutes - offsetMinutes) / STEP_MINUTES) * STEP_MINUTES,
  );
  const endMinutes = normalizeMinutes(startMinutes + durationMinutes);
  const start = formatTime(startMinutes);
  const end = formatTime(endMinutes);
  const metadata = ` ${formatDurationField(durationMinutes)}`;

  return {
    startMinutes,
    endMinutes,
    durationMinutes,
    start,
    end,
    text: formatTimeRange(startMinutes, endMinutes, "compact", metadata),
  };
}

function computeSnippetExpansion(trigger, now = new Date()) {
  if (!trigger) {
    return null;
  }

  if (trigger.kind === "emDash") {
    return { replacement: EM_DASH_REPLACEMENT };
  }

  if (trigger.kind === "task") {
    const createdDate = formatLocalDate(now);
    return {
      replacement: `#task  [created::${createdDate}]`,
      cursorOffset: "#task ".length,
    };
  }

  if (trigger.kind === "ledgerRange") {
    const range = computeRange(
      now,
      trigger.durationMultiplier,
      trigger.offsetMultiplier,
      trigger.dashPresent,
    ).text;
    return {
      replacement: `${range} `,
      range,
    };
  }

  if (trigger.kind === "time") {
    const text = formatOffsetTime(now, trigger.offset);
    return { replacement: text, text };
  }

  if (trigger.kind === "date") {
    const text = formatOffsetDate(now, trigger.offset);
    return { replacement: text, text };
  }

  if (trigger.kind === "datedEntry") {
    const dateText = formatOffsetDate(now, trigger.offset);
    const replacement = `_${dateText}_ — `;
    return {
      replacement,
      cursorOffset: replacement.length,
      text: replacement,
    };
  }

  if (trigger.kind === "datetime") {
    const text = formatOffsetDateTime(now, trigger.offset);
    return { replacement: text, text };
  }

  return null;
}

function expansionCursorCh(expansion) {
  if (!expansion) {
    return null;
  }

  const offset = Number.isInteger(expansion.cursorOffset)
    ? expansion.cursorOffset
    : String(expansion.replacement || "").length;
  return expansion.fromCh + offset;
}

function isWordChar(value) {
  return typeof value === "string" && WORD_CHAR_RE.test(value);
}

function isTriggerBoundaryBlocked(trigger, nextChar) {
  if (trigger.kind === "emDash") {
    return nextChar === "-";
  }

  return isWordChar(nextChar);
}

function findExpansion(line, cursorCh, now = new Date()) {
  if (typeof line !== "string" || !Number.isInteger(cursorCh)) {
    return null;
  }

  if (cursorCh < 0 || cursorCh > line.length) {
    return null;
  }

  const trigger = parseTrigger(line.slice(0, cursorCh));
  if (!trigger || isTriggerBoundaryBlocked(trigger, line[cursorCh])) {
    return null;
  }

  const snippetExpansion = computeSnippetExpansion(trigger, now);
  if (!snippetExpansion) {
    return null;
  }

  let fromCh = trigger.startCh;
  let toCh = cursorCh;
  let replacement = snippetExpansion.replacement;

  if (
    trigger.kind === "ledgerRange" &&
    line[fromCh - 1] === "(" &&
    line[cursorCh] === ")"
  ) {
    fromCh -= 1;
    toCh += 1;
    replacement = snippetExpansion.range;
  }

  const expansion = {
    fromCh,
    toCh,
    replacement,
    trigger: trigger.trigger,
  };

  if (snippetExpansion.range !== undefined) {
    expansion.range = snippetExpansion.range;
  }

  if (snippetExpansion.text !== undefined) {
    expansion.text = snippetExpansion.text;
  }

  if (snippetExpansion.cursorOffset !== undefined) {
    expansion.cursorOffset = snippetExpansion.cursorOffset;
  }

  return expansion;
}

function expandLineAtCursor(line, cursorCh, now = new Date()) {
  const expansion = findExpansion(line, cursorCh, now);

  if (!expansion) {
    return null;
  }

  return {
    line:
      line.slice(0, expansion.fromCh) +
      expansion.replacement +
      line.slice(expansion.toCh),
    cursorCh: expansionCursorCh(expansion),
    expansion,
  };
}

// ---- src/040-editor-and-daily.js ----
function sameEditorPosition(left, right) {
  return (
    !!left &&
    !!right &&
    left.line === right.line &&
    left.ch === right.ch
  );
}

function isCollapsedCodeMirrorSelection(cmView) {
  const selection = cmView && cmView.state && cmView.state.selection;

  if (!selection || !Array.isArray(selection.ranges)) {
    return true;
  }

  if (selection.ranges.length !== 1) {
    return false;
  }

  const range = selection.ranges[0];
  return range.empty || range.from === range.to;
}

function getEditorLines(cm) {
  if (!cm) {
    return null;
  }

  if (typeof cm.getValue === "function") {
    return String(cm.getValue()).split(/\r?\n/);
  }

  if (typeof cm.getLine !== "function") {
    return null;
  }

  const firstLine = typeof cm.firstLine === "function" ? cm.firstLine() : 0;
  const lastLine =
    typeof cm.lastLine === "function"
      ? cm.lastLine()
      : typeof cm.lineCount === "function"
        ? Math.max(firstLine, cm.lineCount() - 1)
        : firstLine;
  const lines = [];

  for (let line = firstLine; line <= lastLine; line += 1) {
    lines[line] = cm.getLine(line) || "";
  }

  return lines;
}

function getEditorCursorLine(cm) {
  if (!cm || typeof cm.getCursor !== "function") {
    return null;
  }

  const cursor = cm.getCursor();
  return cursor && Number.isInteger(cursor.line) ? cursor.line : null;
}

function getActiveMarkdownView(app) {
  const workspace = app && app.workspace;
  if (!workspace || typeof workspace.getActiveViewOfType !== "function") {
    return null;
  }

  const view = workspace.getActiveViewOfType(MarkdownView);
  if (!(view instanceof MarkdownView) || !view.editor) {
    return null;
  }

  return view;
}

function getActiveMarkdownViewPath(app, view) {
  const file = (view && view.file) || getActiveFile(app);
  return file && typeof file.path === "string"
    ? normalizeVaultPath(file.path)
    : "";
}

function delay(ms) {
  return new Promise((resolve) =>
    setTimeout(resolve, Math.max(0, numericOrDefault(ms, 0))),
  );
}

async function waitForActiveMarkdownView(app, options = {}) {
  const expectedPath = normalizeVaultPath(options.path || "");
  const attempts = Math.max(
    1,
    Math.floor(numericOrDefault(options.attempts, DAILY_OPEN_ATTEMPTS)),
  );
  const delayMs = Math.max(
    0,
    Math.floor(numericOrDefault(options.delayMs, DAILY_OPEN_RETRY_DELAY_MS)),
  );

  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const view = getActiveMarkdownView(app);
    if (
      view &&
      (!expectedPath ||
        sameVaultPath(getActiveMarkdownViewPath(app, view), expectedPath))
    ) {
      return view;
    }

    if (attempt < attempts - 1) {
      await delay(delayMs);
    }
  }

  return null;
}

async function executeDailyNotesCommand(app) {
  const commands = app && app.commands;
  if (!commands || typeof commands.executeCommandById !== "function") {
    return false;
  }

  try {
    const result = await commands.executeCommandById(DAILY_NOTES_COMMAND_ID);
    return result !== false;
  } catch (error) {
    return false;
  }
}

function parentVaultPath(path) {
  const normalized = normalizeVaultPath(path);
  const slashIndex = normalized.lastIndexOf("/");
  return slashIndex === -1 ? "" : normalized.slice(0, slashIndex);
}

function isMarkdownFileLike(file, expectedPath = "") {
  if (!file || typeof file.path !== "string") {
    return false;
  }

  if (expectedPath && !sameVaultPath(file.path, expectedPath)) {
    return false;
  }

  if (Array.isArray(file.children)) {
    return false;
  }

  return !file.extension || String(file.extension).toLowerCase() === "md";
}

async function ensureVaultFolder(app, folderPath) {
  const folder = normalizeVaultPath(folderPath);
  if (!folder) {
    return true;
  }

  const vault = app && app.vault;
  if (!vault) {
    return false;
  }

  let currentPath = "";
  for (const segment of folder.split("/")) {
    currentPath = currentPath ? `${currentPath}/${segment}` : segment;

    const existing =
      typeof vault.getAbstractFileByPath === "function"
        ? vault.getAbstractFileByPath(currentPath)
        : null;
    if (existing) {
      continue;
    }

    if (typeof vault.createFolder !== "function") {
      return false;
    }

    try {
      await vault.createFolder(currentPath);
    } catch (error) {
      const created =
        typeof vault.getAbstractFileByPath === "function"
          ? vault.getAbstractFileByPath(currentPath)
          : null;
      if (!created) {
        return false;
      }
    }
  }

  return true;
}

async function resolveOrCreateDailyFile(app, path) {
  const vault = app && app.vault;
  if (!vault || typeof vault.getAbstractFileByPath !== "function") {
    return null;
  }

  const dailyPath = normalizeVaultPath(path);
  const existing = vault.getAbstractFileByPath(dailyPath);
  if (existing) {
    return isMarkdownFileLike(existing, dailyPath) ? existing : null;
  }

  if (typeof vault.create !== "function") {
    return null;
  }

  if (!(await ensureVaultFolder(app, parentVaultPath(dailyPath)))) {
    return null;
  }

  try {
    const created = await vault.create(dailyPath, "");
    return isMarkdownFileLike(created, dailyPath) ? created : null;
  } catch (error) {
    const created = vault.getAbstractFileByPath(dailyPath);
    return isMarkdownFileLike(created, dailyPath) ? created : null;
  }
}

async function openVaultFile(app, file) {
  const workspace = app && app.workspace;
  const leaf =
    workspace && typeof workspace.getLeaf === "function"
      ? workspace.getLeaf(false)
      : null;

  if (!leaf || typeof leaf.openFile !== "function") {
    return false;
  }

  try {
    await leaf.openFile(file);
    return true;
  } catch (error) {
    return false;
  }
}

function getMarkdownLeafFile(leaf) {
  const view = leaf && leaf.view;
  if (!(view instanceof MarkdownView)) {
    return null;
  }

  const file = view.file;
  return isMarkdownFileLike(file) ? file : null;
}

function getMarkdownLeafViewByPath(leaf, path = "") {
  const view = leaf && leaf.view;
  if (!(view instanceof MarkdownView) || !view.editor) {
    return null;
  }

  const file = getMarkdownLeafFile(leaf);
  if (!file) {
    return null;
  }

  const expectedPath = normalizeVaultPath(path || "");
  return !expectedPath || sameVaultPath(file.path, expectedPath) ? view : null;
}

function leafIsInSidebar(workspace, leaf) {
  if (!workspace || !leaf || typeof leaf.getRoot !== "function") {
    return false;
  }

  try {
    const root = leaf.getRoot();
    return root === workspace.leftSplit || root === workspace.rightSplit;
  } catch (error) {
    return false;
  }
}

function markdownLeafPathInfo(leaf) {
  if (!leaf) {
    return null;
  }

  const view = leaf.view;
  const loadedFile = view && view.file;
  let viewState = null;
  if (typeof leaf.getViewState === "function") {
    try {
      viewState = leaf.getViewState();
    } catch (error) {
      viewState = null;
    }
  }

  const pinned = (() => {
    try {
      return Boolean(leaf.pinned || (viewState && viewState.pinned));
    } catch (error) {
      return Boolean(viewState && viewState.pinned);
    }
  })();

  if (loadedFile) {
    if (!(view instanceof MarkdownView) || !isMarkdownFileLike(loadedFile)) {
      return null;
    }
    return { path: normalizeVaultPath(loadedFile.path), pinned };
  }

  const stateFile = viewState && viewState.state && viewState.state.file;
  if (
    !viewState ||
    viewState.type !== "markdown" ||
    typeof stateFile !== "string"
  ) {
    return null;
  }

  const path = normalizeVaultPath(stateFile);
  return path ? { path, pinned } : null;
}

function findOpenMarkdownLeafByPath(app, path) {
  const workspace = app && app.workspace;
  const expectedPath = normalizeVaultPath(path);
  if (
    !workspace ||
    !expectedPath ||
    typeof workspace.iterateAllLeaves !== "function"
  ) {
    return null;
  }

  let matchingLeaf = null;
  let matchingRank = Number.POSITIVE_INFINITY;
  const activeLeaf = workspace.activeLeaf;
  try {
    workspace.iterateAllLeaves((leaf) => {
      if (!leaf) {
        return;
      }

      const info = markdownLeafPathInfo(leaf);
      if (!info || !sameVaultPath(info.path, expectedPath)) {
        return;
      }

      const sidebar = leafIsInSidebar(workspace, leaf);
      const rank = sidebar ? (info.pinned ? 2 : 3) : info.pinned ? 0 : 1;
      if (rank < matchingRank || (rank === matchingRank && leaf === activeLeaf)) {
        matchingLeaf = leaf;
        matchingRank = rank;
      }
    });
  } catch (error) {
    return null;
  }

  return matchingLeaf;
}

async function waitForMarkdownLeafViewByPath(leaf, options = {}) {
  const expectedPath = normalizeVaultPath(options.path || "");
  const attempts = Math.max(
    1,
    Math.floor(numericOrDefault(options.attempts, DAILY_OPEN_ATTEMPTS)),
  );
  const delayMs = Math.max(
    0,
    Math.floor(numericOrDefault(options.delayMs, DAILY_OPEN_RETRY_DELAY_MS)),
  );

  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const view = getMarkdownLeafViewByPath(leaf, expectedPath);
    if (view) {
      return view;
    }

    if (attempt < attempts - 1) {
      await delay(delayMs);
    }
  }

  return null;
}

async function activateMarkdownLeaf(app, leaf, options = {}) {
  const workspace = app && app.workspace;
  if (!workspace || !leaf) {
    return null;
  }

  if (
    leaf.isDeferred === true &&
    typeof leaf.loadIfDeferred === "function"
  ) {
    try {
      await leaf.loadIfDeferred();
    } catch (error) {
      // revealLeaf may still load the deferred tab.
    }
  }

  if (typeof workspace.revealLeaf === "function") {
    try {
      await workspace.revealLeaf(leaf);
    } catch (error) {
      // Continue with direct activation when revealing is unavailable or fails.
    }
  }

  let activated = false;
  if (typeof workspace.setActiveLeaf === "function") {
    try {
      await workspace.setActiveLeaf(leaf, { focus: true });
      activated = true;
    } catch (error) {
      try {
        await workspace.setActiveLeaf(leaf);
        activated = true;
      } catch (ignoredError) {
        // Fall through to the leaf-level focus API below.
      }
    }
  }

  if (!activated && typeof leaf.focus === "function") {
    try {
      await leaf.focus();
      activated = true;
    } catch (error) {
      // Report activation failure below.
    }
  }

  if (!activated) {
    return null;
  }

  return (
    (await waitForMarkdownLeafViewByPath(leaf, options)) ||
    waitForActiveMarkdownView(app, options)
  );
}

async function openTodayDailyNoteWithState(app, options = {}) {
  const dailyPath = todayDailyPath(
    options.now || new Date(),
    options.dailyOptions || getDailyNotesOptions(app),
  );
  const attempts = Math.max(
    1,
    Math.floor(numericOrDefault(options.attempts, DAILY_OPEN_ATTEMPTS)),
  );
  const delayMs = Math.max(
    0,
    Math.floor(numericOrDefault(options.delayMs, DAILY_OPEN_RETRY_DELAY_MS)),
  );

  const existingLeaf = findOpenMarkdownLeafByPath(app, dailyPath);
  if (existingLeaf) {
    const view = await activateMarkdownLeaf(app, existingLeaf, {
      path: dailyPath,
      attempts,
      delayMs,
    });
    return view
      ? { view, path: dailyPath, reusedOpenLeaf: true }
      : null;
  }

  if (await executeDailyNotesCommand(app)) {
    const commandView = await waitForActiveMarkdownView(app, {
      path: dailyPath,
      attempts,
      delayMs,
    });
    if (commandView) {
      return { view: commandView, path: dailyPath, reusedOpenLeaf: false };
    }
  }

  const file = await resolveOrCreateDailyFile(app, dailyPath);
  if (!file || !(await openVaultFile(app, file))) {
    return null;
  }

  const view =
    (await waitForActiveMarkdownView(app, {
      path: dailyPath,
      attempts,
      delayMs,
    })) || getActiveMarkdownView(app);
  if (
    !view ||
    !sameVaultPath(getActiveMarkdownViewPath(app, view), dailyPath)
  ) {
    return null;
  }

  return { view, path: dailyPath, reusedOpenLeaf: false };
}

async function openTodayDailyNote(app, options = {}) {
  const result = await openTodayDailyNoteWithState(app, options);
  return result ? result.view : null;
}

function getActiveEditorView(app) {
  const view = getActiveMarkdownView(app);
  if (!view) {
    return null;
  }

  return getEditorViewFromEditor(view.editor);
}

function getEditorViewFromEditor(cm) {
  // Resolve the underlying CodeMirror 6 EditorView from every shape the codebase
  // hands us: the codemirror-vim CM5 adapter (its CM6 view is `.cm6`), an
  // Obsidian Editor (its CM6 view is `.cm`), or a raw EditorView (itself).
  const editorView = cm && (cm.cm6 || cm.cm || cm);
  if (
    !editorView ||
    !editorView.state ||
    !editorView.state.doc ||
    typeof editorView.dispatch !== "function"
  ) {
    return null;
  }

  return editorView;
}

function positionFromCodeMirrorUpdate(update) {
  const state = update && (update.state || (update.view && update.view.state));
  const selection = state && state.selection;
  const mainSelection = selection && selection.main;
  const rawHead = mainSelection && mainSelection.head;
  const head = Math.floor(numericOrDefault(rawHead, Number.NaN));
  const doc = state && state.doc;
  if (!Number.isFinite(head) || !doc) {
    return null;
  }

  if (typeof doc.lineAt === "function") {
    try {
      const line = doc.lineAt(head);
      if (line && Number.isFinite(line.number) && Number.isFinite(line.from)) {
        return normalizeEditorPosition({
          line: line.number - 1,
          ch: head - line.from,
        });
      }
    } catch (error) {
      return null;
    }
  }

  if (typeof doc.toString === "function") {
    const text = doc.toString();
    const safeHead = Math.min(Math.max(head, 0), text.length);
    const beforeCursor = text.slice(0, safeHead);
    const lines = beforeCursor.split("\n");
    const line = lines.length - 1;
    const lastLine = lines[line] || "";
    return {
      line,
      ch: lastLine.endsWith("\r") ? lastLine.length - 1 : lastLine.length,
    };
  }

  return null;
}

function getEditorLastLine(cm) {
  if (!cm) {
    return null;
  }

  if (typeof cm.lastLine === "function") {
    const line = Math.floor(numericOrDefault(cm.lastLine(), Number.NaN));
    if (Number.isFinite(line)) {
      return Math.max(line, 0);
    }
  }

  if (typeof cm.lineCount === "function") {
    const count = Math.floor(numericOrDefault(cm.lineCount(), Number.NaN));
    if (Number.isFinite(count)) {
      return Math.max(count - 1, 0);
    }
  }

  if (typeof cm.getValue === "function") {
    return Math.max(String(cm.getValue()).split(/\r?\n/).length - 1, 0);
  }

  return null;
}

function getEditorLineText(cm, line) {
  if (!cm) {
    return null;
  }

  if (typeof cm.getLine === "function") {
    const text = cm.getLine(line);
    return text === null || text === undefined ? "" : String(text);
  }

  if (typeof cm.getValue === "function") {
    const lines = String(cm.getValue()).split(/\r?\n/);
    return lines[line] === undefined ? "" : lines[line];
  }

  return null;
}

function clampEditorPosition(cm, position) {
  const normalized = normalizeEditorPosition(position);
  if (!normalized) {
    return null;
  }

  const lastLine = getEditorLastLine(cm);
  const line =
    lastLine === null ? normalized.line : Math.min(normalized.line, lastLine);
  const lineText = getEditorLineText(cm, line);
  const ch =
    lineText === null ? normalized.ch : Math.min(normalized.ch, lineText.length);
  return { line, ch };
}

function getScrollDOMMaxScrollTop(scrollDOM) {
  if (!scrollDOM) {
    return Number.POSITIVE_INFINITY;
  }

  const scrollHeight = finiteNumberOrNull(scrollDOM.scrollHeight);
  const clientHeight = finiteNumberOrNull(scrollDOM.clientHeight);
  if (scrollHeight === null || clientHeight === null || clientHeight <= 0) {
    return Number.POSITIVE_INFINITY;
  }
  return Math.max(0, scrollHeight - clientHeight);
}

function getScrollDOMMaxScrollLeft(scrollDOM) {
  if (!scrollDOM) {
    return Number.POSITIVE_INFINITY;
  }

  const scrollWidth = finiteNumberOrNull(scrollDOM.scrollWidth);
  const clientWidth = finiteNumberOrNull(scrollDOM.clientWidth);
  if (scrollWidth === null || clientWidth === null || clientWidth <= 0) {
    return Number.POSITIVE_INFINITY;
  }
  return Math.max(0, scrollWidth - clientWidth);
}

function setScrollDOMPosition(scrollDOM, scrollTop, scrollLeft = null) {
  if (!scrollDOM) {
    return false;
  }

  const targetScrollTop = clampNumber(
    scrollTop,
    0,
    getScrollDOMMaxScrollTop(scrollDOM),
  );
  const rawScrollLeft =
    finiteNumberOrNull(scrollLeft) ?? finiteNumberOrNull(scrollDOM.scrollLeft) ?? 0;
  const targetScrollLeft = clampNumber(
    rawScrollLeft,
    0,
    getScrollDOMMaxScrollLeft(scrollDOM),
  );

  if (typeof scrollDOM.scrollTo === "function") {
    try {
      scrollDOM.scrollTo({ top: targetScrollTop, left: targetScrollLeft });
      return true;
    } catch (error) {
      // Fall through to direct assignment.
    }
  }

  try {
    scrollDOM.scrollTop = targetScrollTop;
    scrollDOM.scrollLeft = targetScrollLeft;
    return true;
  } catch (error) {
    return false;
  }
}

function editorViewPositionFromLineCh(editorView, line, ch) {
  const doc = editorView && editorView.state && editorView.state.doc;
  if (!doc || typeof doc.line !== "function") {
    return null;
  }

  const lineCount =
    Number.isInteger(doc.lines) && doc.lines > 0 ? doc.lines : 1;
  const safeLine = Math.min(
    Math.max(Math.floor(numericOrDefault(line, 0)), 0),
    lineCount - 1,
  );

  let lineInfo;
  try {
    lineInfo = doc.line(safeLine + 1);
  } catch (error) {
    return null;
  }

  if (
    !lineInfo ||
    !Number.isInteger(lineInfo.from) ||
    !Number.isInteger(lineInfo.to)
  ) {
    return null;
  }

  const maxCh = Math.max(lineInfo.to - lineInfo.from, 0);
  const safeCh = Math.min(
    Math.max(Math.floor(numericOrDefault(ch, 0)), 0),
    maxCh,
  );
  return lineInfo.from + safeCh;
}

function centerEditorViewOnPosition(editorView, line, ch) {
  if (
    !editorView ||
    typeof editorView.dispatch !== "function" ||
    typeof EditorView.scrollIntoView !== "function"
  ) {
    return false;
  }

  const position = editorViewPositionFromLineCh(editorView, line, ch);
  if (position === null) {
    return false;
  }

  try {
    editorView.dispatch({
      effects: EditorView.scrollIntoView(position, {
        y: "center",
        x: "nearest",
      }),
    });
  } catch (error) {
    return false;
  }

  return true;
}

function scrollEditorIntoView(cm, line, ch) {
  if (cm && typeof cm.scrollIntoView === "function") {
    cm.scrollIntoView({ line, ch });
    return true;
  }

  return false;
}

function focusEditor(cm) {
  if (!cm) {
    return false;
  }

  if (typeof cm.focus === "function") {
    try {
      cm.focus();
      return true;
    } catch (error) {
      // Fall through to the underlying CodeMirror view when available.
    }
  }

  const editorView = getEditorViewFromEditor(cm);
  if (editorView && typeof editorView.focus === "function") {
    try {
      editorView.focus();
      return true;
    } catch (error) {
      return false;
    }
  }

  return false;
}

function setEditorCursor(cm, line, ch, options = {}) {
  if (!cm || typeof cm.setCursor !== "function") {
    return false;
  }

  try {
    cm.setCursor(line, ch);
  } catch (error) {
    cm.setCursor({ line, ch });
  }

  if (options.scroll !== false) {
    scrollEditorIntoView(cm, line, ch);
  }

  return true;
}

// Defer `callback` past the current synchronous turn (e.g. the codemirror-vim
// command cycle) so any scroll it dispatches runs after Vim's own trailing
// "keep cursor visible" scroll. Returns a handle that cancelDeferred can clear.
function deferToNextFrame(callback) {
  if (
    typeof window !== "undefined" &&
    typeof window.requestAnimationFrame === "function"
  ) {
    return { type: "raf", handle: window.requestAnimationFrame(callback) };
  }

  return { type: "timeout", handle: setTimeout(callback, 0) };
}

function cancelDeferred(deferred) {
  if (!deferred) {
    return;
  }

  if (
    deferred.type === "raf" &&
    typeof window !== "undefined" &&
    typeof window.cancelAnimationFrame === "function"
  ) {
    window.cancelAnimationFrame(deferred.handle);
    return;
  }

  if (deferred.type === "timeout") {
    clearTimeout(deferred.handle);
  }
}

function replaceEditorLine(cm, line, oldLineText, newLineText) {
  if (!cm || typeof cm.replaceRange !== "function") {
    return false;
  }

  cm.replaceRange(
    newLineText,
    { line, ch: 0 },
    { line, ch: oldLineText.length },
  );
  return true;
}

// ---- src/050-plan-budget.js ----
// --- Plan budget ----------------------------------------------------------
// JavaScript mirror of docs/plan.md (bob-cli), the authoritative definition.
// The Rust engine (src/native/plan_budget/) implements the same rules; both
// test against the same conformance examples. Field names are camelCase here.

const PLAN_UNNAMED_THEME = "(unnamed)";
const PLAN_CONFIG_RELATIVE_PATH = "bob/config.yml";
const PLAN_TASKS_PLUGIN_ID = "obsidian-tasks-plugin";
const PLAN_LINT_THEME_CAP = "plan_theme_cap_exceeded";
const PLAN_LINT_LINK_CAP = "plan_link_cap_exceeded";
const PLAN_LINT_DUPLICATE_NAME = "duplicate_open_pomodoro_name";
const PLAN_LINT_INVENTORY_LABEL = "inventory_label_open";
const PLAN_LINT_SUBHEADING = "subheading_in_pomodoros";
const PLAN_LINT_NEXT_CAP = "next_cap_exceeded";
const PLAN_LINT_PENDING_CAP = "pending_cap_exceeded";
// Emitted only by the bob-ledger-tools `bob-plan` block: `bob plan` has
// no native READY count.
const PLAN_LINT_READY_CAP = "ready_cap_exceeded";
const PLAN_DAILY_PATH_RE = /(^|\/)\d{4}\/\d{8}\.md$/;
const PLAN_ENTRY_RE = /^- \[([^\]])\]/;
const PLAN_PLACEHOLDER_RE = /^\([ \t]*\)/;
const PLAN_BLOCK_ID_RE = /^[A-Za-z0-9-]+$/;
const PLAN_ATX_RE = /^(?: {0,3})(#{1,6})(?:\s|$)/;
// This string must stay identical to the Tasks plugin's own event: the
// installed bundle (`~/bob/.obsidian/plugins/obsidian-tasks-plugin/main.js`,
// `TasksEvents.onReloadOpenSearchResults`) subscribes under exactly this
// name, and every open Tasks query re-reads only when it fires.
const TODAY_RELOAD_EVENT = "obsidian-tasks-plugin:reload-open-search-results";

function defaultPlanCaps() {
  return {
    maxThemes: 3,
    maxLinks: 10,
    maxNext: 15,
    maxPending: 10,
    maxReady: 100,
    maxReadyPerNote: 5,
    strict: false,
    exempt: ["GTD"],
    inventoryLabels: ["LATER", "MISC", "NEW FEATURES", "SASE"],
  };
}

const PLAN_U32_MAX = 4294967295;

function planCapOrDefault(value, fallback) {
  return Number.isInteger(value) && value >= 1 ? value : fallback;
}

function planReadyCapOrDefault(value, fallback) {
  return Number.isInteger(value) && value >= 1 && value <= PLAN_U32_MAX
    ? value
    : fallback;
}

// Per-note Ready cap: an integer 1–999 (`docs/plan.md`, "Ready cap per
// note"), unlike the unbounded lane caps above.
function planPerNoteCapOrDefault(value, fallback) {
  return Number.isInteger(value) && value >= 1 && value <= 999
    ? value
    : fallback;
}

function planStringListOrDefault(value, fallback) {
  if (!Array.isArray(value)) {
    return [...fallback];
  }
  const out = [];
  for (const item of value) {
    if (typeof item !== "string" || !item.trim()) {
      return [...fallback];
    }
    out.push(item.trim());
  }
  return out;
}

// Case-insensitive component key: collapsed whitespace, lowercased.
function normalizePlanComponent(value) {
  return String(value || "")
    .split(/\s+/)
    .filter((part) => part.length > 0)
    .join(" ")
    .toLowerCase();
}

function splitPlanComponents(name) {
  return String(name || "")
    .split("+")
    .map((component) => component.trim())
    .filter((component) => component.length > 0);
}

// Normalize a camelCase caps object, substituting defaults for anything
// missing or invalid. Never throws.
function effectivePlanCaps(caps) {
  const defaults = defaultPlanCaps();
  const raw =
    caps && typeof caps === "object" && !Array.isArray(caps) ? caps : {};
  return {
    maxThemes: planCapOrDefault(raw.maxThemes, defaults.maxThemes),
    maxLinks: planCapOrDefault(raw.maxLinks, defaults.maxLinks),
    maxNext: planCapOrDefault(raw.maxNext, defaults.maxNext),
    maxPending: planCapOrDefault(raw.maxPending, defaults.maxPending),
    maxReady: planReadyCapOrDefault(raw.maxReady, defaults.maxReady),
    maxReadyPerNote: planPerNoteCapOrDefault(
      raw.maxReadyPerNote,
      defaults.maxReadyPerNote,
    ),
    strict:
      typeof raw.strict === "boolean" ? raw.strict : defaults.strict,
    exempt: planStringListOrDefault(raw.exempt, defaults.exempt),
    inventoryLabels: planStringListOrDefault(
      raw.inventoryLabels,
      defaults.inventoryLabels,
    ),
  };
}

// Read the `plan:` block out of a parsed config file (snake_case keys, with
// camelCase tolerated). Unknown keys stay ignored. A missing block means the
// defaults; any invalid value falls back to the full default block, as Rust
// does. Use coercePlanCaps when the invalid flag matters.
function parsePlanCaps(yamlObject) {
  return coercePlanCaps(planCapsBlock(yamlObject)).caps;
}

function planCapsBlock(yamlObject) {
  if (
    !yamlObject ||
    typeof yamlObject !== "object" ||
    Array.isArray(yamlObject)
  ) {
    return {};
  }
  const block = yamlObject.plan;
  if (!block || typeof block !== "object" || Array.isArray(block)) {
    return {};
  }
  return block;
}

function coercePlanCaps(block) {
  const defaults = defaultPlanCaps();
  const raw =
    block && typeof block === "object" && !Array.isArray(block) ? block : {};
  const pick = (snake, camel) =>
    raw[snake] !== undefined ? raw[snake] : raw[camel];
  let invalid = false;
  const cap = (snake, camel, fallback) => {
    const value = pick(snake, camel);
    if (value === undefined || value === null) {
      return fallback;
    }
    if (!Number.isInteger(value) || value < 1) {
      invalid = true;
      return fallback;
    }
    return value;
  };
  const readyCap = (snake, camel, fallback) => {
    const value = pick(snake, camel);
    if (value === undefined || value === null) {
      return fallback;
    }
    if (!Number.isInteger(value) || value < 1 || value > PLAN_U32_MAX) {
      invalid = true;
      return fallback;
    }
    return value;
  };
  const perNoteCap = (snake, camel, fallback) => {
    const value = pick(snake, camel);
    if (value === undefined || value === null) {
      return fallback;
    }
    if (!Number.isInteger(value) || value < 1 || value > 999) {
      invalid = true;
      return fallback;
    }
    return value;
  };
  const list = (snake, camel, fallback) => {
    const value = pick(snake, camel);
    if (value === undefined) {
      return [...fallback];
    }
    if (!Array.isArray(value)) {
      invalid = true;
      return [...fallback];
    }
    const out = [];
    for (const item of value) {
      if (typeof item !== "string" || !item.trim()) {
        invalid = true;
        return [...fallback];
      }
      out.push(item.trim());
    }
    return out;
  };
  const strictValue = pick("strict", "strict");
  let strict = defaults.strict;
  if (strictValue !== undefined) {
    if (typeof strictValue !== "boolean") {
      invalid = true;
    } else {
      strict = strictValue;
    }
  }
  // Unknown keys (including a legacy `max_now`) stay ignored, so an old
  // config loads without error.
  const caps = {
    maxThemes: cap("max_themes", "maxThemes", defaults.maxThemes),
    maxLinks: cap("max_links", "maxLinks", defaults.maxLinks),
    maxNext: cap("max_next", "maxNext", defaults.maxNext),
    maxPending: cap("max_pending", "maxPending", defaults.maxPending),
    maxReady: readyCap("max_ready", "maxReady", defaults.maxReady),
    maxReadyPerNote: perNoteCap(
      "max_ready_per_note",
      "maxReadyPerNote",
      defaults.maxReadyPerNote,
    ),
    strict,
    exempt: list("exempt", "exempt", defaults.exempt),
    inventoryLabels: list(
      "inventory_labels",
      "inventoryLabels",
      defaults.inventoryLabels,
    ),
  };
  // Like Rust, any invalid value falls back to the full default block.
  if (invalid) {
    return { caps: { ...defaults }, invalid: true };
  }
  return { caps, invalid: false };
}

function emptyPlanBudget(caps) {
  const effective = effectivePlanCaps(caps);
  return {
    hasSection: false,
    themes: { count: 0, cap: effective.maxThemes, over: false },
    links: { count: 0, cap: effective.maxLinks, over: false },
    status: "ok",
    themeNames: [],
    entries: [],
    warnings: [],
  };
}

function planFenceMarker(line) {
  const text = String(line || "");
  let indent = 0;
  while (text[indent] === " ") {
    indent += 1;
  }
  if (indent > 3) {
    return null;
  }
  const rest = text.slice(indent);
  const char = rest[0];
  if (char !== "`" && char !== "~") {
    return null;
  }
  let length = 0;
  while (rest[length] === char) {
    length += 1;
  }
  return length >= 3 ? { char, length } : null;
}

function planClosesFence(line, open) {
  const marker = planFenceMarker(line);
  if (!marker) {
    return false;
  }
  const trimmed = String(line || "").trimStart();
  return (
    marker.char === open.char &&
    marker.length >= open.length &&
    trimmed.slice(marker.length).trim() === ""
  );
}

function planFencedLines(lines, start, end) {
  const fenced = new Set();
  let open = null;
  for (let index = start; index <= end; index += 1) {
    const line = lines[index];
    if (open) {
      fenced.add(index);
      if (planClosesFence(line, open)) {
        open = null;
      }
    } else {
      const marker = planFenceMarker(line);
      if (marker) {
        fenced.add(index);
        open = marker;
      }
    }
  }
  return fenced;
}

function planAtxLevel(line) {
  const match = PLAN_ATX_RE.exec(String(line || ""));
  return match ? match[1].length : null;
}

// Ledger lines: from the `## Pomodoros` heading up to the next `## `
// heading. Frontmatter and fenced code blocks are skipped. Returns
// `{ start, end }` 0-based inclusive, or null.
function planSectionRange(lines) {
  if (!Array.isArray(lines)) {
    return null;
  }
  let frontmatterEnd = -1;
  if (String(lines[0] || "").trimEnd() === "---") {
    for (let index = 1; index < lines.length; index += 1) {
      if (String(lines[index] || "").trimEnd() === "---") {
        frontmatterEnd = index;
        break;
      }
    }
  }
  let sectionStart = -1;
  let fence = null;
  for (let index = 0; index < lines.length; index += 1) {
    if (index <= frontmatterEnd) {
      continue;
    }
    const line = String(lines[index] || "");
    if (fence) {
      if (planClosesFence(line, fence)) {
        fence = null;
      }
      continue;
    }
    const marker = planFenceMarker(line);
    if (marker) {
      fence = marker;
      continue;
    }
    if (sectionStart === -1) {
      if (/^##\s+Pomodoros(?:\s|$)/.test(line)) {
        sectionStart = index + 1;
      }
    } else if (/^##\s/.test(line)) {
      return { start: sectionStart, end: index - 1 };
    }
  }
  return sectionStart === -1
    ? null
    : { start: sectionStart, end: lines.length - 1 };
}

function planNormalizeHhmm(value) {
  const digits = String(value || "").replace(/:/g, "");
  if (!/^\d{4}$/.test(digits)) {
    return null;
  }
  const hours = Number.parseInt(digits.slice(0, 2), 10);
  const minutes = Number.parseInt(digits.slice(2), 10);
  if (hours > 23 || minutes > 59) {
    return null;
  }
  return digits;
}

function planParseParentheticalTime(inside) {
  const dash = String(inside || "").indexOf("-");
  if (dash === -1) {
    return null;
  }
  let rawStart = String(inside).slice(0, dash).trim();
  let bold = false;
  if (rawStart.startsWith("**")) {
    bold = true;
    rawStart = rawStart.slice(2).trim();
  }
  const start = planNormalizeHhmm(rawStart);
  if (!start) {
    return null;
  }
  const rawEnd = String(inside).slice(dash + 1).trimStart();
  const endMatch = /^[0-9:]+/.exec(rawEnd);
  if (!endMatch) {
    return null;
  }
  const end = planNormalizeHhmm(endMatch[0]);
  if (!end) {
    return null;
  }
  let rest = rawEnd.slice(endMatch[0].length);
  if (bold) {
    if (!rest.startsWith("**")) {
      return null;
    }
    rest = rest.slice(2);
  } else if (rest.startsWith("**")) {
    return null;
  }
  if (rest !== "" && !/^\s/.test(rest)) {
    return null;
  }
  return { start, end };
}

// Leading `()` placeholder or `(time-range)` of an entry body, mirroring
// capture_pomodoros::parse_entry_body. A name only exists after one of these.
function planLeadingRange(body) {
  const text = String(body || "");
  const placeholder = PLAN_PLACEHOLDER_RE.exec(text);
  if (placeholder) {
    return {
      length: placeholder[0].length,
      timeRange: null,
      placeholder: true,
    };
  }
  if (!text.startsWith("(")) {
    return { length: null, timeRange: null, placeholder: false };
  }
  const close = text.indexOf(")", 1);
  if (close === -1) {
    return { length: null, timeRange: null, placeholder: false };
  }
  const parsed = planParseParentheticalTime(text.slice(1, close));
  if (!parsed) {
    return { length: null, timeRange: null, placeholder: false };
  }
  return {
    length: close + 1,
    timeRange: `${parsed.start}-${parsed.end}`,
    placeholder: false,
  };
}

// The text after `—` (em dash) that follows the leading placeholder or time
// range. A merged name (`BOB + DECKS`) is split by the caller.
function planParseNameTail(remaining) {
  const trimmed = String(remaining || "").replace(/^[ \t]+/, "");
  if (!trimmed.startsWith("—")) {
    return null;
  }
  const name = trimmed.slice(1).replace(/^[ \t]+/, "").trim();
  return name ? name : null;
}

function planParseEntry(line) {
  const text = String(line || "");
  const match = PLAN_ENTRY_RE.exec(text);
  if (!match) {
    return null;
  }
  const afterBracket = text.slice(match[0].length);
  if (!/^\s/.test(afterBracket)) {
    return null;
  }
  const body = afterBracket.trim();
  const checkbox = String(match[1] || "").trim();
  if (/^x$/i.test(checkbox)) {
    return { state: "completed", body };
  }
  if (checkbox === "-") {
    return { state: "cancelled", body };
  }
  return { state: "open", body };
}

// Inner spans of `~~…~~` struck pairs on one line.
function planStruckInnerSpans(line) {
  const text = String(line || "");
  const marks = [];
  let base = 0;
  let rest = text;
  for (;;) {
    const found = rest.indexOf("~~");
    if (found === -1) {
      break;
    }
    marks.push(base + found);
    base += found + 2;
    rest = text.slice(base);
  }
  const spans = [];
  for (let index = 0; index + 1 < marks.length; index += 2) {
    spans.push([marks[index] + 2, marks[index + 1]]);
  }
  return spans;
}

// Block links `[[target#^id]]` (also `![[…]]` and `[[…|alias]]`, with or
// without a trailing `#` move-only marker) outside `~~…~~` struck spans.
// An empty target, the daily note's vault-relative path without `.md`, and
// its basename all canonicalize to the daily path itself (rule 6).
function planCanonicalTarget(target, dailyPath) {
  const name = String(target || "");
  if (!dailyPath) {
    return name;
  }
  const daily = String(dailyPath).replace(/\.md$/, "");
  if (!daily) {
    return name;
  }
  const basename = daily.split("/").pop();
  if (name === "" || name === daily || name === basename) {
    return daily;
  }
  return name;
}

function planBlockLinks(line, dailyPath) {
  const text = String(line || "");
  // Managed dependency rows are never Task Links. Keep the budget scanner
  // aligned with Rust for both Depends-On and generated BLOCKS children.
  try {
    const dependency = typeof parseDependencyLine === "function" ? parseDependencyLine(text) : null;
    const blocks = typeof parseBlocksLine === "function" ? parseBlocksLine(text) : null;
    const relation = typeof isTaskRelationLine === "function" ? isTaskRelationLine(text) : false;
    if (
      (dependency && dependency.verdict !== "not-a-line") ||
      (blocks && blocks.verdict !== "not-a-line") ||
      relation
    ) {
      return [];
    }
  } catch (error) {
    // A failed recogniser must not suppress ordinary Task Link counting.
  }
  const struck = planStruckInnerSpans(text);
  const links = [];
  let base = 0;
  let rest = text;
  for (;;) {
    const open = rest.indexOf("[[");
    if (open === -1) {
      break;
    }
    const absoluteOpen = base + open;
    const afterOpen = rest.slice(open + 2);
    const close = afterOpen.indexOf("]]");
    if (close === -1) {
      break;
    }
    let inside = afterOpen.slice(0, close);
    let linkEnd = absoluteOpen + 2 + close + 2;
    if (rest.slice(open + 2 + close + 2).startsWith("#")) {
      linkEnd += 1;
    }
    if (inside.endsWith("#")) {
      inside = inside.slice(0, -1);
    }
    const pipe = inside.indexOf("|");
    const target = pipe === -1 ? inside : inside.slice(0, pipe);
    const caret = target.indexOf("#^");
    if (caret !== -1) {
      const blockId = target.slice(caret + 2).trim();
      if (
        blockId &&
        PLAN_BLOCK_ID_RE.test(blockId) &&
        !struck.some(
          ([start, end]) => absoluteOpen >= start && linkEnd <= end,
        )
      ) {
        let name = target.slice(0, caret).trim();
        if (name.endsWith(".md")) {
          name = name.slice(0, -3);
        }
        links.push([planCanonicalTarget(name, dailyPath), blockId]);
      }
    }
    base = linkEnd;
    rest = text.slice(base);
  }
  return links;
}

function planMeter(count, cap) {
  return { count, cap, over: count > cap };
}

// Pure ledger budget and lint engine implementing docs/plan.md rules 1–9.
function computePlanBudget(content, caps, dailyPath) {
  const effective = effectivePlanCaps(caps);
  const lines = String(content || "").replace(/\r\n/g, "\n").split("\n");
  const section = planSectionRange(lines);
  if (!section) {
    return emptyPlanBudget(effective);
  }
  const fenced = planFencedLines(lines, section.start, section.end);
  const warnings = [];
  for (let index = section.start; index <= section.end; index += 1) {
    if (fenced.has(index)) {
      continue;
    }
    const level = planAtxLevel(lines[index]);
    if (level !== null && level >= 3) {
      warnings.push({
        code: PLAN_LINT_SUBHEADING,
        message:
          "subheading inside the Pomodoros section splits time totals",
        line: index + 1,
      });
    }
  }

  const scanned = [];
  for (let index = section.start; index <= section.end; index += 1) {
    if (fenced.has(index)) {
      continue;
    }
    const line = String(lines[index] || "");
    if (line.startsWith(" ") || line.startsWith("\t")) {
      continue;
    }
    const parsed = planParseEntry(line);
    if (!parsed) {
      continue;
    }
    if (parsed.state === "cancelled") {
      continue;
    }
    const leading = planLeadingRange(parsed.body);
    const name =
      leading.length === null
        ? null
        : planParseNameTail(parsed.body.slice(leading.length));
    scanned.push({
      line: index + 1,
      state: parsed.state,
      name,
      timeRange: leading.timeRange,
      placeholder: leading.placeholder,
      isCurrent: false,
    });
  }

  const timedOpen = scanned.filter(
    (entry) => entry.state === "open" && entry.timeRange !== null,
  );
  if (timedOpen.length === 1) {
    timedOpen[0].isCurrent = true;
  }

  const exempt = new Set(
    effective.exempt.map((value) => normalizePlanComponent(value)),
  );
  const inventory = new Set(
    effective.inventoryLabels.map((value) => normalizePlanComponent(value)),
  );
  const entryLines = new Set(scanned.map((entry) => entry.line));

  const entries = [];
  const themeNames = [];
  const themeKeys = new Set();
  const seenThemes = new Map();
  const inventoryWarned = new Set();
  const seenLinks = new Set();
  let unnamedCounted = false;

  for (const entry of scanned) {
    if (entry.state !== "open") {
      continue;
    }
    const components = entry.name ? splitPlanComponents(entry.name) : [];
    const keys = components.map((component) =>
      normalizePlanComponent(component),
    );
    const exemptEntry =
      keys.length > 0 && keys.every((key) => exempt.has(key));
    let entryLinks = [];
    if (!exemptEntry) {
      for (
        let offset = 0;
        entry.line + offset <= section.end;
        offset += 1
      ) {
        const index = entry.line + offset;
        if (entryLines.has(index + 1)) {
          break;
        }
        if (fenced.has(index)) {
          continue;
        }
        const line = String(lines[index] || "");
        if (line !== "" && !line.startsWith(" ") && !line.startsWith("\t")) {
          break;
        }
        for (const link of planBlockLinks(line, dailyPath)) {
          entryLinks.push(link);
        }
      }
    }
    if (components.length === 0 && entryLinks.length === 0) {
      // An empty `()` placeholder never counts.
      continue;
    }

    const distinctLinks = new Set();
    if (!exemptEntry) {
      for (const [target, blockId] of entryLinks) {
        const key = `${target}\u0000${blockId}`;
        distinctLinks.add(key);
        seenLinks.add(key);
      }
    }

    for (let index = 0; index < components.length; index += 1) {
      const component = components[index];
      const key = keys[index];
      if (exempt.has(key)) {
        continue;
      }
      if (seenThemes.has(key)) {
        warnings.push({
          code: PLAN_LINT_DUPLICATE_NAME,
          message:
            `${component} is open in more than one Pomodoro ` +
            `(lines ${seenThemes.get(key)} and ${entry.line})`,
          line: entry.line,
        });
      } else {
        seenThemes.set(key, entry.line);
      }
      if (inventory.has(key) && !inventoryWarned.has(key)) {
        inventoryWarned.add(key);
        warnings.push({
          code: PLAN_LINT_INVENTORY_LABEL,
          message: `${component} is an inventory label, not a theme`,
          line: entry.line,
        });
      }
    }

    if (components.length === 0 && !unnamedCounted) {
      unnamedCounted = true;
      themeKeys.add(PLAN_UNNAMED_THEME);
      themeNames.push(PLAN_UNNAMED_THEME);
    }
    for (let index = 0; index < components.length; index += 1) {
      const component = components[index];
      const key = keys[index];
      if (exempt.has(key) || themeKeys.has(key)) {
        continue;
      }
      themeKeys.add(key);
      themeNames.push(component);
    }

    const row = {
      line: entry.line,
      name: entry.name === null ? PLAN_UNNAMED_THEME : entry.name,
      components,
      exempt: exemptEntry,
      running: entry.isCurrent,
      highlight: false,
      links: distinctLinks.size,
    };
    if (entry.timeRange !== null) {
      row.timeRange = entry.timeRange;
    }
    entries.push(row);
  }

  const highlightIndex = entries.findIndex((entry) => !entry.exempt);
  if (highlightIndex !== -1) {
    entries[highlightIndex].highlight = true;
  }

  const themes = planMeter(themeNames.length, effective.maxThemes);
  const links = planMeter(seenLinks.size, effective.maxLinks);
  const status = themes.over || links.over ? "over" : "ok";
  if (themes.over) {
    warnings.push({
      code: PLAN_LINT_THEME_CAP,
      message: `today's plan has ${themes.count}/${themes.cap} themes`,
    });
  }
  if (links.over) {
    warnings.push({
      code: PLAN_LINT_LINK_CAP,
      message: `today's plan has ${links.count}/${links.cap} links`,
    });
  }

  return {
    hasSection: true,
    themes,
    links,
    status,
    themeNames,
    entries,
    warnings,
  };
}

// ---- src/060-today.js ----
// --- Today (ledger-derived) -------------------------------------------------
// JavaScript mirror of `today_links` in `src/native/plan_budget/today.rs`,
// which is exactly the `=x` / start lineup rule
// (`list_queued_links` in `src/native/capture_pomodoro_start.rs`):
// a direct child bullet at an open entry's first child indentation whose
// body, after stripping Pomodoro markers, is exactly one plain
// `[[target#^id]]` or embedded `![[target#^id]]` block link — not struck
// through and not fenced. `docs/plan.md` ("Today conformance examples")
// is the shared test vector source for both implementations.

function todayIndentLen(line) {
  const text = String(line || "");
  let indent = 0;
  while (text[indent] === " " || text[indent] === "\t") {
    indent += 1;
  }
  return indent;
}

function todayMarkerLen(afterIndent) {
  const text = String(afterIndent || "");
  const first = text[0];
  if (first === "-" || first === "*" || first === "+") {
    return 1;
  }
  if (first >= "0" && first <= "9") {
    let digits = 0;
    while (
      digits < text.length &&
      text[digits] >= "0" &&
      text[digits] <= "9"
    ) {
      digits += 1;
    }
    const closer = text[digits];
    if (closer === "." || closer === ")") {
      return digits + 1;
    }
  }
  return null;
}

// An indented list line (a possible sub-bullet): indented, with a valid
// marker followed by nothing or whitespace.
function todayIsSubBulletLine(line) {
  const text = String(line || "");
  if (text.trim() === "") {
    return false;
  }
  const indent = todayIndentLen(text);
  if (indent === 0) {
    return false;
  }
  const markerLen = todayMarkerLen(text.slice(indent));
  if (markerLen === null) {
    return false;
  }
  const rest = text.slice(indent + markerLen);
  return rest === "" || rest[0] === " " || rest[0] === "\t";
}

// The bullet body with trailing whitespace trimmed, or null when the line
// is not a well-formed bullet.
function todayBulletBody(line) {
  const text = String(line || "");
  const indent = todayIndentLen(text);
  const markerLen = todayMarkerLen(text.slice(indent));
  if (markerLen === null) {
    return null;
  }
  const afterMarker = text.slice(indent + markerLen);
  if (afterMarker !== "" && afterMarker[0] !== " " && afterMarker[0] !== "\t") {
    return null;
  }
  const bodyStart = indent + markerLen + (afterMarker === "" ? 0 : 1);
  const trimmed = text.slice(bodyStart).replace(/[ \t]+$/, "");
  if (trimmed === "") {
    return null;
  }
  return { bodyStart, bodyEnd: bodyStart + trimmed.length, body: trimmed };
}

function todayStripWrappingQuotes(value) {
  const text = String(value || "");
  if (text.length >= 2) {
    const first = text[0];
    const last = text[text.length - 1];
    if (
      (first === '"' && last === '"') ||
      (first === "'" && last === "'")
    ) {
      return text.slice(1, -1).trim();
    }
  }
  return text;
}

function todayIsUriScheme(path) {
  const colon = String(path || "").indexOf(":");
  if (colon === -1) {
    return false;
  }
  const scheme = String(path).slice(0, colon);
  if (!scheme || !/[A-Za-z]/.test(scheme[0])) {
    return false;
  }
  return /^[A-Za-z][A-Za-z0-9+.-]*$/.test(scheme);
}

// One `[[target#^id]]` token on a line, mirroring
// `wikilink_tokens`/`parse_block_target`: the alias (`|…`) is ignored,
// the block ID must match `PLAN_BLOCK_ID_RE`, and paths holding `#`, `^`,
// or a URI scheme never parse.
function todayWikilinkTokens(line) {
  const text = String(line || "");
  const tokens = [];
  let cursor = 0;
  for (;;) {
    const open = text.indexOf("[[", cursor);
    if (open === -1) {
      break;
    }
    const innerStart = open + 2;
    const relativeClose = text.slice(innerStart).indexOf("]]");
    if (relativeClose === -1) {
      break;
    }
    const close = innerStart + relativeClose + 2;
    const inner = text.slice(innerStart, innerStart + relativeClose);
    const rawTarget = todayStripWrappingQuotes(
      inner.split("|")[0] || "",
    ).trim();
    const caret = rawTarget.indexOf("#^");
    if (caret !== -1) {
      const rawPath = rawTarget.slice(0, caret).trim();
      const blockId = rawTarget.slice(caret + 2).trim();
      if (
        blockId &&
        PLAN_BLOCK_ID_RE.test(blockId) &&
        !rawPath.includes("#") &&
        !rawPath.includes("^") &&
        !todayIsUriScheme(rawPath)
      ) {
        let pathPart = rawPath;
        if (/\.md$/i.test(pathPart)) {
          pathPart = pathPart.slice(0, -3);
        }
        const embedded = open > 0 && text[open - 1] === "!";
        tokens.push({
          start: embedded ? open - 1 : open,
          end: close,
          embedded,
          pathPart,
          blockId,
        });
      }
    }
    cursor = close;
  }
  return tokens;
}

// The trimmed body is exactly one plain or embedded block link, mirroring
// `bare_plain_link`/`bare_embedded_link` (a trailing `#` move-only marker
// disqualifies, exactly as in Rust).
function todayBareLink(body) {
  const text = String(body || "");
  const tokens = todayWikilinkTokens(text);
  if (tokens.length !== 1) {
    return null;
  }
  const token = tokens[0];
  return token.start === 0 && token.end === text.length ? token : null;
}

// A dedicated Task Link: strip leading Pomodoro markers (the Strip policy
// only removes markers directly before the link), then require a bare link
// outside `~~…~~` struck spans.
function todayLinkFromBody(body) {
  const stripped = String(body || "").replace(/^(?:🍅\s*)+/, "");
  if (stripped === "") {
    return null;
  }
  const token = todayBareLink(stripped);
  if (!token) {
    return null;
  }
  const struck = planStruckInnerSpans(stripped);
  if (
    struck.some(([start, end]) => token.start >= start && token.end <= end)
  ) {
    return null;
  }
  return token;
}

function emptyTodayCache() {
  return {
    date: null,
    dailyPath: null,
    keys: [],
    rank: new Map(),
    details: new Map(),
    detailsSignature: "",
    idsByPath: new Map(),
  };
}

function todayEachOpenEntry(content, visit) {
  if (typeof visit !== "function") {
    return;
  }
  const lines = String(content || "").replace(/\r\n/g, "\n").split("\n");
  const section = planSectionRange(lines);
  if (!section) {
    return;
  }
  const fenced = planFencedLines(lines, section.start, section.end);
  for (let index = section.start; index <= section.end; index += 1) {
    if (fenced.has(index)) {
      continue;
    }
    const line = String(lines[index] || "");
    if (line.startsWith(" ") || line.startsWith("\t")) {
      continue;
    }
    const parsed = planParseEntry(line);
    if (!parsed || parsed.state !== "open") {
      continue;
    }
    // The entry's sub-bullet range: following non-empty indented list
    // lines (a blank line, a column-0 line, or the section end stops it).
    const range = [];
    for (let sub = index + 1; sub <= section.end; sub += 1) {
      if (fenced.has(sub)) {
        continue;
      }
      if (!todayIsSubBulletLine(lines[sub])) {
        break;
      }
      range.push(sub);
    }
    const leading = planLeadingRange(parsed.body);
    const entryName =
      leading.length === null
        ? null
        : planParseNameTail(parsed.body.slice(leading.length));
    visit({
      index,
      lines,
      fenced,
      parsed,
      leading,
      entryName,
      range,
    });
  }
}

// Every dedicated Task Link under today's open entries, in ledger order.
// `dailyPath` canonicalizes empty targets only for key building in
// `resolveTodayKeys`; the recorded `target` is the written path part.
function computeTodayLinks(content, dailyPath) {
  const links = [];
  todayEachOpenEntry(content, (entry) => {
    const range = entry.range;
    if (!range || range.length === 0) {
      return;
    }
    const childIndent = todayIndentLen(entry.lines[range[0]]);
    for (const sub of range) {
      if (todayIndentLen(entry.lines[sub]) !== childIndent) {
        continue;
      }
      const bullet = todayBulletBody(entry.lines[sub]);
      if (!bullet) {
        continue;
      }
      const token = todayLinkFromBody(bullet.body);
      if (!token) {
        continue;
      }
      links.push({
        entryLine: entry.index + 1,
        entryName: entry.entryName,
        entryRange: entry.leading.timeRange,
        entryPlaceholder: entry.leading.placeholder === true,
        ledgerLine: sub + 1,
        target: token.pathPart,
        blockId: token.blockId,
        embedded: token.embedded,
      });
    }
  });
  return links;
}

function todayOpenEntries(content) {
  const entries = [];
  todayEachOpenEntry(content, (entry) => {
    entries.push(
      Object.freeze({
        entryLine: entry.index + 1,
        name: entry.entryName,
        range: entry.leading.timeRange,
        placeholder: entry.leading.placeholder === true,
      }),
    );
  });
  return Object.freeze(entries);
}

function todayRunningEntryLine(entries) {
  const list = Array.isArray(entries) ? entries : [];
  const timed = [];
  for (const entry of list) {
    if (!entry || entry.placeholder === true) {
      continue;
    }
    if (typeof entry.range === "string" && entry.range) {
      timed.push(entry);
    }
  }
  if (timed.length !== 1) {
    return null;
  }
  const line = timed[0].entryLine;
  return typeof line === "number" ? line : null;
}

function todayResolveLinkKey(link, dailyPath, resolve) {
  if (!link || typeof link.blockId !== "string" || !link.blockId) {
    return null;
  }
  let resolved = null;
  const target = typeof link.target === "string" ? link.target : "";
  if (target === "") {
    resolved = typeof dailyPath === "string" ? dailyPath : null;
  } else if (typeof resolve === "function") {
    try {
      const file = resolve(target, dailyPath);
      resolved = file && typeof file.path === "string" ? file.path : null;
    } catch (error) {
      resolved = null;
    }
  }
  if (typeof resolved !== "string" || !resolved) {
    return null;
  }
  const withExtension = /\.md$/i.test(resolved) ? resolved : `${resolved}.md`;
  return `${withExtension}#${link.blockId}`;
}

// Every resolved Today link in ledger order, without dedupe.
function resolveTodayLinkKeys(links, dailyPath, resolve) {
  const out = [];
  const list = Array.isArray(links) ? links : [];
  for (const link of list) {
    const key = todayResolveLinkKey(link, dailyPath, resolve);
    if (!key) {
      continue;
    }
    out.push(Object.freeze({ link, key }));
  }
  return out;
}

// Ordered, unique Today keys (`"<vault path with .md>#<block id>"`).
// `resolve(target, dailyPath)` wraps
// `app.metadataCache.getFirstLinkpathDest`; an empty target is the daily
// note itself. Unresolved targets are skipped. First-occurrence dedupe of
// `resolveTodayLinkKeys`.
function resolveTodayKeys(links, dailyPath, resolve) {
  const seen = new Set();
  const keys = [];
  for (const item of resolveTodayLinkKeys(links, dailyPath, resolve)) {
    if (!item || typeof item.key !== "string" || seen.has(item.key)) {
      continue;
    }
    seen.add(item.key);
    keys.push(item.key);
  }
  return keys;
}

function todayKeyParts(key) {
  const text = typeof key === "string" ? key : "";
  const hash = text.lastIndexOf("#");
  if (hash === -1) {
    return { path: text, blockId: "" };
  }
  return {
    path: text.slice(0, hash),
    blockId: text.slice(hash + 1),
  };
}

function todayIdsByPathFromKeys(keys) {
  const map = new Map();
  for (const key of Array.isArray(keys) ? keys : []) {
    const parts = todayKeyParts(key);
    if (!parts.path || !parts.blockId) {
      continue;
    }
    let ids = map.get(parts.path);
    if (!(ids instanceof Set)) {
      ids = new Set();
      map.set(parts.path, ids);
    }
    ids.add(parts.blockId);
  }
  return map;
}

function todayLinkDetails(resolved, options) {
  const runningEntryLine =
    options && typeof options.runningEntryLine === "number"
      ? options.runningEntryLine
      : null;
  const homeLabels =
    options && options.homeLabels instanceof Map ? options.homeLabels : new Map();
  const map = new Map();
  const seen = new Set();
  const list = Array.isArray(resolved) ? resolved : [];
  for (const item of list) {
    if (!item || typeof item.key !== "string" || !item.key || !item.link) {
      continue;
    }
    const link = item.link;
    const entryLine = link.entryLine;
    const seenKey = `${item.key}\0${String(entryLine)}`;
    if (seen.has(seenKey)) {
      continue;
    }
    seen.add(seenKey);
    const name =
      typeof link.entryName === "string" && link.entryName
        ? link.entryName
        : null;
    const home = homeLabels.get(entryLine);
    const label =
      name || (typeof home === "string" && home ? home : null);
    const detail = Object.freeze({
      entryLine,
      ledgerLine: link.ledgerLine,
      name,
      range: typeof link.entryRange === "string" ? link.entryRange : null,
      placeholder: link.entryPlaceholder === true,
      running: entryLine === runningEntryLine,
      label,
      embedded: link.embedded === true,
    });
    const existing = map.get(item.key);
    if (existing) {
      existing.push(detail);
    } else {
      map.set(item.key, [detail]);
    }
  }
  for (const [key, details] of map) {
    details.sort((left, right) => {
      if (left.running !== right.running) {
        return left.running ? -1 : 1;
      }
      const leftLine =
        typeof left.entryLine === "number" ? left.entryLine : 0;
      const rightLine =
        typeof right.entryLine === "number" ? right.entryLine : 0;
      return leftLine - rightLine;
    });
    map.set(key, Object.freeze(details.slice()));
  }
  return map;
}

function todayDetailsSignature(details) {
  if (!(details instanceof Map)) {
    return "";
  }
  const rows = [];
  for (const [key, list] of details) {
    const items = Array.isArray(list) ? list : [];
    rows.push([
      key,
      items.map((detail) => ({
        entryLine: detail ? detail.entryLine : null,
        ledgerLine: detail ? detail.ledgerLine : null,
        name: detail ? detail.name : null,
        range: detail ? detail.range : null,
        placeholder: !!(detail && detail.placeholder),
        running: !!(detail && detail.running),
        label: detail ? detail.label : null,
        embedded: !!(detail && detail.embedded),
      })),
    ]);
  }
  return JSON.stringify(rows);
}

function planTaskBlockId(task) {
  if (!task || typeof task !== "object") {
    return null;
  }
  for (const key of ["blockLink", "blockId"]) {
    const value = task[key];
    if (typeof value !== "string") {
      continue;
    }
    // Tasks 8.4.0 keeps the block ID in `blockLink` as ` ^id` (see its
    // `blockLinkRegex`: `/ \^<id>$/`); the ID itself matches
    // `PLAN_BLOCK_ID_RE`.
    const trimmed = value.trim().replace(/^\^/, "");
    if (trimmed && PLAN_BLOCK_ID_RE.test(trimmed)) {
      return trimmed;
    }
  }
  return null;
}

function planTaskStatusSymbol(task) {
  if (!task || typeof task !== "object") {
    return "";
  }
  const status =
    task.status && typeof task.status === "object" ? task.status : {};
  for (const value of [status.symbol, task.statusSymbol, task.symbol]) {
    if (typeof value === "string" && value) {
      return value;
    }
  }
  return "";
}

function planLaneVisible(task, list, todayDay) {
  if (planTaskIsDone(task)) {
    return false;
  }
  if (planTaskIsBlocked(task, list)) {
    return false;
  }
  const tags = planTaskTags(task);
  if (
    tags.some(
      (tag) => typeof tag === "string" && tag.toLowerCase().includes("#hide"),
    )
  ) {
    return false;
  }
  const loweredPath = String(planTaskPath(task) || "").toLowerCase();
  if (loweredPath.includes("_templates") || loweredPath.includes("_conflicts")) {
    return false;
  }
  if (todayDay !== null) {
    const scheduled = planTaskScheduledDay(task);
    if (scheduled !== null && scheduled > todayDay) {
      return false;
    }
  }
  return true;
}

// A lane budget over Tasks-plugin task objects: `"next"` is symbol `*`,
// `"pending"` is type IN_PROGRESS. Visibility matches the dash defaults
// (`docs/plan.md`, "Lanes"), counting the whole lane, Today included.
function laneBudgetFromTasks(tasks, today, caps, lane) {
  const effective = effectivePlanCaps(caps);
  const list = Array.isArray(tasks) ? tasks : [];
  const todayDay = planDayNumber(today === undefined ? new Date() : today);
  let count = 0;
  for (const task of list) {
    if (!planLaneVisible(task, list, todayDay)) {
      continue;
    }
    if (lane === "next") {
      if (planTaskStatusSymbol(task) !== "*") {
        continue;
      }
    } else if (lane === "pending") {
      const type =
        task && task.status && typeof task.status === "object"
          ? task.status.type
          : null;
      if (type !== "IN_PROGRESS") {
        continue;
      }
    } else {
      continue;
    }
    count += 1;
  }
  const cap = lane === "pending" ? effective.maxPending : effective.maxNext;
  return { count, cap, over: count > cap };
}

// ---- src/070-ready-and-review.js ----
// --- READY backlog ----------------------------------------------------------
// The shared READY backlog (`docs/plan.md`, "READY backlog"): the global
// dashboard backlog, regardless of which daily file hosts the badge.
//
// The predicate matches the dashboard READY section's effective filters:
// TODO type (including custom TODO symbols), dashboard visibility
// (template/conflict exclusion, dash.md self-exclusion, `#hide`
// case-insensitive substring match like Tasks `tag does not include
// #hide`, and the Tasks global query's `_conflicts` exclusion applied
// explicitly because `getTasks()` returns the raw cache), not
// dependency-blocked (against the full Tasks list), scheduled on or
// before the current local day, and not Today. Self-exclusion always
// refers to `dash.md`, never the hosting daily note. Tasks built-in
// path/folder filters are case-insensitive, so the helper lowercases
// paths before comparing.
const READY_DASH_PATH = "dash.md";
const READY_FALLBACK_CAP = 100;

// Shared dashboard section base visibility: the Tasks-effective filters
// READY and the PENDING/NEXT dashboard sections agree on. Hide uses a
// case-insensitive substring (`#hide`, `#hide/x`, `#Hide` all excluded),
// paths use lowercased `_templates`/`_conflicts` checks, dash
// self-exclusion is case-insensitive, and future schedules are out.
// Status, done, blocked, and TODAY are layered by callers.
function dashboardSectionBaseVisible(task, todayDay, dashPath = READY_DASH_PATH) {
  if (!task || typeof task !== "object") {
    return false;
  }
  const path = String(planTaskPath(task) || "");
  if (!path) {
    return false;
  }
  const lowered = path.toLowerCase();
  if (lowered.includes("_templates")) {
    return false;
  }
  if (lowered.includes("_conflicts")) {
    return false;
  }
  if (lowered === String(dashPath || "").toLowerCase()) {
    return false;
  }
  const tags = planTaskTags(task);
  if (
    tags.some(
      (tag) => typeof tag === "string" && tag.toLowerCase().includes("#hide"),
    )
  ) {
    return false;
  }
  if (todayDay !== null && todayDay !== undefined) {
    const scheduled = planTaskScheduledDay(task);
    if (scheduled !== null && scheduled > todayDay) {
      return false;
    }
  }
  return true;
}

function readyTaskStatusIsTodo(task) {
  if (!task || typeof task !== "object") {
    return false;
  }
  const status =
    task.status && typeof task.status === "object" ? task.status : null;
  if (status && typeof status.type === "string") {
    return status.type === "TODO";
  }
  return false;
}

function readyTaskVisible(task, todayDay) {
  if (!task || typeof task !== "object") {
    return false;
  }
  if (planTaskIsDone(task)) {
    return false;
  }
  if (!readyTaskStatusIsTodo(task)) {
    return false;
  }
  return dashboardSectionBaseVisible(task, todayDay, READY_DASH_PATH);
}

// Dashboard PENDING/NEXT section membership: the dash section model
// excludes TODAY and dash.md itself plus the shared base visibility
// (templates, conflicts, hide, future schedules), dependency-blocked
// tasks, and done tasks. Status uses IN_PROGRESS for PENDING and symbol
// `*` for NEXT; the standard configured statuses are unchanged.
function dashboardLaneStatusMatches(task, lane) {
  if (lane === "next") {
    return planTaskStatusSymbol(task) === "*";
  }
  if (lane === "pending") {
    const status =
      task && task.status && typeof task.status === "object"
        ? task.status
        : null;
    return status !== null && status.type === "IN_PROGRESS";
  }
  return false;
}

function dashboardLaneSectionVisible(task, list, todayDay, lane) {
  if (!dashboardSectionBaseVisible(task, todayDay, READY_DASH_PATH)) {
    return false;
  }
  if (planTaskIsDone(task)) {
    return false;
  }
  if (planTaskIsBlocked(task, list)) {
    return false;
  }
  return dashboardLaneStatusMatches(task, lane);
}

// Pure dashboard section budget over Tasks-plugin task objects.
// `isToday` is the caller's Today predicate. Returns
// `{ section, lane, cap, over, today }` with integers when available.
// Throws when `isToday` throws so callers degrade to unavailable rather
// than a partially gated zero.
function dashboardLaneBudgetFromTasks(tasks, today, caps, lane, isToday) {
  if (lane !== "pending" && lane !== "next") {
    throw new Error(`unknown lane: ${lane}`);
  }
  const effective = effectivePlanCaps(caps);
  const list = Array.isArray(tasks) ? tasks : [];
  const todayDay = planDayNumber(today === undefined ? new Date() : today);
  const isTodayPredicate =
    typeof isToday === "function" ? isToday : () => false;
  const cap = lane === "pending" ? effective.maxPending : effective.maxNext;
  const whole = laneBudgetFromTasks(list, today, effective, lane);
  let section = 0;
  let todayInLane = 0;
  for (const task of list) {
    if (!dashboardLaneSectionVisible(task, list, todayDay, lane)) {
      continue;
    }
    let todayFlag = false;
    try {
      todayFlag = Boolean(isTodayPredicate(task));
    } catch (error) {
      throw error;
    }
    if (todayFlag) {
      todayInLane += 1;
      continue;
    }
    section += 1;
  }
  return {
    section,
    lane: whole.count,
    count: section,
    laneCount: whole.count,
    today: todayInLane,
    cap,
    over: whole.over,
  };
}

// Shared dashboard lane badge view-model. `budget` is
// `{ section, lane, cap, over, today }` with nulls for unavailable.
// The badge shows and colors the section count against its cap; whole-lane
// pressure remains separately labeled in the tooltip and accessible label.
function dashboardLaneBadgeModel(budget, lane) {
  const label = lane === "next" ? "NEXT" : "PENDING";
  const cap =
    budget && Number.isInteger(budget.cap) && budget.cap >= 1
      ? budget.cap
      : lane === "next"
        ? 15
        : 10;
  const section =
    budget &&
    (typeof budget.section === "number" || budget.section === null)
      ? budget.section
      : budget && typeof budget.count === "number"
        ? budget.count
        : null;
  const laneCount =
    budget &&
    (typeof budget.lane === "number" || budget.lane === null)
      ? budget.lane
      : budget && typeof budget.laneCount === "number"
        ? budget.laneCount
        : null;
  const today =
    budget && (typeof budget.today === "number" || budget.today === null)
      ? budget.today
      : null;
  if (
    section === null ||
    laneCount === null ||
    !Number.isInteger(section) ||
    section < 0 ||
    !Number.isInteger(laneCount) ||
    laneCount < 0
  ) {
    return {
      text: `${label} –`,
      tooltip: `${label} section unavailable; section cap ${cap} cannot be assessed. Live section excluding Today. Open ${label} Tasks in dash.`,
      aria: `${label}: section unavailable; section cap ${cap} cannot be assessed. Open ${label} Tasks in dash.`,
      over: false,
      sectionOver: false,
      laneOver: false,
      placeholder: true,
      section: null,
      lane: null,
      today: null,
      cap,
      tone: null,
    };
  }
  const sectionOver = section > cap;
  const laneOver = laneCount > cap;
  const todayText = Number.isInteger(today) ? today : Math.max(0, laneCount - section);
  const pressure = [];
  if (sectionOver) {
    pressure.push(`${section - cap} over the section cap`);
  }
  if (laneOver) {
    pressure.push(`${laneCount - cap} over the whole-lane cap`);
  }
  const pressureText = pressure.length > 0 ? ` · ${pressure.join("; ")}` : "";
  const tooltip = `${section} in this section; whole lane ${laneCount}/${cap}; ${todayText} in TODAY${pressureText}. Live section excluding Today. Open ${label} Tasks in dash.`;
  const aria = `${label}: ${section} of ${cap} in this section${sectionOver ? `, ${section - cap} over the section cap` : ""}, whole lane ${laneCount} of ${cap}${laneOver ? `, ${laneCount - cap} over the whole-lane cap` : ""}, ${todayText} in TODAY. Open ${label} Tasks in dash.`;
  return {
    text: `${label} ${section}/${cap}`,
    tooltip,
    aria,
    over: sectionOver,
    sectionOver,
    laneOver,
    placeholder: false,
    section,
    lane: laneCount,
    today: todayText,
    cap,
    tone: workBadgeTone(section, cap),
  };
}

// Pure, testable READY count over Tasks-plugin task objects. `isToday`
// is the caller's Today predicate. Throws when `isToday` or `isBlocked`
// throws, so callers can degrade to an unavailable badge rather than a
// partial count.
//
// The optional `isReviewBucket` predicate gates the shared READY count
// (`docs/freshness.md` §4 in bob-cli): tasks it flags (NEW or ROTTEN
// review) are excluded from READY. A throwing predicate discards the
// partial gated count and recomputes the legacy ungated count, so a
// failure halfway through a batch never leaves a partially gated badge.
function readyCountFromTasks(tasks, today, isToday, isReviewBucket) {
  const list = Array.isArray(tasks) ? tasks : [];
  const todayDay = planDayNumber(today === undefined ? new Date() : today);
  const isTodayPredicate =
    typeof isToday === "function" ? isToday : () => false;
  const gated = typeof isReviewBucket === "function";
  const legacyCount = () => {
    let total = 0;
    for (const task of list) {
      if (!readyTaskVisible(task, todayDay)) {
        continue;
      }
      if (planTaskIsBlocked(task, list)) {
        continue;
      }
      let todayFlag = false;
      try {
        todayFlag = Boolean(isTodayPredicate(task));
      } catch (error) {
        throw error;
      }
      if (todayFlag) {
        continue;
      }
      total += 1;
    }
    return total;
  };
  if (!gated) {
    return legacyCount();
  }
  let count = 0;
  for (const task of list) {
    if (!readyTaskVisible(task, todayDay)) {
      continue;
    }
    if (planTaskIsBlocked(task, list)) {
      continue;
    }
    let todayFlag = false;
    try {
      todayFlag = Boolean(isTodayPredicate(task));
    } catch (error) {
      throw error;
    }
    if (todayFlag) {
      continue;
    }
    let review = false;
    try {
      review = Boolean(isReviewBucket(task));
    } catch (error) {
      return legacyCount();
    }
    if (review) {
      continue;
    }
    count += 1;
  }
  return count;
}

function readyBudgetFromTasks(tasks, today, caps, isToday, isReviewBucket) {
  const effective = effectivePlanCaps(caps);
  const cap = planReadyCapOrDefault(effective.maxReady, READY_FALLBACK_CAP);
  const count = readyCountFromTasks(
    tasks,
    today,
    isToday,
    isReviewBucket,
  );
  return { count, cap, over: count > cap };
}

// Shared READY badge view-model. `budget` is `{ count, cap, over }` with
// `count === null` for unavailable. Never throws.
function readyBadgeModel(budget, options = {}) {
  const invalid = Boolean(options.invalid);
  const cap =
    budget && Number.isInteger(budget.cap) && budget.cap >= 1
      ? budget.cap
      : READY_FALLBACK_CAP;
  const count =
    budget && (typeof budget.count === "number" || budget.count === null)
      ? budget.count
      : null;
  if (count === null || !Number.isInteger(count) || count < 0) {
    return {
      text: "READY –",
      tooltip:
        `READY backlog unavailable; limit ${cap}. ` +
        `Live current backlog excluding Today. Open READY Tasks in dash.` +
        (invalid ? " Plan config invalid, using defaults." : ""),
      aria: `READY: unavailable (limit ${cap}). Open READY Tasks in dash.`,
      over: false,
      placeholder: true,
      count: null,
      cap,
      tone: null,
    };
  }
  const over = count > cap;
  const excess = count - cap;
  // Freshness-gated lanes carry total lane pressure: the gated READY
  // count plus the NEW and ROTTEN review buckets behind it.
  const lane = options.lane || null;
  const laneValid =
    lane &&
    Number.isInteger(lane.total) &&
    lane.total >= 0 &&
    Number.isInteger(lane.new) &&
    lane.new >= 0 &&
    Number.isInteger(lane.rotten) &&
    lane.rotten >= 0 &&
    lane.ready === count;
  const tooltip = laneValid
    ? `READY ${count}/${cap} · lane ${lane.total} = ${lane.new} new + ${lane.rotten} rotten + ${lane.ready} ready` +
      (over ? ` · ${excess} over the limit` : "") +
      (invalid ? " · plan config invalid, using defaults" : "")
    : over
      ? `${count} ready tasks; limit ${cap}; ${excess} over the limit. ` +
        `Live current backlog excluding Today. Open READY Tasks in dash.` +
        (invalid ? " Plan config invalid, using defaults." : "")
      : `${count} ready tasks; limit ${cap}. ` +
        `Live current backlog excluding Today. Open READY Tasks in dash.` +
        (invalid ? " Plan config invalid, using defaults." : "");
  const aria = over
    ? `READY: ${count} of ${cap} tasks, ${excess} over the limit. Open READY Tasks in dash.`
    : `READY: ${count} of ${cap} tasks. Open READY Tasks in dash.`;
  return {
    text: `READY ${count}/${cap}`,
    tooltip,
    aria,
    over,
    placeholder: false,
    count,
    cap,
    tone: workBadgeTone(count, cap),
  };
}

// Structured READY content: the shared badge renders separate label and
// value spans (`.bob-plan-ready-label` / `.bob-plan-ready-value`) so the
// dashboard and daily surfaces can style them like neighboring chips. One
// routine owns both initial paint and live refresh so updates never flatten
// the anchor back to plain text.
const READY_LABEL_TEXT = "READY";
const READY_LABEL_CLS = "bob-plan-ready-label";
const READY_VALUE_CLS = "bob-plan-ready-value";

function readyBadgeValueText(model) {
  if (
    !model ||
    model.placeholder ||
    model.count === null ||
    model.count === undefined
  ) {
    return "–";
  }
  return `${model.count}/${model.cap}`;
}

function setReadySpanText(span, text) {
  if (!span) {
    return;
  }
  if (typeof span.setText === "function") {
    span.setText(text);
    return;
  }
  // Real DOM elements expose textContent; minimal test stubs use `.text`.
  // Assigning `.text` on a real Element is a harmless expando, while setting
  // textContent on a stub without that field would create a misleading
  // duplicate source of truth, so prefer whichever already exists.
  if ("textContent" in span && typeof span.textContent === "string") {
    span.textContent = text;
  } else if ("text" in span) {
    span.text = text;
  } else if ("textContent" in span) {
    span.textContent = text;
  } else {
    span.text = text;
  }
}

function collectReadySpans(anchor, cls) {
  if (!anchor) {
    return [];
  }
  try {
    if (typeof anchor.querySelectorAll === "function") {
      return Array.from(anchor.querySelectorAll(`.${cls}`));
    }
  } catch (error) {
    // Fall through to the children scan below.
  }
  const children =
    (Array.isArray(anchor.children) && anchor.children) ||
    (Array.isArray(anchor.childNodes) && anchor.childNodes) ||
    [];
  return children.filter((child) => {
    if (!child) {
      return false;
    }
    if (typeof child.cls === "string") {
      return child.cls.split(/\s+/).includes(cls);
    }
    const classAttr =
      child.attrs && typeof child.attrs.class === "string"
        ? child.attrs.class
        : typeof child.className === "string"
          ? child.className
          : null;
    if (typeof classAttr === "string") {
      return classAttr.split(/\s+/).includes(cls);
    }
    if (child.classList && typeof child.classList.contains === "function") {
      try {
        return child.classList.contains(cls);
      } catch (error) {
        return false;
      }
    }
    return false;
  });
}

function findReadySpan(anchor, cls) {
  if (!anchor) {
    return null;
  }
  try {
    if (typeof anchor.querySelector === "function") {
      return anchor.querySelector(`.${cls}`) || null;
    }
  } catch (error) {
    // Fall through to the children scan below.
  }
  const matches = collectReadySpans(anchor, cls);
  return matches.length > 0 ? matches[0] : null;
}

function createReadySpan(anchor, cls, text) {
  if (anchor && typeof anchor.createEl === "function") {
    return anchor.createEl("span", { cls, text });
  }
  // Minimal-stub fallback: track the child so structure assertions still see
  // exactly one label and one value.
  const span = {
    tag: "span",
    cls,
    text,
    attrs: {},
    setAttribute(name, value) {
      this.attrs[name] = value;
    },
  };
  if (Array.isArray(anchor.children)) {
    anchor.children.push(span);
  }
  return span;
}

// Update the anchor's child spans plus its model-dependent title,
// accessibility label, and state classes without replacing the anchor or
// disturbing its event listeners. Repeated calls leave exactly one label
// and one value span.
function setReadyAnchorContent(anchor, model, options = {}) {
  if (!anchor) {
    return;
  }
  // bob-cli-3d fix: keep the caller's chip-kind class instead of
  // hard-coding `bob-plan-ready`. Callers pass `{ kind: "pending" }`,
  // `{ kind: "next" }`, `{ kind: "crowded" }`, `{ kind: "projects" }`,
  // or `{ kind: "references" }`; the default stays "ready" so existing
  // callers are unchanged. `model.kind` is honored as a fallback for
  // models that carry it.
  const rawKind =
    options && typeof options.kind === "string" && options.kind
      ? options.kind
      : model && typeof model.kind === "string" && model.kind
        ? model.kind
        : "ready";
  const kind =
    rawKind === "pending" ||
    rawKind === "next" ||
    rawKind === "crowded" ||
    rawKind === "projects" ||
    rawKind === "references" ||
    rawKind === "ready"
      ? rawKind
      : "ready";
  const labelText =
    options && typeof options.label === "string" && options.label
      ? options.label
      : model && typeof model.label === "string" && model.label
        ? model.label
        : READY_LABEL_TEXT;
  const valueText = readyBadgeValueText(model);
  let label = findReadySpan(anchor, READY_LABEL_CLS);
  if (!label) {
    label = createReadySpan(anchor, READY_LABEL_CLS, labelText);
  }
  setReadySpanText(label, labelText);
  let value = findReadySpan(anchor, READY_VALUE_CLS);
  if (!value) {
    value = createReadySpan(anchor, READY_VALUE_CLS, valueText);
  }
  setReadySpanText(value, valueText);
  // Drop extras so repeated updates never accumulate spans.
  for (const cls of [READY_LABEL_CLS, READY_VALUE_CLS]) {
    const matches = collectReadySpans(anchor, cls);
    for (let index = 1; index < matches.length; index += 1) {
      const extra = matches[index];
      try {
        if (extra && typeof extra.remove === "function") {
          extra.remove();
        } else if (
          anchor &&
          typeof anchor.removeChild === "function" &&
          extra &&
          extra.parentNode === anchor
        ) {
          anchor.removeChild(extra);
        } else if (anchor && Array.isArray(anchor.children)) {
          const at = anchor.children.indexOf(extra);
          if (at !== -1) {
            anchor.children.splice(at, 1);
          }
        }
      } catch (error) {
        // Best-effort dedupe only.
      }
    }
  }
  // Clear any flattened direct text left by older renders (or stub `.text`)
  // while preserving the span children. Never assign `.text` on a live
  // element: in Obsidian it is a setter that wipes the span children.
  try {
    const childNodes =
      anchor && anchor.childNodes != null ? anchor.childNodes : null;
    if (childNodes && typeof childNodes.length === "number") {
      for (const node of Array.from(childNodes)) {
        if (
          node &&
          node.nodeType === 3 &&
          node !== label &&
          node !== value
        ) {
          if (typeof anchor.removeChild === "function") {
            anchor.removeChild(node);
          }
        }
      }
    }
  } catch (error) {
    // Best-effort cleanup only.
  }
  try {
    const descriptor = anchor
      ? Object.getOwnPropertyDescriptor(anchor, "text")
      : undefined;
    if (descriptor && typeof descriptor.value === "string") {
      // Stub anchors carry `.text` as an own data property alongside
      // `.children`; keep it empty so a stale flattened value can never
      // shadow the spans. A live Obsidian accessor lives on the prototype
      // and must be left alone.
      anchor.text = "";
    }
  } catch (error) {
    // Best-effort cleanup only.
  }
  const resolvedTone = (() => {
    try {
      if (model && typeof model.tone === "string" && WORK_BADGE_TONES.indexOf(model.tone) !== -1) {
        return model.tone;
      }
      if (!model || model.placeholder) {
        return null;
      }
      const rawCount =
        Number.isInteger(model.count) ? model.count
        : Number.isInteger(model.section) ? model.section
        : null;
      const rawCap = Number.isInteger(model.cap) ? model.cap : null;
      if (rawCount === null || rawCap === null) {
        return null;
      }
      return workBadgeTone(rawCount, rawCap);
    } catch (error) {
      return null;
    }
  })();
  const toneCls = workToneClass(resolvedTone);
  const baseCls =
    `bob-plan-chip bob-plan-${kind}${model.over ? " bob-plan-over" : ""}${model.placeholder ? " bob-plan-unavailable" : ""}`;
  const cls = toneCls ? `${baseCls} ${toneCls}` : baseCls;
  if (typeof anchor.setAttribute === "function") {
    anchor.setAttribute("title", model.tooltip);
    anchor.setAttribute("aria-label", model.aria);
    anchor.setAttribute("class", cls);
    if (anchor.attrs && typeof anchor.attrs === "object") {
      anchor.attrs.class = cls;
    }
  }
  if (anchor && typeof anchor.cls === "string") {
    anchor.cls = cls;
  }
  if (anchor && typeof anchor.title === "string") {
    anchor.title = model.tooltip;
  }
}

// Shared NEW/ROTTEN chip content: separate label and value spans like
// the READY badge, so dashboard and rotten-summary chips style like
// neighboring chips. NEW shows 0 when empty and is red above 0;
// ROTTEN is neutral at 0, orange above 0, red once any tickler or
// age-expired row is a full interval overdue.
const REVIEW_LABEL_CLS = "bob-plan-review-label";
const REVIEW_VALUE_CLS = "bob-plan-review-value";

function reviewChipText(kind, review) {
  const active = review && review.available === true ? review : null;
  if (kind === "rotten") {
    return {
      label: "ROTTEN",
      value: active ? active.rottenText.replace(/^ROTTEN /, "") : "–",
      tooltip: active ? active.tooltip : "ROTTEN unavailable",
      aria: active ? active.tooltip : "ROTTEN: unavailable",
    };
  }
  return {
    label: "NEW",
    value: active ? String(active.new) : "–",
    tooltip: active
      ? "NEW " + active.new + " unconfirmed · " + active.meter + " today"
      : "NEW unavailable",
    aria: active
      ? "NEW: " + active.new + " unconfirmed"
      : "NEW: unavailable",
  };
}

function reviewChipClass(kind, review) {
  const active = review && review.available === true ? review : null;
  let cls = "bob-plan-chip bob-plan-review bob-plan-" + kind;
  if (!active) {
    return cls + " bob-plan-unavailable";
  }
  if (kind === "rotten") {
    if (review.escalated) {
      return cls + " bob-plan-over";
    }
    if (review.rotten > 0) {
      return cls + " bob-plan-warn";
    }
    return cls;
  }
  if (review.new > 0) {
    return cls + " bob-plan-over";
  }
  return cls;
}

function reviewChipHref(kind) {
  return kind === "rotten" ? "rotten" : "dash#NEW Tasks";
}

function setReviewAnchorContent(anchor, kind, review) {
  if (!anchor) {
    return;
  }
  const content = reviewChipText(kind, review);
  const cls = reviewChipClass(kind, review);
  let label = findReadySpan(anchor, REVIEW_LABEL_CLS);
  if (!label) {
    label = createReadySpan(anchor, REVIEW_LABEL_CLS, content.label);
  }
  setReadySpanText(label, content.label);
  let value = findReadySpan(anchor, REVIEW_VALUE_CLS);
  if (!value) {
    value = createReadySpan(anchor, REVIEW_VALUE_CLS, content.value);
  }
  setReadySpanText(value, content.value);
  for (const spanCls of [REVIEW_LABEL_CLS, REVIEW_VALUE_CLS]) {
    const matches = collectReadySpans(anchor, spanCls);
    for (let index = 1; index < matches.length; index += 1) {
      const extra = matches[index];
      try {
        if (extra && typeof extra.remove === "function") {
          extra.remove();
        } else if (anchor && Array.isArray(anchor.children)) {
          const at = anchor.children.indexOf(extra);
          if (at !== -1) {
            anchor.children.splice(at, 1);
          }
        }
      } catch (error) {
        // Best-effort dedupe only.
      }
    }
  }
  if (typeof anchor.setAttribute === "function") {
    anchor.setAttribute("title", content.tooltip);
    anchor.setAttribute("aria-label", content.aria);
    anchor.setAttribute("class", cls);
    if (anchor.attrs && typeof anchor.attrs === "object") {
      anchor.attrs.class = cls;
    }
  }
  if (anchor && typeof anchor.cls === "string") {
    anchor.cls = cls;
  }
  if (anchor && typeof anchor.title === "string") {
    anchor.title = content.tooltip;
  }
}

function paintReviewElement(host, kind, review) {
  try {
    if (!host || typeof host.createEl !== "function") {
      return null;
    }
    const anchor = host.createEl("a", {
      cls: reviewChipClass(kind, review),
      title: reviewChipText(kind, review).tooltip,
      href: reviewChipHref(kind),
    });
    setReviewAnchorContent(anchor, kind, review);
    if (anchor && typeof anchor.setAttribute === "function") {
      anchor.setAttribute("aria-label", reviewChipText(kind, review).aria);
      anchor.setAttribute("role", "link");
      if (
        typeof anchor.hasAttribute !== "function" ||
        !anchor.hasAttribute("tabindex")
      ) {
        anchor.setAttribute("tabindex", "0");
      }
    }
    return anchor;
  } catch (error) {
    return null;
  }
}

// ---- src/075-work-badge-tone.js ----
// --- Work badge tones -------------------------------------------------------
// Shared count-to-limit presentation for TODAY, PENDING, NEXT, and READY.
// Precedence (exact comparisons, never rounded percentages):
// n === 0 -> grey, 0 < n < 2L/5 -> blue, 2L/5 <= n < 3L/5 -> green,
// 3L/5 <= n < 4L/5 -> yellow, 4L/5 <= n < L -> orange, n === L -> magenta, n > L -> red.
// Invalid or missing input is unavailable (null), never numeric zero.
const WORK_BADGE_TONES = ["grey", "blue", "green", "yellow", "orange", "magenta", "red"];

function workBadgeTone(count, cap) {
  if (!Number.isInteger(count) || count < 0) {
    return null;
  }
  if (!Number.isInteger(cap) || cap < 1) {
    return null;
  }
  if (count === 0) {
    return "grey";
  }
  if (count > cap) {
    return "red";
  }
  if (count === cap) {
    return "magenta";
  }
  if (5 * count >= 4 * cap) {
    return "orange";
  }
  if (5 * count >= 3 * cap) {
    return "yellow";
  }
  if (5 * count >= 2 * cap) {
    return "green";
  }
  return "blue";
}

// TODAY tone: ledger-availability check plus the theme-overflow override.
// `budget` is a plan budget (`computePlanBudget` / `emptyPlanBudget`
// shape). Missing section, missing/invalid theme or link meters, or a
// missing budget is unavailable (null). Themes over cap force red,
// including when links are zero; themes exactly at cap keep the
// link-based tone. Both fractions remain displayed by callers.
function todayBadgeTone(budget) {
  try {
    if (!budget || typeof budget !== "object" || Array.isArray(budget)) {
      return null;
    }
    if (budget.hasSection !== true) {
      return null;
    }
    const themes = budget.themes;
    const links = budget.links;
    if (!themes || typeof themes !== "object" || Array.isArray(themes)) {
      return null;
    }
    if (!links || typeof links !== "object" || Array.isArray(links)) {
      return null;
    }
    if (
      !Number.isInteger(themes.count) ||
      themes.count < 0 ||
      !Number.isInteger(themes.cap) ||
      themes.cap < 1
    ) {
      return null;
    }
    if (
      !Number.isInteger(links.count) ||
      links.count < 0 ||
      !Number.isInteger(links.cap) ||
      links.cap < 1
    ) {
      return null;
    }
    if (themes.count > themes.cap) {
      return "red";
    }
    return workBadgeTone(links.count, links.cap);
  } catch (error) {
    return null;
  }
}

function workToneClass(tone) {
  if (typeof tone !== "string" || !tone) {
    return "";
  }
  if (WORK_BADGE_TONES.indexOf(tone) === -1) {
    return "";
  }
  return `bob-work-tone-${tone}`;
}

function workBadgeToneClass(count, cap) {
  return workToneClass(workBadgeTone(count, cap));
}

// Append (or replace) the Work tone class on a chip class string without
// accumulating stale tones. Keeps over/unavailable markers intact.
function withWorkToneClass(baseCls, tone) {
  const base = String(baseCls || "");
  const cleaned = base
    .replace(new RegExp(`\\s*bob-work-tone-(${WORK_BADGE_TONES.join("|")})\\b`, "g"), "")
    .replace(/\s+/g, " ")
    .trim();
  const toneCls = workToneClass(tone);
  if (!toneCls) {
    return cleaned;
  }
  return cleaned ? `${cleaned} ${toneCls}` : toneCls;
}
// ---- src/080-freshness-placement.js ----
// --- Task freshness: placement ----------------------------------------------
// Owned by `docs/freshness.md` in bob-cli; the Rust half is
// `src/native/freshness/placement.rs`. Both sides run the placement (P)
// conformance vectors in that doc verbatim.
//
// Placement is the exception to the copy-small-helpers rule: nav,
// task-status-cycler and block-id-prompt call
// `api?.freshness?.stampLine?.(line, dateText) ?? line` (api
// `version >= 3`) instead of placing `fresh` themselves. A missing stamp
// only means Bryan sees the task once more; a misplaced stamp hides
// Tasks fields — so the risky part lives here, and when ledger-tools is
// absent or old the gesture simply doesn't stamp.

// Tasks keys recognized at the end of a Dataview task line, in the order
// `docs/freshness.md` pins them.
const FRESHNESS_TASKS_KEYS = [
  "priority",
  "start",
  "created",
  "scheduled",
  "due",
  "completion",
  "cancelled",
  "repeat",
  "onCompletion",
  "id",
  "dependsOn",
];

// Any `[key:: value]` or `(key:: value)` field, with the key matched
// case-sensitively and any spacing allowed around `::`. Mirrors the Rust
// `INLINE_FIELD_RE` in `task_fields.rs`.
const FRESHNESS_INLINE_FIELD_SOURCE =
  "\\[([A-Za-z][A-Za-z0-9_-]*)\\s*::\\s*([^\\]\n]*)\]|\\(([A-Za-z][A-Za-z0-9_-]*)\\s*::\\s*([^)\n]*)\\)";

// Every `key` field on `line`, in line order: `{ start, end, value }`
// with UTF-16 offsets into `line`. The key match is case-sensitive and
// the value is trimmed of spaces/tabs only, like the Rust scanner.
function freshnessInlineFields(line, key) {
  const text = String(line || "");
  const pattern = new RegExp(FRESHNESS_INLINE_FIELD_SOURCE, "g");
  const out = [];
  let match = pattern.exec(text);
  while (match !== null) {
    const matchedKey = match[1] !== undefined ? match[1] : match[3];
    const raw = match[1] !== undefined ? match[2] : match[4];
    if (matchedKey === key) {
      const value = raw.replace(/^[ \t]+|[ \t]+$/g, "");
      out.push({ start: match.index, end: match.index + match[0].length, value });
    }
    match = pattern.exec(text);
  }
  return out;
}

function freshnessIsLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

// A strict `YYYY-MM-DD` calendar date, else null. Anything else —
// including out-of-range months and days — is rejected, like the Rust
// `parse_strict_calendar_date`.
function parseFreshDateStrict(value) {
  const text = String(value || "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return null;
  }
  const year = Number(text.slice(0, 4));
  const month = Number(text.slice(5, 7));
  const day = Number(text.slice(8, 10));
  if (month < 1 || month > 12 || day < 1) {
    return null;
  }
  const daysInMonth = [
    31,
    freshnessIsLeapYear(year) ? 29 : 28,
    31, 30, 31, 30, 31, 31, 30, 31, 30, 31,
  ][month - 1];
  if (day > daysInMonth) {
    return null;
  }
  return text;
}

function freshDateToUtc(text) {
  return Date.UTC(
    Number(text.slice(0, 4)),
    Number(text.slice(5, 7)) - 1,
    Number(text.slice(8, 10)),
  );
}

function freshPad2(number) {
  return String(number).padStart(2, "0");
}

// Add `days` to a canonical date. DST-safe via UTC noon arithmetic.
function freshDateAddDays(text, days) {
  const shifted = new Date(freshDateToUtc(text) + days * 86400000);
  return (
    String(shifted.getUTCFullYear()).padStart(4, "0") +
    "-" +
    freshPad2(shifted.getUTCMonth() + 1) +
    "-" +
    freshPad2(shifted.getUTCDate())
  );
}

// Whole days from `from` to `to` (both canonical dates).
function freshDateDiffDays(from, to) {
  return Math.round((freshDateToUtc(to) - freshDateToUtc(from)) / 86400000);
}

// Drop leading `>` quote markers the way the vault scanner does (up to
// three spaces, `>`, one optional space, repeated). Quoted tasks are
// still tasks; the `>` bytes stay in place on write.
function freshnessStripBlockquotePrefix(line) {
  let rest = String(line || "");
  for (;;) {
    const spaces = rest.match(/^ */)[0].length;
    if (spaces > 3 || rest[spaces] !== ">") {
      return rest;
    }
    rest = rest.slice(spaces + 1);
    if (rest.startsWith(" ")) {
      rest = rest.slice(1);
    }
  }
}

function freshnessAfterListMarker(line, index) {
  if (line[index] === "-" || line[index] === "*" || line[index] === "+") {
    return line[index + 1] !== undefined &&
      /\s/.test(line[index + 1])
      ? index + 1
      : null;
  }
  const digits = (line.slice(index).match(/^\d+/) || [""])[0].length;
  if (
    digits === 0 ||
    (line[index + digits] !== "." && line[index + digits] !== ")")
  ) {
    return null;
  }
  return line[index + digits + 1] !== undefined &&
    /\s/.test(line[index + digits + 1])
    ? index + digits + 1
    : null;
}

// The checkbox status char on a task line, or null when `line` is not a
// task line.
function freshnessTaskStatus(line) {
  const stripped = freshnessStripBlockquotePrefix(line);
  let index = 0;
  while (stripped[index] === " " || stripped[index] === "\t") {
    index += 1;
  }
  const after = freshnessAfterListMarker(stripped, index);
  if (after === null) {
    return null;
  }
  index = after;
  while (stripped[index] !== undefined && /\s/.test(stripped[index])) {
    index += 1;
  }
  if (stripped[index] !== "[") {
    return null;
  }
  const close = stripped.indexOf("]", index + 1);
  if (close === -1) {
    return null;
  }
  const inner = stripped.slice(index + 1, close);
  if ([...inner].length !== 1) {
    return null;
  }
  const trailing = stripped.slice(close + 1);
  if (trailing !== "" && !/^\s/.test(trailing)) {
    return null;
  }
  return inner;
}

function freshnessIsClosedStatus(status) {
  return status === "x" || status === "X" || status === "-";
}

function freshnessHasRepeatField(line) {
  return freshnessInlineFields(line, "repeat").length > 0;
}

// A `[refresh:: N]` value: an integer 1-365, nothing else.
function freshnessParseRefreshValue(value) {
  const trimmed = String(value || "").trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    return null;
  }
  const number = Number(trimmed);
  if (!Number.isSafeInteger(number) || number < 1 || number > 365) {
    return null;
  }
  return number;
}

function freshnessFirstValidRefresh(line) {
  const fields = freshnessInlineFields(line, "refresh");
  for (const field of fields) {
    const days = freshnessParseRefreshValue(field.value);
    if (days !== null) {
      return days;
    }
  }
  return null;
}

// A `[keeps:: N]` value: a decimal integer 1-999, nothing else.
// Absence means 0 and writers omit zero. Mirrors `parse_keeps_value`
// in `src/native/freshness/placement.rs`.
function freshnessParseKeepsValue(value) {
  const trimmed = String(value || "").trim();
  if (trimmed === "" || !/^[0-9]+$/.test(trimmed)) {
    return null;
  }
  const number = Number(trimmed);
  if (!Number.isSafeInteger(number) || number < 1 || number > 999) {
    return null;
  }
  return number;
}

function freshnessFirstValidKeeps(line) {
  const fields = freshnessInlineFields(line, "keeps");
  for (const field of fields) {
    const count = freshnessParseKeepsValue(field.value);
    if (count !== null) {
      return count;
    }
  }
  return null;
}

// The scan floor: the start of the task body, or the end of a leading
// `#task` global-filter token. The suffix scan never moves left of it.
// Quote markers are detection-only: the floor is shifted back into the
// original line's coordinates.
function freshnessScanFloor(line) {
  const text = String(line || "");
  const stripped = freshnessStripBlockquotePrefix(text);
  const offset = text.length - stripped.length;
  let index = 0;
  while (stripped[index] === " " || stripped[index] === "\t") {
    index += 1;
  }
  const after = freshnessAfterListMarker(stripped, index);
  if (after === null) {
    return null;
  }
  index = after;
  while (stripped[index] !== undefined && /\s/.test(stripped[index])) {
    index += 1;
  }
  const close = stripped.indexOf("]", index);
  if (close === -1) {
    return null;
  }
  let bodyStart = close + 1;
  while (stripped[bodyStart] === " " || stripped[bodyStart] === "\t") {
    bodyStart += 1;
  }
  const body = stripped.slice(bodyStart);
  if (
    body === "#task" ||
    body.startsWith("#task ") ||
    body.startsWith("#task\t")
  ) {
    return offset + bodyStart + "#task".length;
  }
  return offset + bodyStart;
}

function freshnessTrimEndTo(text, cursor) {
  let end = Math.min(cursor, text.length);
  while (end > 0 && (text[end - 1] === " " || text[end - 1] === "\t")) {
    end -= 1;
  }
  return end;
}

// Start of a trailing ` ^id` block link, if `text` ends with one.
function freshnessTrailingBlockStart(text) {
  const trimmed = text.replace(/[ \t]+$/, "");
  const tokenStart = (() => {
    const last = Math.max(trimmed.lastIndexOf(" "), trimmed.lastIndexOf("\t"));
    return last === -1 ? 0 : last + 1;
  })();
  const token = trimmed.slice(tokenStart);
  if (!token.startsWith("^")) {
    return null;
  }
  const id = token.slice(1);
  if (!id || !/^[A-Za-z0-9-]+$/.test(id)) {
    return null;
  }
  if (tokenStart > 0) {
    const before = trimmed[tokenStart - 1];
    if (before !== " " && before !== "\t") {
      return null;
    }
  }
  return text.replace(/[ \t]+$/, "").length - token.length;
}

// Start of a trailing `#tag`, if `trimmed` (already right-trimmed) ends
// with one starting at or after `floor`.
function freshnessTrailingTagStart(trimmed, floor) {
  const last = Math.max(trimmed.lastIndexOf(" "), trimmed.lastIndexOf("\t"));
  const tokenStart = last === -1 ? 0 : last + 1;
  const start = Math.max(tokenStart, floor);
  const token = trimmed.slice(start);
  if (!token.startsWith("#")) {
    return null;
  }
  if (start > floor) {
    const before = trimmed[start - 1];
    if (before !== " " && before !== "\t") {
      return null;
    }
  }
  const value = token.slice(1);
  if (!value || /[\s!@#$%^&*(),.?":{}|<>]/.test(value)) {
    return null;
  }
  return start;
}

// The `(start, key)` of a trailing `[k:: v]` / `(k:: v)` field: the key
// must equal its trim.
function freshnessTrailingFieldKey(trimmed) {
  let end = trimmed.length;
  if (trimmed.endsWith(",")) {
    end -= 1;
    end = trimmed.slice(0, end).replace(/[ \t]+$/, "").length;
  }
  const head = trimmed.slice(0, end);
  const close = head[head.length - 1];
  const open = close === "]" ? "[" : close === ")" ? "(" : null;
  if (open === null) {
    return null;
  }
  const withoutClose = head.slice(0, -1);
  const start = withoutClose.lastIndexOf(open);
  if (start === -1) {
    return null;
  }
  const inner = withoutClose.slice(start + 1).trim();
  const separator = inner.indexOf("::");
  if (separator === -1) {
    return null;
  }
  const key = inner.slice(0, separator);
  if (key !== key.trim() || !key.trim()) {
    return null;
  }
  return { start, key: key.trim() };
}

// Byte offset where the trailing Tasks suffix starts. The suffix starts
// at the leftmost Tasks element (a Tasks-key field, a trailing tag, or
// `^id`) of the run scanned from the end of the line. `fresh` /
// `refresh` / `keeps` / `unblocked` fields extend the run but are not
// part of the suffix. They are run-extending non-Tasks keys: never add
// them to the Tasks key registry. Returns the trimmed length when
// there is no suffix.
function freshnessTasksSuffixStart(line) {
  const text = String(line || "");
  const floor = freshnessScanFloor(text);
  if (floor === null) {
    return text.replace(/[ \t\n\r]+$/, "").length;
  }
  const trimmedLen = text.replace(/[ \t\n\r]+$/, "").length;
  let cursor = trimmedLen;
  let leftmost = null;

  const blockStart = freshnessTrailingBlockStart(text.slice(0, cursor));
  if (blockStart !== null && blockStart >= floor) {
    leftmost = blockStart;
    cursor = freshnessTrimEndTo(text.slice(0, blockStart), blockStart);
  }

  for (;;) {
    if (cursor <= floor) {
      break;
    }
    const slice = text.slice(0, cursor);
    const trimmed = slice.replace(/[ \t\n\r]+$/, "");
    const end = trimmed.length;
    if (end <= floor) {
      break;
    }
    const tagStart = freshnessTrailingTagStart(trimmed, floor);
    if (tagStart !== null) {
      leftmost = tagStart;
      cursor = freshnessTrimEndTo(text.slice(0, tagStart), tagStart);
      continue;
    }
    const trailingBlock = freshnessTrailingBlockStart(trimmed);
    if (trailingBlock !== null && trailingBlock >= floor) {
      leftmost = trailingBlock;
      cursor = freshnessTrimEndTo(text.slice(0, trailingBlock), trailingBlock);
      continue;
    }
    const field = freshnessTrailingFieldKey(trimmed);
    if (!field) {
      break;
    }
    if (field.start < floor) {
      break;
    }
    if (FRESHNESS_TASKS_KEYS.includes(field.key)) {
      leftmost = field.start;
      cursor = freshnessTrimEndTo(text.slice(0, field.start), field.start);
      continue;
    }
    if (
      field.key === "fresh" ||
      field.key === "refresh" ||
      field.key === "keeps" ||
      field.key === "unblocked"
    ) {
      cursor = freshnessTrimEndTo(text.slice(0, field.start), field.start);
      continue;
    }
    break;
  }

  return leftmost === null ? trimmedLen : leftmost;
}

// Remove selected freshness fields from `text`, collapsing the
// whitespace each removal leaves to a single space.
function freshnessRemoveNamedFields(text, names) {
  const ranges = [];
  for (const name of names) {
    for (const field of freshnessInlineFields(text, name)) {
      ranges.push([field.start, field.end]);
    }
  }
  if (ranges.length === 0) {
    return text;
  }
  ranges.sort((left, right) => left[0] - right[0] || left[1] - right[1]);

  let output = "";
  let cursor = 0;
  for (const [start, end] of ranges) {
    const before = text.slice(cursor, start).replace(/[ \t]+$/, "");
    output += before;
    let next = end;
    while (text[next] === " " || text[next] === "\t") {
      next += 1;
    }
    if (output !== "" && next < text.length) {
      output += " ";
    }
    cursor = next;
  }
  output += text.slice(cursor);
  return output;
}

function freshnessRemoveFields(text) {
  return freshnessRemoveNamedFields(text, [
    "fresh",
    "refresh",
    "keeps",
    "unblocked",
  ]);
}

// Rebuild `line` with `[fresh:: dateText]` (plus `[refresh:: N]` and
// `[keeps:: N]` when kept) immediately before the Tasks suffix.
// Output order is `fresh`, optional `refresh`, optional `keeps`, then
// the existing Tasks suffix, tags, and block ID. The suffix bytes
// themselves are never changed.
function freshnessRebuildWithoutFields(
  line,
  dateText,
  keptRefresh,
  keptKeeps,
) {
  const text = String(line || "");
  const trimmedLen = text.replace(/[ \t\n\r]+$/, "").length;
  const suffixStart = Math.min(freshnessTasksSuffixStart(text), trimmedLen);
  const headClean = freshnessRemoveFields(text.slice(0, suffixStart));
  const suffixClean = freshnessRemoveFields(text.slice(suffixStart, trimmedLen));
  const head = headClean.replace(/[ \t\n\r]+$/, "");
  const suffix = suffixClean.trim().replace(/^[ \t]+/, "");

  let output = head + " [fresh:: " + dateText + "]";
  if (keptRefresh !== null && keptRefresh !== undefined) {
    output += " [refresh:: " + keptRefresh + "]";
  }
  if (keptKeeps !== null && keptKeeps !== undefined) {
    output += " [keeps:: " + keptKeeps + "]";
  }
  if (suffix !== "") {
    output += " " + suffix;
  }
  return output;
}

function freshnessTodayFallback() {
  return formatLocalDate(new Date());
}

function freshnessNormalizeDateText(dateText) {
  return parseFreshDateStrict(dateText) || freshnessTodayFallback();
}

// Stamp `line` with `dateText`, keeping the first valid existing
// `[refresh:: N]` if there is one. Every generic human stamp clears
// `keeps`: the line is rewritten without any `keeps` field, even when
// `dateText` already equals today. Refusals (not a task, recurring,
// done/cancelled) return the line unchanged with a reason. A line
// already stamped with `dateText` in canonical position — and with no
// `keeps` to clear — is byte-identical with `changed: false`.
function freshnessStampLine(line, dateText) {
  const text = String(line || "");
  const day = freshnessNormalizeDateText(dateText);
  const status = freshnessTaskStatus(text);
  if (status === null) {
    return { line: text, changed: false, refused: "not_task" };
  }
  if (freshnessIsClosedStatus(status)) {
    return { line: text, changed: false, refused: "closed" };
  }
  if (freshnessHasRepeatField(text)) {
    return { line: text, changed: false, refused: "recurring" };
  }
  const output = freshnessRebuildWithoutFields(
    text,
    day,
    freshnessFirstValidRefresh(text),
    null,
  );
  return { line: output, changed: output !== text, refused: null };
}

function freshnessHasHiddenTag(line) {
  return /(?:^|[ \t])#hide(?=$|[ \t])/i.test(String(line || ""));
}

function freshnessFirstValidDate(line, name) {
  for (const field of freshnessInlineFields(line, name)) {
    const date = parseFreshDateStrict(field.value);
    if (date !== null) {
      return date;
    }
  }
  return null;
}

// Return the source of a due Ready resurfacing, if this line is in the
// freshness scope. Scheduled wins a tie with an unblock date. keepLine uses
// this so an unblock review does not alter the keep streak.
function freshnessReturnedByFromLine(line, todayText, options = {}) {
  try {
    const text = String(line || "");
    const today = freshnessNormalizeDateText(todayText);
    const settings = options && typeof options === "object" ? options : {};
    if (freshnessTaskStatus(text) !== " ") {
      return null;
    }
    if (
      freshnessHasRepeatField(text) ||
      freshnessHasHiddenTag(text) ||
      Boolean(settings.recurring) ||
      Boolean(settings.hidden) ||
      Boolean(settings.isDailyNote) ||
      Boolean(settings.isToday)
    ) {
      return null;
    }
    const read = readFreshness(text, today);
    if (read.fresh === null) {
      return null;
    }
    const scheduled = freshnessFirstValidDate(text, "scheduled");
    const scheduledReturn =
      scheduled !== null && read.fresh < scheduled && scheduled <= today
        ? scheduled
        : null;
    const unblockedReturn =
      read.unblocked !== null &&
      read.fresh <= read.unblocked &&
      read.unblocked <= today
        ? read.unblocked
        : null;
    if (
      scheduledReturn !== null &&
      (unblockedReturn === null || scheduledReturn >= unblockedReturn)
    ) {
      return "scheduled";
    }
    return unblockedReturn === null ? null : "unblocked";
  } catch (error) {
    return null;
  }
}

// Record an automatic Blocked → Ready recovery when it needs to re-enter
// review. The existing freshness group is kept exactly as written and this
// never creates a fresh stamp. Extra scope flags let callers exclude daily
// notes and Today-linked tasks, which cannot be inferred from a line alone.
function freshnessMarkUnblockedLine(line, options = {}) {
  try {
    const text = String(line || "");
    const settings = options && typeof options === "object" ? options : {};
    const today = freshnessNormalizeDateText(settings.today);
    const status =
      settings.status === undefined || settings.status === null
        ? freshnessTaskStatus(text)
        : String(settings.status)[0];
    if (
      status !== " " ||
      freshnessTaskStatus(text) === null ||
      freshnessIsClosedStatus(status) ||
      freshnessHasRepeatField(text) ||
      freshnessHasHiddenTag(text) ||
      Boolean(settings.recurring) ||
      Boolean(settings.hidden) ||
      Boolean(settings.isDailyNote) ||
      Boolean(settings.isToday)
    ) {
      return text;
    }

    const read = readFreshness(text, today);
    if (read.fresh === null) {
      return text;
    }
    const scheduled = freshnessFirstValidDate(text, "scheduled");
    if (
      scheduled !== null &&
      read.fresh < scheduled &&
      scheduled <= today
    ) {
      return text;
    }

    const withoutUnblocked = freshnessRemoveNamedFields(text, ["unblocked"]);
    const trimmedLen = withoutUnblocked.replace(/[ \t\n\r]+$/, "").length;
    const suffixStart = Math.min(
      freshnessTasksSuffixStart(withoutUnblocked),
      trimmedLen,
    );
    const head = withoutUnblocked
      .slice(0, suffixStart)
      .replace(/[ \t\n\r]+$/, "");
    const suffix = withoutUnblocked
      .slice(suffixStart, trimmedLen)
      .trim()
      .replace(/^[ \t]+/, "");
    return (
      head +
      " [unblocked:: " +
      today +
      "]" +
      (suffix === "" ? "" : " " + suffix)
    );
  } catch (error) {
    return String(line || "");
  }
}

// The sole increment helper (`docs/freshness.md` §2a): stamp `line`
// with `dateText` while counting one due-Ready bare keep. `options`
// carries `{ counted }`: a counted keep increments the valid semantic
// streak by one (saturating at 999; absence means 0 so the first
// counted keep writes 1), while an uncounted keep preserves the valid
// semantic value. Both paths canonicalize and repair
// malformed/duplicate placement. A valid prior `fresh < today` is
// independently required before incrementing, even when `counted` is
// true, so NEW and same-day lines never inflate under stale caches or
// repeated events — those stamp and preserve instead. Refusals match
// the generic stamper. Rust reads, clears, and reports `keeps`; it has
// no increment path.
function freshnessKeepLine(line, dateText, options) {
  const text = String(line || "");
  const day = freshnessNormalizeDateText(dateText);
  const status = freshnessTaskStatus(text);
  if (status === null) {
    return { line: text, changed: false, refused: "not_task" };
  }
  if (freshnessIsClosedStatus(status)) {
    return { line: text, changed: false, refused: "closed" };
  }
  if (freshnessHasRepeatField(text)) {
    return { line: text, changed: false, refused: "recurring" };
  }
  const counted =
    options !== null &&
    options !== undefined &&
    typeof options === "object" &&
    Boolean(options.counted);
  const read = readFreshness(text, day);
  const priorValid = read.fresh !== null && read.fresh < day;
  const returnedBy = freshnessReturnedByFromLine(text, day, options);
  let keptKeeps = null;
  if (counted && priorValid && returnedBy !== "unblocked") {
    keptKeeps = Math.min(read.keeps + 1, 999);
  } else if (read.keeps > 0) {
    keptKeeps = read.keeps;
  }
  const output = freshnessRebuildWithoutFields(
    text,
    day,
    freshnessFirstValidRefresh(text),
    keptKeeps,
  );
  return { line: output, changed: output !== text, refused: null };
}

// Set or clear `[refresh:: N]` and stamp with `dateText`. A value
// outside 1-365 clears the field instead of writing an invalid one,
// like the Rust `set_refresh`.
function freshnessSetRefreshLine(line, days, dateText) {
  const text = String(line || "");
  const day = freshnessNormalizeDateText(dateText);
  let normalized = days;
  if (typeof normalized === "string" && /^[+-]?\d+$/.test(normalized.trim())) {
    normalized = Number(normalized.trim());
  }
  const edit =
    Number.isSafeInteger(normalized) && normalized >= 1 && normalized <= 365
      ? normalized
      : null;
  const status = freshnessTaskStatus(text);
  if (status === null) {
    return { line: text, changed: false, refused: "not_task" };
  }
  if (freshnessIsClosedStatus(status)) {
    return { line: text, changed: false, refused: "closed" };
  }
  if (freshnessHasRepeatField(text)) {
    return { line: text, changed: false, refused: "recurring" };
  }
  const output = freshnessRebuildWithoutFields(text, day, edit, null);
  return { line: output, changed: output !== text, refused: null };
}

function freshnessPushLint(lints, code) {
  if (!lints.includes(code)) {
    lints.push(code);
  }
}

// Read the `fresh` / `refresh` / `keeps` / `unblocked` fields on `line`: the latest
// valid `fresh` date not after `todayText` (a future date is treated
// as none), the first valid `[refresh:: N]`, the first valid
// `[keeps:: N]` semantic count (0 when absent or when no value is
// valid), the latest valid `[unblocked:: YYYY-MM-DD]`, and lint codes
// in first-seen order. Mirrors `read_freshness`
// in `src/native/freshness/placement.rs`.
function readFreshness(line, todayText) {
  const text = String(line || "");
  const today = freshnessNormalizeDateText(todayText);
  const freshFields = freshnessInlineFields(text, "fresh");
  const refreshFields = freshnessInlineFields(text, "refresh");
  const keepsFields = freshnessInlineFields(text, "keeps");
  const unblockedFields = freshnessInlineFields(text, "unblocked");
  const lints = [];

  let best = null;
  for (const field of freshFields) {
    const date = parseFreshDateStrict(field.value.trim());
    if (date === null) {
      freshnessPushLint(lints, "fresh_malformed");
    } else if (date > today) {
      freshnessPushLint(lints, "fresh_future");
    } else if (best === null || date > best) {
      best = date;
    }
  }
  if (freshFields.length > 1) {
    freshnessPushLint(lints, "fresh_duplicate");
  }

  let refresh = null;
  let refreshInvalidSeen = false;
  for (const field of refreshFields) {
    const days = freshnessParseRefreshValue(field.value);
    if (days === null) {
      refreshInvalidSeen = true;
    } else if (refresh === null) {
      refresh = days;
    }
  }
  if (refreshInvalidSeen) {
    freshnessPushLint(lints, "refresh_invalid");
  }

  let keeps = null;
  let keepsInvalidSeen = false;
  for (const field of keepsFields) {
    const count = freshnessParseKeepsValue(field.value);
    if (count === null) {
      keepsInvalidSeen = true;
    } else if (keeps === null) {
      keeps = count;
    }
  }
  if (keepsInvalidSeen) {
    freshnessPushLint(lints, "keeps_invalid");
  }
  if (keepsFields.length > 1) {
    freshnessPushLint(lints, "keeps_duplicate");
  }

  let unblocked = null;
  let unblockedInvalidSeen = false;
  for (const field of unblockedFields) {
    const date = parseFreshDateStrict(field.value);
    if (date === null) {
      unblockedInvalidSeen = true;
    } else if (unblocked === null || date > unblocked) {
      unblocked = date;
    }
  }
  if (unblockedInvalidSeen) {
    freshnessPushLint(lints, "unblocked_malformed");
  }
  if (unblockedFields.length > 1) {
    freshnessPushLint(lints, "unblocked_duplicate");
  }

  const suffixStart = freshnessTasksSuffixStart(text);
  const trimmedLen = text.replace(/[ \t\n\r]+$/, "").length;
  if (suffixStart < trimmedLen) {
    const misplaced = (name) =>
      freshnessInlineFields(text, name).some(
        (field) => field.start >= suffixStart,
      );
    if (
      misplaced("fresh") ||
      misplaced("refresh") ||
      misplaced("keeps") ||
      misplaced("unblocked")
    ) {
      freshnessPushLint(lints, "fresh_misplaced");
    }
  }

  return {
    fresh: best,
    refresh,
    keeps: keeps === null ? 0 : keeps,
    unblocked,
    lints,
  };
}

// ---- src/090-freshness-config.js ----
// --- Task freshness: config -------------------------------------------------
// Beside `planCapsBlock` / `coercePlanCaps`: the `freshness:` block in
// `~/.config/bob/config.yml` (`interval`, `pending_interval`,
// `next_interval`, `rotten_daily_budget`, `decay`).
// The removed `stale_daily_budget` key still supplies the budget for
// one release with a deprecation lint.
// Mirrors `docs/freshness.md` §§2-2a in bob-cli (freshness namespace v8).

// Whether the compatible review-walk decision card is present: nav exposes
// `api.freshnessDecayCard.version >= 2` (ungated handler contract). Version
// 1 still gated by date and cannot fulfill an immediate-availability
// promise. The leaf, the `Alt+F to decide` key hint, and the "asks"
// promise stay gated behind it so a mixed-version session degrades to
// counting pips with truthful counting-only wording — never a promise
// the installed nav cannot keep. Never throws.
function freshnessDecayCardCapable(app) {
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const holder = plugins ? plugins["bob-navigation-hotkeys"] : null;
    const api = holder ? holder.api : null;
    const card = api ? api.freshnessDecayCard : null;
    return Boolean(card) && Number(card.version) >= 2;
  } catch (error) {
    return false;
  }
}

function defaultFreshnessConfig() {
  return {
    interval: 7,
    pendingInterval: 1,
    nextInterval: 1,
    projectInterval: null,
    rottenDailyBudget: null,
    decay: { enabled: true, keeps: 3, enter: null },
  };
}

// Normalize the `freshness.decay` value: absent, null, `true`, or an
// empty mapping means enabled with 3 keeps; `false` disables asking
// while keeping counting and display; a mapping may set `keeps`
// (integer 0-999) and `enter` (a nonempty priority label). Anything
// else is invalid under the freshness failure contract. Mirrors
// `parse_decay_config` in `src/native/config/freshness.rs`.
function coerceFreshnessDecay(raw) {
  const defaults = () => ({ enabled: true, keeps: 3, enter: null });
  if (raw === undefined || raw === null || raw === true) {
    return { decay: defaults(), invalid: false };
  }
  if (raw === false) {
    return { decay: { enabled: false, keeps: 3, enter: null }, invalid: false };
  }
  if (typeof raw !== "object" || Array.isArray(raw)) {
    return { decay: defaults(), invalid: true };
  }
  let keeps = 3;
  const keepsRaw = raw.keeps;
  if (keepsRaw !== undefined && keepsRaw !== null) {
    if (
      typeof keepsRaw !== "number" ||
      !Number.isInteger(keepsRaw) ||
      keepsRaw < 0 ||
      keepsRaw > 999
    ) {
      return { decay: defaults(), invalid: true };
    }
    keeps = keepsRaw;
  }
  let enter = null;
  const enterRaw = raw.enter;
  if (enterRaw !== undefined && enterRaw !== null) {
    if (typeof enterRaw !== "string" || enterRaw.trim() === "") {
      return { decay: defaults(), invalid: true };
    }
    enter = enterRaw.trim();
  }
  return { decay: { enabled: true, keeps, enter }, invalid: false };
}

// Whether a choice is due for a Ready-lane row in `tier` with `keeps`
// counted keeps under `config`: enabled decay, Ready lane,
// rotten/tickler tier, keeps at or over the limit. The annotation
// means a choice is due, not permission to execute an action. Mirrors
// `decide_for` in `src/native/freshness/state.rs`.
function freshnessDecideFor(lane, tier, keeps, config, returnedBy) {
  try {
    const dueTier =
      (tier === "rotten" || tier === "tickler") &&
      returnedBy !== "unblocked";
    if (!dueTier || lane !== "ready") {
      return false;
    }
    const decay =
      config && config.decay && typeof config.decay === "object"
        ? config.decay
        : { enabled: true, keeps: 3 };
    if (!decay.enabled) {
      return false;
    }
    const limit =
      Number.isInteger(decay.keeps) && decay.keeps >= 0 ? decay.keeps : 3;
    const count = Number.isInteger(keeps) && keeps >= 0 ? keeps : 0;
    return count >= limit;
  } catch (error) {
    return false;
  }
}

// The raw `freshness:` block out of a parsed config file, or undefined
// when the file holds no such block. A present-but-bad block (null is
// fine, anything else that is not a mapping is not) is returned as-is
// so `coerceFreshnessConfig` can flag it; unknown keys stay ignored.
function freshnessBlock(yamlObject) {
  if (
    !yamlObject ||
    typeof yamlObject !== "object" ||
    Array.isArray(yamlObject)
  ) {
    return undefined;
  }
  const block = yamlObject.freshness;
  return block === undefined ? undefined : block;
}

function coerceFreshnessConfig(block) {
  const defaults = defaultFreshnessConfig();
  const fallback = () => ({
    config: { ...defaults, intervalFromConfig: false },
    invalid: false,
  });
  if (block === undefined || block === null) {
    return fallback();
  }
  if (typeof block !== "object" || Array.isArray(block)) {
    return {
      config: { ...defaults, intervalFromConfig: false },
      invalid: true,
    };
  }
  // Snake_case keys, with camelCase tolerated like the plan caps.
  const pick = (snake, camel) =>
    block[snake] !== undefined ? block[snake] : block[camel];
  let invalid = false;
  let interval = defaults.interval;
  let intervalFromConfig = false;
  const rawInterval = pick("interval", "interval");
  if (rawInterval !== undefined && rawInterval !== null) {
    if (
      typeof rawInterval === "number" &&
      Number.isInteger(rawInterval) &&
      rawInterval >= 1 &&
      rawInterval <= 365
    ) {
      interval = rawInterval;
      intervalFromConfig = true;
    } else {
      invalid = true;
    }
  }
  // The canonical `rotten_daily_budget` wins by presence, including
  // an explicit null (budget off). The removed `stale_daily_budget`
  // still supplies the budget for one release; when both occur the
  // legacy value is warned about and ignored.
  const rawCanonical =
    block.rotten_daily_budget !== undefined
      ? block.rotten_daily_budget
      : block.rottenDailyBudget;
  const rawLegacy =
    block.stale_daily_budget !== undefined
      ? block.stale_daily_budget
      : block.staleDailyBudget;
  const legacyPresent = rawLegacy !== undefined && rawLegacy !== null;
  let budget = defaults.rottenDailyBudget;
  let deprecatedStaleBudget = false;
  const coerceBudget = (raw) =>
    typeof raw === "number" && Number.isInteger(raw) && raw >= 1
      ? raw
      : null;
  if (rawCanonical !== undefined) {
    if (rawCanonical !== null) {
      const coerced = coerceBudget(rawCanonical);
      if (coerced === null) {
        invalid = true;
      } else {
        budget = coerced;
      }
    }
    deprecatedStaleBudget = legacyPresent;
  } else if (rawLegacy !== undefined) {
    if (rawLegacy !== null) {
      const coerced = coerceBudget(rawLegacy);
      if (coerced === null) {
        invalid = true;
      } else {
        budget = coerced;
        deprecatedStaleBudget = true;
      }
    }
  }
  // Lane intervals: absent or null means the default 1, `false`
  // turns that lane's walk off, an integer 1-365 sets it. Anything
  // else (including `true`, 0, 366, strings, floats) is a config
  // error shaped like `interval`'s. Mirrors `parse_lane_interval`
  // in `src/native/config/freshness.rs`.
  const coerceLaneInterval = (raw) => {
    if (raw === undefined || raw === null) {
      return { days: 1, invalid: false };
    }
    if (raw === false) {
      return { days: null, invalid: false };
    }
    if (
      typeof raw === "number" &&
      Number.isInteger(raw) &&
      raw >= 1 &&
      raw <= 365
    ) {
      return { days: raw, invalid: false };
    }
    return { days: 1, invalid: true };
  };
  const rawPending = pick("pending_interval", "pendingInterval");
  const pendingCoerced = coerceLaneInterval(rawPending);
  if (pendingCoerced.invalid) {
    invalid = true;
  }
  const rawNext = pick("next_interval", "nextInterval");
  const nextCoerced = coerceLaneInterval(rawNext);
  if (nextCoerced.invalid) {
    invalid = true;
  }
  // Project interval: absent or null inherits; an integer 1-365 sets
  // the explicit cadence. Mirrors `parse_tracker_interval` in Rust.
  const coerceTrackerInterval = (raw) => {
    if (raw === undefined || raw === null) {
      return { days: null, invalid: false };
    }
    if (typeof raw === "boolean") {
      return { days: null, invalid: true };
    }
    if (
      typeof raw === "number" &&
      Number.isInteger(raw) &&
      raw >= 1 &&
      raw <= 365
    ) {
      return { days: raw, invalid: false };
    }
    return { days: null, invalid: true };
  };
  const rawProject = pick("project_interval", "projectInterval");
  const projectCoerced = coerceTrackerInterval(rawProject);
  if (projectCoerced.invalid) {
    invalid = true;
  }
  // Keep-streak policy: absent, null, `true`, or `{}` means enabled
  // with 3 keeps; `false` keeps counting/display but never asks;
  // `keeps` 0-999 and a nonempty `enter` label otherwise. Mirrors
  // `parse_decay_config` in `src/native/config/freshness.rs`.
  const decayCoerced = coerceFreshnessDecay(block.decay);
  if (decayCoerced.invalid) {
    invalid = true;
  }
  // Like Rust, any invalid value falls back to the full default block.
  if (invalid) {
    return {
      config: { ...defaults, intervalFromConfig: false },
      invalid: true,
    };
  }
  return {
    config: {
      interval,
      pendingInterval: pendingCoerced.days,
      nextInterval: nextCoerced.days,
      projectInterval: projectCoerced.days,
      rottenDailyBudget: budget,
      intervalFromConfig,
      deprecatedStaleBudget,
      decay: decayCoerced.decay,
    },
    invalid: false,
  };
}

// Read `freshness:` from `~/.config/bob/config.yml` (honoring
// XDG_CONFIG_HOME), with the same injectable options as `loadPlanCaps`.
// Mobile (no desktop `fs`) and a missing file fall back to the defaults.
// Returns `{ config, invalid, configPath }`; `invalid` is true only when
// the file was read but held a present-but-bad value.
function loadFreshnessConfig(options = {}) {
  const defaults = defaultFreshnessConfig();
  const freshDefaults = () => ({ ...defaults, intervalFromConfig: false });
  const configPath = options.configPath || planConfigPath(options);
  const platform = options.Platform === undefined ? Platform : options.Platform;
  if (platform && platform.isDesktopApp === false) {
    return { config: freshDefaults(), invalid: false, configPath };
  }
  const fsModule =
    options.fsModule === undefined
      ? planRequireOptionalNodeModule("fs")
      : options.fsModule;
  if (!fsModule || typeof fsModule.readFileSync !== "function") {
    return { config: freshDefaults(), invalid: false, configPath };
  }
  let rawConfig;
  try {
    rawConfig = fsModule.readFileSync(configPath, "utf8");
  } catch (error) {
    return {
      config: freshDefaults(),
      invalid: Boolean(error && error.code && error.code !== "ENOENT"),
      configPath,
    };
  }
  const yamlParser =
    options.parseYaml === undefined ? parseYaml : options.parseYaml;
  if (typeof yamlParser !== "function") {
    return { config: freshDefaults(), invalid: false, configPath };
  }
  let parsed;
  try {
    parsed = yamlParser(rawConfig);
  } catch (error) {
    return { config: freshDefaults(), invalid: true, configPath };
  }
  const coerced = coerceFreshnessConfig(freshnessBlock(parsed));
  return { config: coerced.config, invalid: coerced.invalid, configPath };
}
// ---- src/100-freshness-evaluate.js ----
// --- Task freshness: evaluation ---------------------------------------------
// Computed at read time, never stored. Mirrors `state.rs`; both sides run
// the state (S) conformance vectors in `docs/freshness.md` verbatim.

// Parse a note's raw `task_refresh` frontmatter value: an integer 1-365
// (numbers stay numbers, quoted strings are unquoted), else a
// `task_refresh_invalid` lint that falls through to the next level.
function freshnessParseNoteRefresh(raw) {
  if (raw === undefined || raw === null) {
    return { days: null, lint: null };
  }
  const text = String(raw)
    .trim()
    .replace(/^["']+|["']+$/g, "")
    .trim();
  if (text === "") {
    return { days: null, lint: null };
  }
  if (!/^[+-]?\d+$/.test(text)) {
    return { days: null, lint: "task_refresh_invalid" };
  }
  const number = Number(text);
  if (!Number.isSafeInteger(number) || number < 1 || number > 365) {
    return { days: null, lint: "task_refresh_invalid" };
  }
  return { days: number, lint: null };
}

// Lane for one row: pending for `/`, next for `*`, ready for the
// Tasks status type TODO, none otherwise. Mirrors `lane_for_row` in
// `src/native/freshness/state.rs`.
function freshnessLaneForRow(statusSymbol, isTodo) {
  if (statusSymbol === "/") {
    return "pending";
  }
  if (statusSymbol === "*") {
    return "next";
  }
  if (isTodo) {
    return "ready";
  }
  return null;
}

// Exact, case-insensitive checklist tags from the Tasks tag list. PRE
// wins when both tags are present; prefixes, subtags, and tag text in a
// description never qualify.
function freshnessChecklistForTags(tags) {
  const tokens = new Set(
    (Array.isArray(tags) ? tags : [])
      .filter((tag) => typeof tag === "string")
      .map((tag) => tag.trim().toLowerCase()),
  );
  if (!tokens.has("#gtd")) {
    return null;
  }
  if (tokens.has("#pre")) {
    return "pre";
  }
  return tokens.has("#post") ? "post" : null;
}

// Lane interval for one lane: the configured `pendingInterval` /
// `nextInterval` (absent means the default 1); null means that lane is
// not walked (`false` off-switch).
function freshnessLaneIntervalDays(config, lane) {
  if (lane === "pending") {
    const raw =
      config && config.pendingInterval !== undefined
        ? config.pendingInterval
        : 1;
    return raw === null ? null : raw;
  }
  if (lane === "next") {
    const raw =
      config && config.nextInterval !== undefined ? config.nextInterval : 1;
    return raw === null ? null : raw;
  }
  return null;
}

// Effective interval and where it came from. A configured project
// interval wins for `^prj` (source `project`). Otherwise a lane task
// in a walked lane uses that
// lane's interval (source `pending` | `next`), overriding the whole
// Ready chain below. Otherwise the task's `[refresh:: N]`, then the
// note's `task_refresh`, then `freshness.interval`, then 7. Mirrors
// `evaluate` + `interval_for` in `src/native/freshness/state.rs`.
function freshnessTrackerIntervalFor(config, tracker) {
  if (tracker === "prj") {
    const days =
      config && Number.isInteger(config.projectInterval)
        ? config.projectInterval
        : null;
    if (days !== null) {
      return { days, source: "project" };
    }
  }
  return null;
}
function freshnessIntervalFor(taskDays, noteDays, config, lane, tracker) {
  const trackerInterval = freshnessTrackerIntervalFor(config, tracker || null);
  if (trackerInterval !== null) {
    return trackerInterval;
  }
  if (lane === "pending") {
    const days = freshnessLaneIntervalDays(config, "pending");
    if (days !== null) {
      return { days, source: "pending" };
    }
  } else if (lane === "next") {
    const days = freshnessLaneIntervalDays(config, "next");
    if (days !== null) {
      return { days, source: "next" };
    }
  }
  if (taskDays !== null && taskDays !== undefined) {
    return { days: taskDays, source: "task" };
  }
  if (noteDays !== null && noteDays !== undefined) {
    return { days: noteDays, source: "note" };
  }
  const interval =
    config && Number.isInteger(config.interval) ? config.interval : 7;
  const fromConfig =
    Boolean(config && config.intervalFromConfig) || interval !== 7;
  if (fromConfig) {
    return { days: interval, source: "config" };
  }
  return { days: 7, source: "default" };
}

// Pure, never-throwing line interval for nav's refresh row:
// `{ days, source, ready: { days, source } }`. Reads the status from
// the line (quote-aware) and the lane/project intervals from
// `config`. `ready` is the interval the task returns to after
// release, including a configured project override. A `^prj` in any
// lane shows the Ready-chain interval when no tracker interval is
// set (the weekly reminder never becomes a daily lane review).
// References use ordinary Ready/lane intervals. Mirrors `docs/freshness.md` §4.
function freshnessIntervalForLine(line, noteRefreshRaw, config) {
  try {
    const text = typeof line === "string" ? line : "";
    const read = readFreshness(text, freshnessTodayFallback());
    const note = freshnessParseNoteRefresh(noteRefreshRaw);
    const blockMatch = / \^([A-Za-z0-9-]+)\s*$/.exec(
      String(text || "").split("\n")[0] || "",
    );
    const blockId = blockMatch !== null ? blockMatch[1] : null;
    const symbol = freshnessTaskStatus(text);
    const lane =
      symbol === "/" ? "pending" : symbol === "*" ? "next" : null;
    const tracker = blockId === "prj" ? "prj" : null;
    const ready =
      freshnessTrackerIntervalFor(config, tracker) ||
      freshnessIntervalFor(read.refresh, note.days, config, null, null);
    if (tracker !== null) {
      const trackerInterval = freshnessTrackerIntervalFor(config, tracker);
      if (trackerInterval !== null) {
        return {
          days: trackerInterval.days,
          source: trackerInterval.source,
          ready: { ...ready },
        };
      }
    }
    if (lane !== null && tracker === null) {
      const days = freshnessLaneIntervalDays(config, lane);
      if (days !== null) {
        return { days, source: lane, ready: { ...ready } };
      }
    }
    return { days: ready.days, source: ready.source, ready: { ...ready } };
  } catch (error) {
    return {
      days: 7,
      source: "default",
      ready: { days: 7, source: "default" },
    };
  }
}

function freshnessEvaluateValidScheduled(value) {
  if (value === null || value === undefined) {
    return null;
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : formatLocalDate(value);
  }
  return parseFreshDateStrict(String(value).trim());
}

// The earliest of the row's valid `scheduled`, `due`, and `start`
// dates (Tasks' "happens" date); null when it has none of them.
// Mirrors `occurs_on` in `src/native/freshness/state.rs`.
function freshnessOccursOn(row) {
  const safe = row && typeof row === "object" ? row : {};
  const dates = [
    freshnessEvaluateValidScheduled(safe.scheduled),
    freshnessEvaluateValidScheduled(safe.due),
    freshnessEvaluateValidScheduled(safe.start),
  ].filter((date) => date !== null && date !== undefined);
  if (dates.length === 0) {
    return null;
  }
  dates.sort();
  return dates[0];
}

// Recurring overlay (`docs/freshness.md` §4): an open, visible,
// non-checklist recurring row whose occurrence date has arrived
// walks in RECURRING. Applied after the checklist logic at the
// single `freshnessEvaluate` exit so no early return in the
// evaluator can drop it. A checklist member never reaches a
// recurring tier. Mirrors `overlay_recurring` in
// `src/native/freshness/state.rs`: `tier`, `dueOn`, and
// `daysOverdue` are set from the occurrence date, `decide` is
// false, and `state`, `lane`, `fresh`, interval, keeps, and lints
// are left alone.
function freshnessApplyRecurringOverlay(row, today, evaluated) {
  const safe = row && typeof row === "object" ? row : {};
  if (safe.checklist === "pre" || safe.checklist === "post") {
    return evaluated;
  }
  if (!safe.recurring) {
    return evaluated;
  }
  if (evaluated.lane === null || evaluated.lane === undefined) {
    return evaluated;
  }
  if (!safe.laneVisible) {
    return evaluated;
  }
  if (safe.isDailyNote || safe.isToday) {
    return evaluated;
  }
  const occurs = freshnessOccursOn(safe);
  if (occurs === null || occurs === undefined) {
    return evaluated;
  }
  if (occurs > today) {
    return evaluated;
  }
  return {
    ...evaluated,
    tier: "recurring",
    dueOn: occurs,
    daysOverdue: freshDateDiffDays(occurs, today),
    decide: false,
  };
}

// Evaluate one row for `todayText` under `config`. A row carries the
// caller-precomputed scope inputs:
//
//   { path, line (1-based), statusSymbol ("/", "*", or the line's
//     status; absent derives from rawLine), isTodo (Tasks status type
//     TODO), recurring, laneVisible (the NEXT/PENDING lane predicate),
//     isDailyNote (canonical YYYY/YYYYMMDD.md), isToday (Task Link
//     under today's open Pomodoros), scheduled (canonical date or
//     null), due (canonical date or null), start (canonical date or
//     null), created (canonical date or null, for queue order only),
//     rawLine (the task's originalMarkdown), noteRefreshRaw (the note's
//     raw `task_refresh`) }
//
// Returns `{ state ("new"|"resurfaced"|"rotten"|"fresh"|null; null is
// out of scope, see S13; lane rows keep a null state),
// tier ("new"|"projects"|"pending"|"next"|"recurring"|"tickler"|"rotten"|null),
// lane ("ready"|"pending"|"next"|null), fresh, intervalDays,
// intervalSource, dueOn, daysOverdue, keeps (the valid `[keeps:: N]`
// semantic count, 0 when absent), decide (a choice is due — never
// permission to act), lints }`. Tracker rows use the ordinary lane-visible
// predicate (sync owns `#hide`). Due `^prj` rows walk in PROJECTS.
// Reference tasks use ordinary freshness and review groups. Mirrors
// `evaluate_without_checklist` plus the checklist
// overlay in `src/native/freshness/state.rs`; `state` stays exactly
// as before so buckets never move. The RECURRING overlay is applied
// by `freshnessEvaluate` at its single exit, after this returns.
function freshnessEvaluateWithoutRecurring(row, todayText, config) {
  const safe = row && typeof row === "object" ? row : {};
  const today = freshnessNormalizeDateText(todayText);
  const read = readFreshness(safe.rawLine || "", today);
  const lints = [...read.lints];

  const note = freshnessParseNoteRefresh(safe.noteRefreshRaw);
  if (note.lint) {
    freshnessPushLint(lints, note.lint);
  }

  let writtenSymbol = null;
  try {
    writtenSymbol = freshnessTaskStatus(safe.rawLine || "");
  } catch (error) {
    writtenSymbol = null;
  }
  if (
    (writtenSymbol === null || writtenSymbol === undefined) &&
    typeof safe.statusSymbol === "string" &&
    safe.statusSymbol !== ""
  ) {
    writtenSymbol = String(safe.statusSymbol)[0];
  }
  let symbol = writtenSymbol;
  try {
    if (symbol === null || symbol === undefined || symbol === "") {
      symbol = freshnessTaskStatus(safe.rawLine || "");
    }
  } catch (error) {
    symbol = null;
  }
  if (symbol === null || symbol === undefined || symbol === "") {
    symbol = safe.isTodo ? " " : "?";
  } else {
    symbol = String(symbol)[0];
  }
  const checklist =
    safe.checklist === "pre" || safe.checklist === "post"
      ? safe.checklist
      : null;
  const lane =
    checklist !== null && writtenSymbol === "?"
      ? null
      : freshnessLaneForRow(symbol, Boolean(safe.isTodo));
  const laneDays =
    lane === "pending" || lane === "next"
      ? freshnessLaneIntervalDays(config, lane)
      : null;

  // Project identity is the only tracker exception. References use
  // ordinary Ready and lane intervals.
  const tracker = freshnessTrackerFromRow(safe);
  const isPrj = tracker === "prj";
  const trackerInterval = freshnessTrackerIntervalFor(
    config,
    isPrj ? "prj" : null,
  );
  const readyInterval = freshnessIntervalFor(
    read.refresh,
    note.days,
    config,
    null,
    null,
  );
  const interval = trackerInterval !== null
    ? trackerInterval
    : isPrj
      ? readyInterval
      : freshnessIntervalFor(read.refresh, note.days, config, lane, null);
  const isTracker = isPrj;
  const fresh = read.fresh;

  const walkScope =
    lane !== null &&
    Boolean(safe.laneVisible) &&
    !safe.recurring &&
    !safe.isDailyNote &&
    !safe.isToday;

  // Checklist visibility shares the established lane predicate, with
  // recurring, daily-note, and Today exclusions deliberately lifted.
  // The status must be the symbol actually written on the task line.
  const checklistScheduled = freshnessEvaluateValidScheduled(safe.scheduled);
  const checklistScope =
    checklist !== null &&
    [" ", "*", "/", "?"].includes(writtenSymbol) &&
    Boolean(safe.laneVisible) &&
    !(checklistScheduled !== null && checklistScheduled > today);

  // Ordinary lane due arithmetic uses the lane interval only.
  // Trackers never use it here; their lane arithmetic lives below.
  const effectiveLaneDays = laneDays;
  let laneDueOn = null;
  let laneDue = false;
  let laneDaysOverdue = null;
  if ((lane === "pending" || lane === "next") && effectiveLaneDays !== null) {
    if (fresh === null) {
      laneDue = true;
    } else {
      const due = freshDateAddDays(fresh, effectiveLaneDays);
      laneDueOn = due;
      if (today >= due) {
        laneDue = true;
        laneDaysOverdue = freshDateDiffDays(due, today);
      }
    }
  }

  const inScope =
    Boolean(safe.isTodo) &&
    lane === "ready" &&
    Boolean(safe.laneVisible) &&
    !safe.recurring &&
    !safe.isDailyNote &&
    !safe.isToday;

  // Effective resurfacing date: whichever came last from the inline
  // schedule and the recorded automatic unblock. A scheduled date wins
  // a tie; unblock dates allow `fresh == unblocked` so same-day recovery
  // after a stamp still returns to review.
  const inlineScheduled = freshnessEvaluateValidScheduled(safe.scheduled);
  const unblockedOn = read.unblocked;
  let scheduledReturn = null;
  let unblockedReturn = null;
  if (inScope) {
    if (
      inlineScheduled !== null &&
      fresh !== null &&
      fresh < inlineScheduled &&
      inlineScheduled <= today
    ) {
      scheduledReturn = inlineScheduled;
    }
    if (
      unblockedOn !== null &&
      fresh !== null &&
      fresh <= unblockedOn &&
      unblockedOn <= today
    ) {
      unblockedReturn = unblockedOn;
    }
  }
  let returnedOn = null;
  let returnedBy = null;
  if (scheduledReturn !== null && unblockedReturn !== null) {
    if (scheduledReturn >= unblockedReturn) {
      returnedOn = scheduledReturn;
      returnedBy = "scheduled";
    } else {
      returnedOn = unblockedReturn;
      returnedBy = "unblocked";
    }
  } else if (scheduledReturn !== null) {
    returnedOn = scheduledReturn;
    returnedBy = "scheduled";
  } else if (unblockedReturn !== null) {
    returnedOn = unblockedReturn;
    returnedBy = "unblocked";
  }

  // Ready state: lane rows keep a null state; Ready rows evaluate
  // normally, trackers included. A hidden `^prj` never arrives in
  // scope because it uses the ordinary lane-visible predicate.
  let state = null;
  if (inScope) {
    if (lane === "pending" || lane === "next") {
      state = null;
    } else if (fresh === null) {
      state = "new";
    } else if (returnedOn !== null) {
      state = "resurfaced";
    } else {
      const due = freshDateAddDays(fresh, interval.days);
      state = today >= due ? "rotten" : "fresh";
    }
  }

  // Tracker lane due date uses the effective (tracker-override or
  // Ready-chain) interval, never the lane interval; a disabled lane
  // walk does not disable the reminder.
  const trackerLaneEligible =
    isTracker && (lane === "pending" || lane === "next") && walkScope;
  const trackerLaneDue =
    trackerLaneEligible &&
    (fresh === null ||
      returnedOn !== null ||
      (fresh !== null && today >= freshDateAddDays(fresh, interval.days)));
  let trackerLaneDueOn = null;
  if (trackerLaneDue) {
    if (returnedOn !== null) {
      trackerLaneDueOn = returnedOn;
    } else if (fresh !== null) {
      trackerLaneDueOn = freshDateAddDays(fresh, interval.days);
    }
  }

  // PROJECTS is every due `^prj` row (Ready states and lane rows with
  // their actual lane retained). All other rows, including references,
  // use the ordinary NEW/lane/TICKLER/ROTTEN groups.
  const trackerReadyDue =
    isTracker &&
    lane === "ready" &&
    (state === "new" || state === "resurfaced" || state === "rotten");
  const trackerLaneDueRow = trackerLaneEligible && trackerLaneDue;
  let tier = null;
  if (checklistScope) {
    tier = checklist;
  } else if (isPrj && (trackerReadyDue || trackerLaneDueRow)) {
    tier = "projects";
  } else if (lane === "ready" && state === "new" && !isTracker) {
    tier = "new";
  } else if (lane === "pending" && walkScope && laneDue && !isTracker) {
    tier = "pending";
  } else if (lane === "next" && walkScope && laneDue && !isTracker) {
    tier = "next";
  } else if (state === "resurfaced") {
    tier = "tickler";
  } else if (state === "rotten") {
    tier = "rotten";
  }

  // A choice is due — never permission to act — for Ready due rows at
  // or over the keep limit. Mirrors the `decide` computation in
  // `evaluate` in `src/native/freshness/state.rs`.
  const keeps = read.keeps;
  const decide = freshnessDecideFor(lane, tier, keeps, config, returnedBy);

  // Lane rows use the lane due date; an unwalked lane falls back to
  // the Ready-chain interval with no due date (L4). Lane tracker rows
  // keep their actual lane with null state but use the effective
  // tracker due metadata; a disabled lane walk does not clear it.
  if (lane === "pending" || lane === "next") {
    if (isTracker) {
      let daysOverdue = null;
      if (trackerLaneDueOn !== null && today >= trackerLaneDueOn) {
        daysOverdue = freshDateDiffDays(trackerLaneDueOn, today);
      }
      return {
        state: null,
        tier,
        lane,
        fresh,
        intervalDays: interval.days,
        intervalSource: interval.source,
        dueOn: checklistScope ? null : trackerLaneDueOn,
        daysOverdue: checklistScope ? null : daysOverdue,
        keeps,
        decide,
        returnedBy,
        unblockedOn,
        lints,
      };
    }
    let dueOn = checklistScope || fresh === null ? null : laneDueOn;
    let daysOverdue =
      checklistScope || fresh === null ? null : laneDaysOverdue;
    if (laneDays === null) {
      dueOn = null;
      daysOverdue = null;
    }
    return {
      state: null,
      tier,
      lane,
      fresh,
      intervalDays: interval.days,
      intervalSource: interval.source,
      dueOn,
      daysOverdue,
      keeps,
      decide,
      returnedBy,
      unblockedOn,
      lints,
    };
  }

  if (state === null) {
    return {
      state: null,
      tier: checklistScope ? tier : null,
      lane,
      fresh,
      intervalDays: interval.days,
      intervalSource: interval.source,
      dueOn: null,
      daysOverdue: null,
      keeps,
      decide,
      returnedBy,
      unblockedOn,
      lints,
    };
  }

  if (state === "new") {
    return {
      state,
      tier,
      lane,
      fresh: null,
      intervalDays: interval.days,
      intervalSource: interval.source,
      dueOn: null,
      daysOverdue: null,
      keeps,
      decide,
      returnedBy,
      unblockedOn,
      lints,
    };
  }

  if (state === "resurfaced") {
    return {
      state,
      tier,
      lane,
      fresh,
      intervalDays: interval.days,
      intervalSource: interval.source,
      dueOn: checklistScope ? null : returnedOn,
      daysOverdue: checklistScope
        ? null
        : freshDateDiffDays(returnedOn, today),
      keeps,
      decide,
      returnedBy,
      unblockedOn,
      lints,
    };
  }

  if (state === "rotten") {
    const dueOn = freshDateAddDays(fresh, interval.days);
    return {
      state,
      tier,
      lane,
      fresh,
      intervalDays: interval.days,
      intervalSource: interval.source,
      dueOn: checklistScope ? null : dueOn,
      daysOverdue: checklistScope ? null : freshDateDiffDays(dueOn, today),
      keeps,
      decide,
      returnedBy,
      unblockedOn,
      lints,
    };
  }

  const dueOn = freshDateAddDays(fresh, interval.days);
  return {
    state,
    tier,
    lane,
    fresh,
    intervalDays: interval.days,
    intervalSource: interval.source,
    dueOn: checklistScope ? null : dueOn,
    daysOverdue: null,
    keeps,
    decide,
    returnedBy,
    unblockedOn,
    lints,
  };
}

// Evaluate one row for `todayText` under `config` (same shape as
// `freshnessEvaluateWithoutRecurring`): the base evaluation plus the
// RECURRING overlay at this single exit, so the lane-row and
// null-state early returns inside cannot drop the tier. Mirrors
// `evaluate` =
// `overlay_recurring(overlay_checklist(evaluate_without_checklist(…)))`
// in `src/native/freshness/state.rs`.
function freshnessEvaluate(row, todayText, config) {
  const evaluated = freshnessEvaluateWithoutRecurring(
    row,
    todayText,
    config,
  );
  return freshnessApplyRecurringOverlay(
    row,
    freshnessNormalizeDateText(todayText),
    evaluated,
  );
}

// One row's state: `"new"` | `"resurfaced"` | `"rotten"` | `"fresh"` |
// null (out of scope).
function freshnessState(row, todayText, config) {
  return freshnessEvaluate(row, todayText, config).state;
}

// Stable read-time bucket for dashboard gating (`docs/freshness.md`
// §4 in bob-cli): `"new"` surfaces in NEW, `"rotten"` (resurfaced or
// age-expired) surfaces in ROTTEN review, anything else (fresh or
// out of scope) has no bucket.
function freshnessBucketForState(state) {
  if (state === "new") {
    return "new";
  }
  if (state === "resurfaced" || state === "rotten") {
    return "rotten";
  }
  return null;
}

// Local day number for a canonical `YYYY-MM-DD` date text, parsed as a
// local calendar date (never UTC, so DST boundaries match the vault's
// local day). Null when the text is not a strict calendar date.
function freshnessDayNumberForDateText(dateText) {
  try {
    const text = parseFreshDateStrict(dateText);
    if (text === null) {
      return null;
    }
    const parts = text.split("-").map((part) => Number(part));
    if (parts.length !== 3 || parts.some((part) => !Number.isInteger(part))) {
      return null;
    }
    return planDayNumber(new Date(parts[0], parts[1] - 1, parts[2]));
  } catch (error) {
    return null;
  }
}

function freshnessRowKey(row) {
  const path = String(row.path || "");
  if (row.blockId) {
    return path + "#" + row.blockId;
  }
  return path + ":" + row.line;
}

// Walk tier order: PRE → NEW → PROJECTS → PENDING → NEXT → RECURRING →
// TICKLER → ROTTEN → POST. Mirrors the `Tier` ordering in
// `src/native/freshness/state.rs`.
const FRESHNESS_TIER_ORDER = {
  pre: 0,
  new: 1,
  projects: 2,
  pending: 3,
  next: 4,
  recurring: 5,
  tickler: 6,
  rotten: 7,
  post: 8,
};

// Project tracking-task identity is the exact `^prj` block ID.
function freshnessTrackerFromRow(row) {
  const safe = row && typeof row === "object" ? row : {};
  const blockId =
    typeof safe.tracker === "string"
      ? safe.tracker
      : typeof safe.blockId === "string"
        ? safe.blockId
        : null;
  if (blockId === "prj") {
    return "prj";
  }
  return null;
}

function freshnessTierLabel(tier) {
  if (tier === "pre") {
    return "PRE";
  }
  if (tier === "new") {
    return "NEW";
  }
  if (tier === "projects") {
    return "PROJECTS";
  }
  if (tier === "pending") {
    return "PENDING";
  }
  if (tier === "next") {
    return "NEXT";
  }
  if (tier === "recurring") {
    return "RECURRING";
  }
  if (tier === "tickler") {
    return "TICKLER";
  }
  if (tier === "rotten") {
    return "ROTTEN";
  }
  if (tier === "post") {
    return "POST";
  }
  return "";
}

// Compact status-bar label for the review footer.
function freshnessTierFooterLabel(tier) {
  if (tier === "pending") {
    return "WIP";
  }
  if (tier === "recurring") {
    return "RECUR";
  }
  if (tier === "tickler") {
    return "TICKS";
  }
  return freshnessTierLabel(tier);
}

// Compare `created` with missing dates always last, in both ascending
// and descending keys. Mirrors `compare_created` in `state.rs`.
function freshnessCompareCreated(a, b, descending) {
  if (a === null || a === undefined) {
    return b === null || b === undefined ? 0 : 1;
  }
  if (b === null || b === undefined) {
    return -1;
  }
  if (a === b) {
    return 0;
  }
  if (descending) {
    return a < b ? 1 : -1;
  }
  return a < b ? -1 : 1;
}

function freshnessCompareDueOn(a, b) {
  if (a === null || a === undefined) {
    return b === null || b === undefined ? 0 : -1;
  }
  if (b === null || b === undefined) {
    return 1;
  }
  if (a === b) {
    return 0;
  }
  return a < b ? -1 : 1;
}

function freshnessComparePathLine(a, b) {
  if (a.path !== b.path) {
    return a.path < b.path ? -1 : 1;
  }
  return a.line - b.line;
}
// ---- src/110-freshness-queue.js ----
// The tiered review queue PRE → NEW → PROJECTS → PENDING → NEXT →
// RECURRING → TICKLER → ROTTEN → POST, with each tier's
// comparator from `docs/freshness.md` §4.
// Entries
// carry `{ key, path, line, lineNumber, text, originalMarkdown,
// blockId, state (null for lane rows), bucket, tier (machine),
// tierLabel, lane, created, fresh, dueOn, daysOverdue, interval,
// intervalSource, keeps, decide, returnedBy, unblockedOn, rank,
// tierRank, tierTotal }` with
// 1-based `line` (Tasks' `lineNumber` is 0-based). `decide` means a
// choice is due, not permission to execute an action.
function freshnessQueue(rows, todayText, config) {
  const list = Array.isArray(rows) ? rows : [];
  const entries = [];
  for (const row of list) {
    if (!row || typeof row !== "object") {
      continue;
    }
    const evaluated = freshnessEvaluate(row, todayText, config);
    if (evaluated.tier === null || evaluated.tier === undefined) {
      continue;
    }
    const checklistTier =
      evaluated.tier === "pre" || evaluated.tier === "post";
    if (
      !checklistTier &&
      (evaluated.lane === null || evaluated.lane === undefined)
    ) {
      continue;
    }
    entries.push({
      key: freshnessRowKey(row),
      path: String(row.path || ""),
      line: row.line,
      lineNumber:
        Number.isInteger(row.lineNumber) ? row.lineNumber : row.line - 1,
      text: typeof row.text === "string" ? row.text : "",
      originalMarkdown:
        typeof row.originalMarkdown === "string" ? row.originalMarkdown : "",
      blockId: row.blockId || null,
      state: evaluated.state,
      bucket: freshnessBucketForState(evaluated.state),
      tier: evaluated.tier,
      tierLabel: freshnessTierLabel(evaluated.tier),
      lane: evaluated.lane,
      created:
        row.created === undefined || row.created === null
          ? null
          : String(row.created),
      fresh: evaluated.fresh,
      dueOn: evaluated.dueOn,
      daysOverdue: evaluated.daysOverdue,
      interval: evaluated.intervalDays,
      intervalSource: evaluated.intervalSource,
      keeps: evaluated.keeps,
      decide: evaluated.decide,
      returnedBy: evaluated.returnedBy,
      unblockedOn: evaluated.unblockedOn,
      rank: 0,
      tierRank: 0,
      tierTotal: 0,
    });
  }

  entries.sort((left, right) => {
    const tierOrder =
      (FRESHNESS_TIER_ORDER[left.tier] ?? 99) -
      (FRESHNESS_TIER_ORDER[right.tier] ?? 99);
    if (tierOrder !== 0) {
      return tierOrder;
    }
    if (
      left.tier === "pre" ||
      left.tier === "new" ||
      left.tier === "post"
    ) {
      return freshnessComparePathLine(left, right);
    }
    if (
      left.tier === "projects" ||
      left.tier === "pending" ||
      left.tier === "next"
    ) {
      return (
        freshnessCompareDueOn(left.dueOn, right.dueOn) ||
        freshnessCompareCreated(left.created, right.created, false) ||
        freshnessComparePathLine(left, right)
      );
    }
    if (left.tier === "recurring") {
      return (
        freshnessCompareDueOn(left.dueOn, right.dueOn) ||
        freshnessComparePathLine(left, right)
      );
    }
    if (left.tier === "tickler") {
      return (
        freshnessCompareDueOn(left.dueOn, right.dueOn) ||
        freshnessComparePathLine(left, right)
      );
    }
    return (
      left.interval - right.interval ||
      freshnessCompareDueOn(left.dueOn, right.dueOn) ||
      freshnessCompareCreated(left.created, right.created, true) ||
      freshnessComparePathLine(left, right)
    );
  });

  const totals = {};
  for (const entry of entries) {
    totals[entry.tier] = (totals[entry.tier] || 0) + 1;
  }
  const seen = {};
  for (let index = 0; index < entries.length; index += 1) {
    const entry = entries[index];
    entry.rank = index + 1;
    seen[entry.tier] = (seen[entry.tier] || 0) + 1;
    entry.tierRank = seen[entry.tier];
    entry.tierTotal = totals[entry.tier] || 0;
  }
  return entries;
}

function freshnessIsExcludedCountPath(path) {
  return String(path || "")
    .split("/")
    .some((segment) => segment === "_templates" || segment === "_conflicts");
}

// Whole-vault counts: `{ due, new, resurfaced, rotten, fresh,
// preDue, postDue, pendingDue, nextDue, projectsDue,
// recurringDue, byTier, walk, decide,
// refreshedToday, upkeepToday, budget, budgetMet }`. State totals
// (`due = new + resurfaced + rotten`) count evaluated Ready states
// over the full review universe, including eligible Ready trackers
// once each; `byTier` counts the actual full queue and `walk` sums
// it. `decide` counts the rows where a choice is due (never
// permission to act). `refreshedToday` counts tasks of any status
// outside `_templates` / `_conflicts` whose `fresh` equals today;
// `upkeepToday` counts those whose status symbol is neither `/` nor
// `*`. `budgetMet` compares the budget against upkeep, with zero NEW.
// Mirrors `counts` in `src/native/freshness/state.rs`.
function freshnessCounts(rows, todayText, config) {
  const today = freshnessNormalizeDateText(todayText);
  const list = Array.isArray(rows) ? rows : [];
  let due = 0;
  let freshNew = 0;
  let resurfaced = 0;
  let rotten = 0;
  let fresh = 0;
  const returnedBy = { scheduled: 0, unblocked: 0 };
  const byTier = {
    pre: 0,
    new: 0,
    projects: 0,
    pending: 0,
    next: 0,
    recurring: 0,
    tickler: 0,
    rotten: 0,
    post: 0,
  };
  let decide = 0;
  let refreshedToday = 0;
  let upkeepToday = 0;

  for (const row of list) {
    if (!row || typeof row !== "object") {
      continue;
    }
    const evaluated = freshnessEvaluate(row, today, config);
    if (
      evaluated.state === "resurfaced" &&
      (evaluated.returnedBy === "scheduled" ||
        evaluated.returnedBy === "unblocked")
    ) {
      returnedBy[evaluated.returnedBy] += 1;
    }
    if (evaluated.decide) {
      decide += 1;
    }
    if (
      !freshnessIsExcludedCountPath(row.path) &&
      evaluated.fresh === today
    ) {
      refreshedToday += 1;
      let symbol = null;
      try {
        if (
          row.statusSymbol !== undefined &&
          row.statusSymbol !== null &&
          String(row.statusSymbol) !== ""
        ) {
          symbol = String(row.statusSymbol)[0];
        } else {
          symbol = freshnessTaskStatus(row.rawLine || "");
        }
      } catch (error) {
        symbol = null;
      }
      if (symbol !== "/" && symbol !== "*") {
        upkeepToday += 1;
      }
    }
    if (evaluated.state === "new") {
      freshNew += 1;
      due += 1;
    } else if (evaluated.state === "resurfaced") {
      resurfaced += 1;
      due += 1;
    } else if (evaluated.state === "rotten") {
      rotten += 1;
      due += 1;
    } else if (evaluated.state === "fresh") {
      fresh += 1;
    }
    if (Object.prototype.hasOwnProperty.call(byTier, evaluated.tier)) {
      byTier[evaluated.tier] += 1;
    }
  }

  const rawBudget =
    config && config.rottenDailyBudget !== undefined
      ? config.rottenDailyBudget
      : null;
  const budget =
    Number.isInteger(rawBudget) && rawBudget >= 1 ? rawBudget : null;
  const budgetMet =
    budget !== null && upkeepToday >= budget && freshNew === 0;
  const walk =
    byTier.pre +
    byTier.new +
    byTier.projects +
    byTier.pending +
    byTier.next +
    byTier.recurring +
    byTier.tickler +
    byTier.rotten +
    byTier.post;

  return {
    due,
    new: freshNew,
    resurfaced,
    rotten,
    fresh,
    returnedBy,
    preDue: byTier.pre,
    postDue: byTier.post,
    pendingDue: byTier.pending,
    nextDue: byTier.next,
    projectsDue: byTier.projects,
    recurringDue: byTier.recurring,
    byTier: { ...byTier },
    walk,
    decide,
    refreshedToday,
    upkeepToday,
    budget,
    budgetMet,
  };
}

const FRESHNESS_LINT_MESSAGES = {
  fresh_malformed: "fresh date is not a YYYY-MM-DD calendar date",
  fresh_future: "fresh date is in the future",
  fresh_duplicate: "more than one fresh field; the latest valid date wins",
  fresh_misplaced:
    "fresh/refresh/keeps/unblocked sits inside the Tasks suffix; the next stamp repairs it",
  refresh_invalid: "refresh is not an integer 1-365",
  keeps_invalid: "keeps is not an integer 1-999",
  keeps_duplicate: "more than one keeps field; the first valid count wins",
  unblocked_malformed: "unblocked date is not a YYYY-MM-DD calendar date",
  unblocked_duplicate: "more than one unblocked field; the latest valid date wins",
  task_refresh_invalid: "task_refresh is not an integer 1-365",
  freshness_stale_daily_budget_deprecated:
    "freshness.stale_daily_budget is deprecated; use freshness.rotten_daily_budget",
};

// Per-occurrence lints in row order: `{ code, path, line, message }`.
function freshnessCollectLints(rows, todayText, config) {
  const today = freshnessNormalizeDateText(todayText);
  const list = Array.isArray(rows) ? rows : [];
  const out = [];
  for (const row of list) {
    if (!row || typeof row !== "object") {
      continue;
    }
    const evaluated = freshnessEvaluate(row, today, config);
    for (const code of evaluated.lints) {
      out.push({
        code,
        path: String(row.path || ""),
        line: row.line,
        message: FRESHNESS_LINT_MESSAGES[code] || code,
      });
    }
  }
  return out;
}

// Pure view-model for the status bar counter. `counts` is a
// `freshnessCounts` result; `mostOverdue` is the queue's largest
// `daysOverdue` (or null when nothing is due). The meter shows
// upkeep (`upkeepToday`); ROTTEN includes TICKLER, as on the chip.
// Mirrors `docs/freshness.md` §4 (freshness namespace v5).
function freshnessStatusView(counts, options = {}) {
  const tasksAvailable = options.tasksAvailable !== false;
  if (!tasksAvailable) {
    return {
      text: "⟳ –",
      tooltip: "Tasks unavailable",
      mode: "unavailable",
    };
  }
  const safe = counts || {};
  // Tier counts drive the surfaces so the shown numbers sum to
  // `walk`. Without a `byTier` histogram fall back to the legacy
  // state counts. The rotten number keeps folding TICKLER in.
  const tierCount = (key, legacy) => {
    if (safe.byTier && typeof safe.byTier === "object") {
      const value = safe.byTier[key];
      if (Number.isInteger(value) && value >= 0) {
        return value;
      }
    }
    return Number.isInteger(legacy) && legacy >= 0 ? legacy : 0;
  };
  const tierPre = tierCount("pre", safe.preDue);
  const tierNew = tierCount("new", safe.new);
  const tierProjects = tierCount("projects", safe.projectsDue);
  const tierPending = tierCount("pending", safe.pendingDue);
  const tierNext = tierCount("next", safe.nextDue);
  const tierRecurring = tierCount("recurring", safe.recurringDue);
  const tierTickler = tierCount("tickler", safe.resurfaced);
  const tierRotten = tierCount("rotten", safe.rotten);
  const tierPost = tierCount("post", safe.postDue);
  const rotten = tierTickler + tierRotten;
  const walk =
    Number.isInteger(safe.walk) && safe.walk >= 0
      ? safe.walk
      : tierPre +
        tierNew +
        tierProjects +
        tierPending +
        tierNext +
        tierRecurring +
        tierTickler +
        tierRotten +
        tierPost;
  const upkeep =
    Number.isInteger(safe.upkeepToday) && safe.upkeepToday >= 0
      ? safe.upkeepToday
      : Number.isInteger(safe.refreshedToday) && safe.refreshedToday >= 0
        ? safe.refreshedToday
        : 0;
  const budget =
    Number.isInteger(safe.budget) && safe.budget >= 1 ? safe.budget : null;
  const meter = budget !== null ? upkeep + "/" + budget : String(upkeep);
  const text =
    "⟳ " +
    tierPre +
    " pre · " +
    tierNew +
    " new · " +
    tierProjects +
    " projects · " +
    tierPending +
    " pending · " +
    tierNext +
    " next · " +
    tierRecurring +
    " recurring · " +
    rotten +
    " rotten · " +
    tierPost +
    " post · ✓ " +
    meter +
    " today";
  const mostOverdue =
    Number.isInteger(options.mostOverdue) && options.mostOverdue >= 0
      ? options.mostOverdue
      : null;
  const tooltip =
    "Walk " +
    walk +
    " · PRE " +
    tierPre +
    " · NEW " +
    tierNew +
    " · PROJECTS " +
    tierProjects +
    " · PENDING " +
    tierPending +
    " · NEXT " +
    tierNext +
    " · RECURRING " +
    tierRecurring +
    " · TICKLER " +
    tierTickler +
    " · ROTTEN " +
    tierRotten +
    " · POST " +
    tierPost +
    (mostOverdue === null
      ? " · nothing due"
      : " · oldest " + mostOverdue + "d overdue") +
    " · ✓ " +
    meter +
    " today";
  // Mode precedence: `new` (NEW > 0), then `due` while any
  // commitment tier (PRE, NEW, PROJECTS, PENDING, NEXT, RECURRING,
  // TICKLER) remains, then `budget` (met), then `clear`
  // (walk empty), else `due`. The raw `budgetMet` formula is
  // unchanged; outstanding PROJECTS commitments take precedence in
  // this mode.
  let mode = "due";
  if (tierNew > 0) {
    mode = "new";
  } else if (
    tierPre > 0 ||
    tierProjects > 0 ||
    tierPending > 0 ||
    tierNext > 0 ||
    tierRecurring > 0 ||
    tierTickler > 0
  ) {
    mode = "due";
  } else if (safe.budgetMet) {
    mode = "budget";
  } else if (walk === 0) {
    mode = "clear";
  } else {
    mode = "due";
  }
  return { text, tooltip, mode };
}
// ---- src/120-freshness-footer.js ----
const FRESHNESS_FOOTER_TIERS = [
  "pre",
  "new",
  "projects",
  "pending",
  "next",
  "recurring",
  "tickler",
  "rotten",
  "post",
];

const FRESHNESS_FOOTER_COMMITMENT_TIERS = [
  "pre",
  "new",
  "projects",
  "pending",
  "next",
  "recurring",
  "tickler",
];

function freshnessReviewEntryViewEmpty() {
  return {
    ok: false,
    tier: "",
    label: "",
    detail: "",
    compact: "",
    actionHint: "",
  };
}

// Machine walk tier for an already-evaluated queue entry. v4 `tier`,
// else the legacy v3 `state` mapping (`resurfaced` reads as TICKLER).
function freshnessReviewMachineTier(entry) {
  const tier =
    entry && typeof entry.tier === "string"
      ? entry.tier.trim().toLowerCase()
      : "";
  if (
    tier === "pre" ||
    tier === "new" ||
    tier === "projects" ||
    tier === "pending" ||
    tier === "next" ||
    tier === "recurring" ||
    tier === "tickler" ||
    tier === "rotten" ||
    tier === "post"
  ) {
    return tier;
  }
  // Legacy queue entries are tagged only by navigation when they came
  // from a freshness namespace <=10. New producers never emit this tier.
  if (
    tier === "references" &&
    entry &&
    entry.legacyReferenceTier === true
  ) {
    return tier;
  }
  const state =
    entry && typeof entry.state === "string"
      ? entry.state.trim().toLowerCase()
      : "";
  if (state === "new") {
    return "new";
  }
  if (state === "rotten") {
    return "rotten";
  }
  if (state === "resurfaced") {
    return "tickler";
  }
  return "";
}

// `2026-10-07` -> `Oct 7`, else the raw text. Matches the navigation
// notice short-date, so shared presentation stays equivalent.
function freshnessReviewShortDate(text) {
  const months = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
  ];
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(text || "").trim());
  if (!match) {
    return String(text || "");
  }
  const month = months[Number(match[2]) - 1];
  if (!month) {
    return String(text || "");
  }
  return month + " " + Number(match[3]);
}

function freshnessReviewLaneConfirmedDetail(entry, todayText) {
  const fresh =
    entry && typeof entry.fresh === "string" && entry.fresh
      ? entry.fresh
      : null;
  if (!fresh) {
    return "never confirmed";
  }
  const freshDay = freshnessDayNumberForDateText(fresh);
  const todayDay = freshnessDayNumberForDateText(todayText);
  let age = null;
  if (freshDay !== null && todayDay !== null) {
    age = todayDay - freshDay;
  } else if (
    entry &&
    Number.isFinite(entry.daysOverdue) &&
    Number.isInteger(entry.interval)
  ) {
    age = Math.max(0, Math.floor(entry.daysOverdue)) + entry.interval;
  }
  if (age === null || !Number.isFinite(age)) {
    return "confirmed " + fresh;
  }
  if (age <= 0) {
    return "confirmed today";
  }
  if (age === 1) {
    return "confirmed yesterday";
  }
  return "confirmed " + age + " days ago";
}

function freshnessReviewTrackerDetail(entry, kind) {
  const fresh =
    entry && typeof entry.fresh === "string" && entry.fresh
      ? entry.fresh
      : null;
  const interval =
    entry && Number.isInteger(entry.interval) ? entry.interval : null;
  const every = interval !== null ? " · every " + interval + "d" : "";
  if (!fresh) {
    return kind + " · never confirmed" + every;
  }
  const overdue =
    entry && Number.isFinite(entry.daysOverdue)
      ? Math.max(0, Math.floor(entry.daysOverdue))
      : null;
  const lead =
    overdue === null
      ? entry && typeof entry.dueOn === "string" && entry.dueOn
        ? "due " + freshnessReviewShortDate(entry.dueOn)
        : "due"
      : overdue < 1
        ? "due today"
        : overdue + "d overdue";
  return (
    kind +
    " · " +
    lead +
    " · confirmed " +
    freshnessReviewShortDate(fresh) +
    every
  );
}

function freshnessReviewRottenDetail(entry) {
  const interval =
    entry && Number.isInteger(entry.interval) ? entry.interval : null;
  const every = interval !== null ? " · every " + interval + "d" : "";
  const overdue =
    entry && Number.isFinite(entry.daysOverdue)
      ? Math.max(0, Math.floor(entry.daysOverdue))
      : null;
  if (overdue === null || overdue < 1) {
    return "due today" + every;
  }
  return "rotten " + overdue + "d" + every;
}

function freshnessReviewRottenCompact(entry) {
  const overdue =
    entry && Number.isFinite(entry.daysOverdue)
      ? Math.max(0, Math.floor(entry.daysOverdue))
      : null;
  if (overdue === null || overdue < 1) {
    return "due today";
  }
  return "rotten " + overdue + "d";
}

// Pure presentation for one already-evaluated review-queue entry.
// Formats stored fields; it does not re-evaluate or mutate rows.
// Never throws: invalid input yields `{ ok: false }`.
function freshnessReviewEntryView(entry, options = {}) {
  try {
    if (!entry || typeof entry !== "object") {
      return freshnessReviewEntryViewEmpty();
    }
    const tier = freshnessReviewMachineTier(entry);
    if (!tier) {
      return freshnessReviewEntryViewEmpty();
    }
    const label =
      (entry && typeof entry.tierLabel === "string" && entry.tierLabel
        ? entry.tierLabel
        : "") ||
      freshnessTierLabel(tier) ||
      tier.toUpperCase();
    const todayText =
      options && typeof options.todayText === "string"
        ? options.todayText
        : null;
    let detail = "";
    let compact = "";
    let actionHint = "";
    if (tier === "pre") {
      detail = "checklist";
      compact = "checklist";
      actionHint = "Ctrl+Enter done · ]s skip";
    } else if (tier === "post") {
      detail = "closeout";
      compact = "closeout";
      actionHint = "Ctrl+Enter done · closes the review";
    } else if (tier === "projects") {
      detail = freshnessReviewTrackerDetail(entry, "Empty project");
      compact = "Empty project";
    } else if (tier === "references") {
      detail = freshnessReviewTrackerDetail(entry, "Reference");
      compact = "Reference";
    } else if (tier === "pending" || tier === "next") {
      detail = freshnessReviewLaneConfirmedDetail(entry, todayText);
      compact = detail;
      actionHint =
        tier === "pending"
          ? "Still pending? Ctrl+Alt+F keep · Alt+N release · Ctrl+Shift+Enter today"
          : "Still next? Ctrl+Alt+F keep · Alt+N release · Ctrl+Shift+Enter today";
    } else if (tier === "recurring") {
      const overdue =
        entry && Number.isFinite(entry.daysOverdue)
          ? Math.max(0, Math.floor(entry.daysOverdue))
          : null;
      detail =
        overdue === null || overdue < 1
          ? "recurring · due today"
          : "recurring · " + overdue + "d overdue";
      compact = detail;
      actionHint =
        "Ctrl+Enter done · Ctrl+Shift+Enter today · Ctrl+Shift+P reschedule · ]s skip";
    } else if (tier === "tickler") {
      const since =
        entry && typeof entry.dueOn === "string" && entry.dueOn
          ? entry.dueOn
          : entry && typeof entry.fresh === "string"
            ? entry.fresh
            : "";
      const source = entry && entry.returnedBy;
      const prefix = source === "unblocked" ? "unblocked " : "scheduled ";
      detail = since ? prefix + freshnessReviewShortDate(since) : "tickler";
      compact = detail;
    } else if (tier === "rotten") {
      detail = freshnessReviewRottenDetail(entry);
      compact = freshnessReviewRottenCompact(entry);
    }
    return {
      ok: true,
      tier,
      label,
      detail,
      compact,
      actionHint,
    };
  } catch (error) {
    return freshnessReviewEntryViewEmpty();
  }
}

function freshnessFooterTierCount(counts, key, legacy) {
  const safe = counts && typeof counts === "object" ? counts : {};
  if (safe.byTier && typeof safe.byTier === "object") {
    const value = safe.byTier[key];
    if (Number.isInteger(value) && value >= 0) {
      return value;
    }
  }
  return Number.isInteger(legacy) && legacy >= 0 ? legacy : 0;
}

function freshnessFooterReadTiers(counts) {
  const safe = counts && typeof counts === "object" ? counts : {};
  const tiers = {
    pre: freshnessFooterTierCount(safe, "pre", safe.preDue),
    new: freshnessFooterTierCount(safe, "new", safe.new),
    projects: freshnessFooterTierCount(safe, "projects", safe.projectsDue),
    pending: freshnessFooterTierCount(safe, "pending", safe.pendingDue),
    next: freshnessFooterTierCount(safe, "next", safe.nextDue),
    recurring: freshnessFooterTierCount(safe, "recurring", safe.recurringDue),
    tickler: freshnessFooterTierCount(safe, "tickler", safe.resurfaced),
    rotten: freshnessFooterTierCount(safe, "rotten", safe.rotten),
    post: freshnessFooterTierCount(safe, "post", safe.postDue),
  };
  const walk =
    Number.isInteger(safe.walk) && safe.walk >= 0
      ? safe.walk
      : FRESHNESS_FOOTER_TIERS.reduce((sum, key) => sum + tiers[key], 0);
  const upkeep =
    Number.isInteger(safe.upkeepToday) && safe.upkeepToday >= 0
      ? safe.upkeepToday
      : Number.isInteger(safe.refreshedToday) && safe.refreshedToday >= 0
        ? safe.refreshedToday
        : 0;
  const budget =
    Number.isInteger(safe.budget) && safe.budget >= 1 ? safe.budget : null;
  let commitments = 0;
  for (const key of FRESHNESS_FOOTER_COMMITMENT_TIERS) {
    commitments += tiers[key];
  }
  return {
    tiers,
    walk,
    upkeep,
    budget,
    budgetMet: Boolean(safe.budgetMet),
    commitments,
  };
}

function freshnessFooterGroups(counts) {
  try {
    const { tiers } = freshnessFooterReadTiers(counts);
    const groups = [];
    for (const key of FRESHNESS_FOOTER_TIERS) {
      const count = tiers[key];
      if (Number.isInteger(count) && count > 0) {
        groups.push({
          key,
          label: freshnessTierFooterLabel(key),
          count,
        });
      }
    }
    return groups;
  } catch (error) {
    return [];
  }
}

function freshnessFooterHiddenView() {
  return {
    visible: false,
    mode: "hidden",
    walk: 0,
    commitments: 0,
    dueText: "",
    contextText: "",
    detailText: "",
    hintText: "",
    groups: [],
    groupsText: "",
    meterText: "",
    tooltip: "",
    ariaLabel: "",
    current: null,
    action: "review",
  };
}

function freshnessFooterJoin(parts) {
  return parts.filter((part) => part && String(part).trim()).join(" · ");
}

// Match the active editor cursor to a live queue entry. `cursor` is
// `{ path, line0, sourceLine, sourceLines? }` with a 0-based line.
// Exact path+line wins when the source line still matches; a moved
// line is accepted only as a unique verified originalMarkdown identity.
// Duplicate text or duplicate block IDs never borrow another rank.
function freshnessMatchQueueCursor(queue, cursor) {
  try {
    if (!cursor || typeof cursor !== "object") {
      return null;
    }
    const path = String(cursor.path || "");
    const line0 = Number.isInteger(cursor.line0)
      ? cursor.line0
      : Number.isInteger(cursor.line)
        ? cursor.line
        : null;
    const sourceLine =
      typeof cursor.sourceLine === "string" ? cursor.sourceLine : null;
    if (!path || !Number.isInteger(line0) || line0 < 0) {
      return null;
    }
    const list = Array.isArray(queue) ? queue : [];
    const onPath = [];
    for (const entry of list) {
      if (entry && String(entry.path || "") === path) {
        onPath.push(entry);
      }
    }
    if (onPath.length === 0) {
      return null;
    }
    const lineMatches = [];
    for (const entry of onPath) {
      const zero = Number.isInteger(entry.lineNumber)
        ? entry.lineNumber
        : Number.isInteger(entry.line)
          ? entry.line - 1
          : null;
      if (zero === line0) {
        lineMatches.push(entry);
      }
    }
    if (lineMatches.length > 1) {
      return null;
    }
    if (lineMatches.length === 1) {
      const entry = lineMatches[0];
      const want = String(entry.originalMarkdown || entry.text || "");
      if (sourceLine !== null && want && sourceLine !== want) {
        return null;
      }
      return entry;
    }
    if (!sourceLine) {
      return null;
    }
    const textMatches = [];
    const blockIds = new Map();
    for (const entry of onPath) {
      if (String(entry.originalMarkdown || "") === sourceLine) {
        textMatches.push(entry);
      }
      const blockId =
        entry && entry.blockId ? String(entry.blockId) : "";
      if (blockId) {
        blockIds.set(blockId, (blockIds.get(blockId) || 0) + 1);
      }
    }
    if (textMatches.length !== 1) {
      return null;
    }
    const unique = textMatches[0];
    const uniqueBlock =
      unique && unique.blockId ? String(unique.blockId) : "";
    if (uniqueBlock && (blockIds.get(uniqueBlock) || 0) > 1) {
      return null;
    }
    const sourceLines = cursor.sourceLines;
    if (Array.isArray(sourceLines)) {
      let hits = 0;
      for (const line of sourceLines) {
        if (line === sourceLine) {
          hits += 1;
          if (hits > 1) {
            return null;
          }
        }
      }
      if (hits !== 1) {
        return null;
      }
    }
    return unique;
  } catch (error) {
    return null;
  }
}

// Compact live review footer from one memo's `counts` and `queue`.
// Visible only for a usable, warm snapshot whose queue length is > 0.
// Never throws; unavailable, cold, or failed data hide the item.
function freshnessFooterView(memo, options = {}) {
  try {
    if (options && options.tasksAvailable === false) {
      return freshnessFooterHiddenView();
    }
    if (!memo || typeof memo !== "object") {
      return freshnessFooterHiddenView();
    }
    if (memo.tasksAvailable === false) {
      return freshnessFooterHiddenView();
    }
    const counts = memo.counts && typeof memo.counts === "object"
      ? memo.counts
      : memo;
    const queue = Array.isArray(memo.queue)
      ? memo.queue
      : Array.isArray(options.queue)
        ? options.queue
        : [];
    if (queue.length === 0) {
      return freshnessFooterHiddenView();
    }
    const read = freshnessFooterReadTiers(counts);
    if (!Number.isInteger(read.walk) || read.walk <= 0) {
      return freshnessFooterHiddenView();
    }
    const navAvailable = options.navAvailable !== false;
    const action = navAvailable ? "jump" : "review";
    const hintDefault = navAvailable ? "]s next" : "open review";
    let current = null;
    const currentEntry =
      options.current && typeof options.current === "object"
        ? options.current
        : null;
    if (currentEntry) {
      const presentation = freshnessReviewEntryView(currentEntry, {
        todayText: options.todayText,
      });
      if (presentation.ok) {
        const rank = Number.isInteger(currentEntry.rank)
          ? currentEntry.rank
          : null;
        const total = Number.isInteger(read.walk) ? read.walk : queue.length;
        if (rank !== null && rank >= 1) {
          current = {
            key: currentEntry.key || null,
            rank,
            total,
            tier: presentation.tier,
            label:
              freshnessTierFooterLabel(presentation.tier) ||
              presentation.label,
            tierRank: Number.isInteger(currentEntry.tierRank)
              ? currentEntry.tierRank
              : null,
            tierTotal: Number.isInteger(currentEntry.tierTotal)
              ? currentEntry.tierTotal
              : null,
            compact: presentation.compact,
            detail: presentation.detail,
            actionHint: presentation.actionHint,
          };
        }
      }
    }
    const allGroups = freshnessFooterGroups(counts);
    const groups = current
      ? allGroups.filter((group) => group.key !== current.tier)
      : allGroups.slice();
    const groupsText = groups
      .map((group) => group.label + " " + group.count)
      .join(" · ");
    const meter =
      read.budget !== null
        ? read.upkeep + "/" + read.budget
        : String(read.upkeep);
    const meterText = "✓ " + meter + " today";
    const dueText = current
      ? "Review " + current.rank + "/" + current.total
      : "Review " + read.walk + " due";
    let contextText = "";
    let detailText = "";
    let hintText = "";
    // Additive roll preview from nav `api.quickRoll` v1 (plan
    // 202610/quick_roll_alt_p.md, phase footer-preview). Only a queue row
    // with an available preview takes the hint slot; anything else leaves
    // the footer byte-identical to today.
    const quickRollOption =
      options && options.quickRoll && typeof options.quickRoll === "object"
        ? options.quickRoll
        : null;
    const quickRollReady =
      current !== null &&
      quickRollOption !== null &&
      quickRollOption.ok === true &&
      typeof quickRollOption.compact === "string" &&
      quickRollOption.compact.trim() !== "";
    if (current) {
      if (
        current.label &&
        Number.isInteger(current.tierRank) &&
        Number.isInteger(current.tierTotal)
      ) {
        contextText = current.label + " " + current.tierRank + "/" + current.tierTotal;
      } else if (current.label) {
        contextText = current.label;
      }
      detailText = current.compact || "";
      if (quickRollReady) {
        hintText = quickRollOption.compact;
      }
    } else if (read.commitments > 0) {
      contextText =
        read.commitments === 1
          ? "1 commitment"
          : read.commitments + " commitments";
      hintText = hintDefault;
    } else if (read.budgetMet) {
      contextText = "Upkeep budget met";
      hintText = hintDefault;
    } else {
      contextText = "Commitments done";
      hintText = hintDefault;
    }
    let mode = "due";
    if (read.tiers.new > 0) {
      mode = "new";
    } else if (read.commitments > 0) {
      mode = "due";
    } else if (read.budgetMet) {
      mode = "budget";
    } else {
      mode = "due";
    }
    const mostOverdue =
      Number.isInteger(options.mostOverdue) && options.mostOverdue >= 0
        ? options.mostOverdue
        : null;
    const shownTiers = new Set(groups.map((group) => group.key));
    if (current && current.tier) {
      shownTiers.add(current.tier);
    }
    const legendParts = [];
    if (shownTiers.has("pending")) {
      legendParts.push("WIP = PENDING");
    }
    if (shownTiers.has("recurring")) {
      legendParts.push("RECUR = RECURRING");
    }
    if (shownTiers.has("tickler")) {
      legendParts.push("TICKS = TICKLER");
    }
    const legendText = legendParts.join(" · ");
    const tooltipLines = [
      freshnessFooterJoin([
        dueText,
        contextText,
        detailText,
        hintText,
      ]),
      groupsText,
      freshnessFooterJoin([
        meterText,
        mostOverdue === null ? "" : "oldest " + mostOverdue + "d overdue",
      ]),
      legendText,
      "Footer splits TICKS from ROTTEN; dashboard ROTTEN chips still fold both.",
    ];
    if (current && current.detail && current.detail !== current.compact) {
      tooltipLines.splice(1, 0, current.detail);
    }
    if (
      quickRollReady &&
      typeof quickRollOption.detail === "string" &&
      quickRollOption.detail.trim() !== ""
    ) {
      tooltipLines.push(quickRollOption.detail);
    }
    if (current && current.actionHint) {
      tooltipLines.push(current.actionHint);
    }
    tooltipLines.push(
      action === "jump"
        ? "click for the next due task"
        : "click to open the review page",
    );
    const tooltip = tooltipLines.filter(Boolean).join("\n");
    const ariaLabel = freshnessFooterJoin([
      dueText,
      contextText,
      detailText,
      groupsText,
      meterText,
      hintText,
    ]);
    return {
      visible: true,
      mode,
      walk: read.walk,
      commitments: read.commitments,
      dueText,
      contextText,
      detailText,
      hintText,
      groups,
      groupsText,
      meterText,
      tooltip,
      ariaLabel,
      current,
      action,
    };
  } catch (error) {
    return freshnessFooterHiddenView();
  }
}

function freshnessFooterSetText(node, text) {
  if (!node) {
    return;
  }
  const value = text == null ? "" : String(text);
  try {
    if (typeof node.setText === "function") {
      node.setText(value);
    } else if ("textContent" in node) {
      node.textContent = value;
    }
  } catch (error) {
    // Cosmetic.
  }
}

function freshnessFooterSetAttr(node, name, value) {
  if (!node) {
    return;
  }
  try {
    if (typeof node.setAttribute === "function") {
      node.setAttribute(name, value);
    } else if (name === "title") {
      node.title = value;
    }
  } catch (error) {
    // Cosmetic.
  }
}

function freshnessFooterToggleClass(node, name, on) {
  if (!node || !name) {
    return;
  }
  try {
    if (node.classList && typeof node.classList.add === "function") {
      if (on) {
        node.classList.add(name);
      } else if (typeof node.classList.remove === "function") {
        node.classList.remove(name);
      }
      return;
    }
    if (typeof node.addClass === "function" && on) {
      node.addClass(name);
      return;
    }
    if (typeof node.removeClass === "function" && !on) {
      node.removeClass(name);
    }
  } catch (error) {
    // Cosmetic.
  }
}

function freshnessFooterCreateChild(parent, tag, className) {
  if (!parent) {
    return null;
  }
  try {
    if (typeof parent.createEl === "function") {
      return parent.createEl(tag, { cls: className });
    }
  } catch (error) {
    // Fall through to DOM.
  }
  try {
    const doc =
      parent.ownerDocument ||
      (typeof document !== "undefined" ? document : null);
    if (doc && typeof doc.createElement === "function") {
      const node = doc.createElement(tag);
      if (className) {
        node.className = className;
      }
      if (typeof parent.appendChild === "function") {
        parent.appendChild(node);
      }
      return node;
    }
  } catch (error) {
    return null;
  }
  return null;
}

function freshnessFooterEnsureDom(el) {
  if (!el) {
    return null;
  }
  if (el._bobFreshnessParts && el._bobFreshnessParts.button) {
    return el._bobFreshnessParts;
  }
  try {
    if (typeof el.empty === "function") {
      el.empty();
    } else if ("textContent" in el) {
      el.textContent = "";
    }
  } catch (error) {
    // Rebuild below.
  }
  const button = freshnessFooterCreateChild(el, "button", "bob-freshness-main");
  if (!button) {
    return null;
  }
  freshnessFooterSetAttr(button, "type", "button");
  const icon = freshnessFooterCreateChild(
    button,
    "span",
    "bob-freshness-icon",
  );
  freshnessFooterSetText(icon, "⟳");
  const due = freshnessFooterCreateChild(button, "span", "bob-freshness-due");
  const context = freshnessFooterCreateChild(
    el,
    "span",
    "bob-freshness-context",
  );
  const detail = freshnessFooterCreateChild(
    el,
    "span",
    "bob-freshness-detail",
  );
  const hint = freshnessFooterCreateChild(el, "span", "bob-freshness-hint");
  const groups = freshnessFooterCreateChild(
    el,
    "span",
    "bob-freshness-groups",
  );
  const meter = freshnessFooterCreateChild(el, "span", "bob-freshness-meter");
  const parts = { button, icon, due, context, detail, hint, groups, meter };
  el._bobFreshnessParts = parts;
  return parts;
}

function freshnessFooterSetOmitted(node, omitted) {
  freshnessFooterToggleClass(node, "bob-freshness-omit", omitted);
  if (omitted) {
    freshnessFooterSetAttr(node, "hidden", "hidden");
  } else if (node && typeof node.removeAttribute === "function") {
    try {
      node.removeAttribute("hidden");
    } catch (error) {
      // Cosmetic.
    }
  }
}

// Hide optional parts in this order until the item fits: groups, then
// optional detail, shortcut hint, upkeep meter. The main due total or
// current rank and tier stay visible.
function freshnessFooterFit(el, parts, view) {
  const show = {
    groups: Boolean(view && view.groupsText),
    detail: Boolean(view && view.detailText),
    hint: Boolean(view && view.hintText),
    meter: Boolean(view && view.meterText),
  };
  const apply = () => {
    freshnessFooterSetOmitted(parts.groups, !show.groups);
    freshnessFooterSetOmitted(parts.detail, !show.detail);
    freshnessFooterSetOmitted(parts.hint, !show.hint);
    freshnessFooterSetOmitted(parts.meter, !show.meter);
  };
  apply();
  let width = 0;
  try {
    width = Number(el.clientWidth);
  } catch (error) {
    return show;
  }
  if (!Number.isFinite(width) || width <= 0) {
    return show;
  }
  const overflows = () => {
    try {
      return Number(el.scrollWidth) > Number(el.clientWidth) + 1;
    } catch (error) {
      return false;
    }
  };
  if (!overflows()) {
    return show;
  }
  show.groups = false;
  apply();
  if (!overflows()) {
    return show;
  }
  show.detail = false;
  apply();
  if (!overflows()) {
    return show;
  }
  show.hint = false;
  apply();
  if (!overflows()) {
    return show;
  }
  show.meter = false;
  apply();
  return show;
}

function freshnessFooterPaint(el, view) {
  if (!el) {
    return null;
  }
  const parts = freshnessFooterEnsureDom(el);
  if (!parts) {
    return null;
  }
  const visible = Boolean(view && view.visible);
  freshnessFooterToggleClass(el, "bob-freshness-hidden", !visible);
  freshnessFooterSetAttr(el, "aria-hidden", visible ? "false" : "true");
  const modes = [
    "bob-freshness-unavailable",
    "bob-freshness-new",
    "bob-freshness-due",
    "bob-freshness-clear",
    "bob-freshness-budget",
    "bob-freshness-hidden",
  ];
  const wanted = visible
    ? "bob-freshness-" + (view.mode || "due")
    : "bob-freshness-hidden";
  try {
    if (el.classList && typeof el.classList.add === "function") {
      for (const mode of modes) {
        if (mode === wanted || (mode === "bob-freshness-hidden" && !visible)) {
          el.classList.add(mode);
        } else if (typeof el.classList.remove === "function") {
          el.classList.remove(mode);
        }
      }
      el.classList.add("bob-freshness");
      if (!visible) {
        el.classList.add("bob-freshness-hidden");
      }
    }
  } catch (error) {
    // Classes are cosmetic.
  }
  if (parts.button) {
    try {
      parts.button.disabled = !visible;
      parts.button.tabIndex = visible ? 0 : -1;
    } catch (error) {
      // Focus management is best-effort.
    }
  }
  if (!visible) {
    freshnessFooterSetText(parts.due, "");
    freshnessFooterSetText(parts.context, "");
    freshnessFooterSetText(parts.detail, "");
    freshnessFooterSetText(parts.hint, "");
    freshnessFooterSetText(parts.groups, "");
    freshnessFooterSetText(parts.meter, "");
    freshnessFooterSetAttr(parts.button, "aria-label", "Review footer hidden");
    freshnessFooterSetAttr(el, "title", "");
    return parts;
  }
  freshnessFooterSetText(parts.due, view.dueText);
  freshnessFooterSetText(parts.context, view.contextText);
  freshnessFooterSetText(parts.detail, view.detailText);
  freshnessFooterSetText(parts.hint, view.hintText);
  freshnessFooterSetText(parts.groups, view.groupsText);
  freshnessFooterSetText(parts.meter, view.meterText);
  freshnessFooterSetOmitted(parts.context, !view.contextText);
  freshnessFooterSetOmitted(parts.detail, !view.detailText);
  freshnessFooterSetOmitted(parts.hint, !view.hintText);
  freshnessFooterSetOmitted(parts.groups, !view.groupsText);
  freshnessFooterSetOmitted(parts.meter, !view.meterText);
  freshnessFooterToggleClass(
    parts.context,
    "bob-freshness-tier",
    Boolean(view.current),
  );
  freshnessFooterSetAttr(parts.button, "aria-label", view.ariaLabel || view.tooltip);
  freshnessFooterSetAttr(el, "title", view.tooltip);
  freshnessFooterSetAttr(parts.button, "title", view.tooltip);
  freshnessFooterFit(el, parts, view);
  return parts;
}
// ---- src/130-freshness-marks.js ----
// Unavailable NEW/ROTTEN review model: explicit nulls, never a zero
// that could read as an empty success.
function freshnessReviewUnavailable() {
  return {
    available: false,
    new: null,
    tickler: null,
    rotten: null,
    refreshedToday: null,
    upkeepToday: null,
    budget: null,
    budgetMet: false,
    meter: "✓ –",
    severity: "unavailable",
    escalated: false,
    oldestDaysOverdue: null,
    tooltip: "Review unavailable",
    newText: "NEW –",
    rottenText: "ROTTEN –",
  };
}

// Shared NEW/ROTTEN view-model from one freshness snapshot. `counts`
// is a `freshnessCounts` result and `queue` a `freshnessQueue` result
// over the same rows. The ROTTEN total includes TICKLER; escalation
// is per-row (`daysOverdue >= interval` for that row), never the
// confirmation age or the global default. The meter shows upkeep
// (`upkeepToday`); `refreshedToday` stays exposed for the census.
// An optional `visible` (`{ counts, queue }` projected onto the
// visible Ready pool) drives the NEW/ROTTEN chips and severity while
// the meter still uses the full counts; without it the full inputs
// drive everything (legacy behavior). Never throws.
function freshnessReviewModel(counts, queue, visible = null) {
  try {
    const chips =
      visible && typeof visible === "object" && visible.counts
        ? visible.counts
        : counts || {};
    const chipQueue =
      visible &&
      typeof visible === "object" &&
      Array.isArray(visible.queue)
        ? visible.queue
        : queue;
    const safe = chips;
    const freshNew =
      Number.isInteger(safe.new) && safe.new >= 0 ? safe.new : 0;
    const resurfaced =
      Number.isInteger(safe.resurfaced) && safe.resurfaced >= 0
        ? safe.resurfaced
        : 0;
    const ageExpired =
      Number.isInteger(safe.rotten) && safe.rotten >= 0 ? safe.rotten : 0;
    const rotten = resurfaced + ageExpired;
    const refreshed =
      Number.isInteger(safe.refreshedToday) && safe.refreshedToday >= 0
        ? safe.refreshedToday
        : 0;
    const upkeep =
      Number.isInteger(safe.upkeepToday) && safe.upkeepToday >= 0
        ? safe.upkeepToday
        : refreshed;
    const budget =
      Number.isInteger(safe.budget) && safe.budget >= 1 ? safe.budget : null;
    const budgetMet = Boolean(safe.budgetMet);
    let oldest = null;
    let escalated = false;
    for (const entry of Array.isArray(chipQueue) ? chipQueue : []) {
      if (!entry || typeof entry !== "object") {
        continue;
      }
      if (entry.state !== "resurfaced" && entry.state !== "rotten") {
        continue;
      }
      if (Number.isInteger(entry.daysOverdue) && entry.daysOverdue >= 0) {
        if (oldest === null || entry.daysOverdue > oldest) {
          oldest = entry.daysOverdue;
        }
        if (
          Number.isInteger(entry.interval) &&
          entry.interval >= 1 &&
          entry.daysOverdue >= entry.interval
        ) {
          escalated = true;
        }
      }
    }
    const meter =
      budget !== null ? upkeep + "/" + budget : String(upkeep);
    // NEW is red above 0; ROTTEN is neutral at 0, orange above 0, red
    // once any tickler or age-expired row is a full interval overdue.
    const severity =
      freshNew > 0 ? "new" : escalated ? "escalated" : rotten > 0 ? "rotten" : "none";
    const tooltip =
      "ROTTEN " +
      rotten +
      " = " +
      resurfaced +
      " tickler + " +
      ageExpired +
      " rotten · oldest " +
      (oldest === null ? "–" : oldest + "d") +
      " overdue · ✓ " +
      meter +
      " today";
    return {
      available: true,
      new: freshNew,
      tickler: resurfaced,
      rotten,
      refreshedToday: refreshed,
      upkeepToday: upkeep,
      budget,
      budgetMet,
      meter: "✓ " + meter,
      severity,
      escalated,
      oldestDaysOverdue: oldest,
      tooltip,
      newText: "NEW " + freshNew,
      rottenText: "ROTTEN " + rotten + " · ✓ " + meter,
    };
  } catch (error) {
    return freshnessReviewUnavailable();
  }
}

// --- Task freshness: display mark (mark-core) -------------------------------
// Owned by `docs/freshness.md` §§11-12 in bob-cli. Pure helpers only:
// source detection, resolution, model, consensus, tooltip dates, and a
// listener-free DOM builder. Every helper is synchronous and never
// throws; bad input yields null (or the unresolved model for the model
// builder). Reuses `freshnessInlineFields`, `readFreshness`,
// `freshnessTaskStatus`, `parseFreshDateStrict`, `freshDateDiffDays`,
// `freshDateAddDays`, `freshnessParseRefreshValue`, `freshnessIntervalFor`,
// `freshnessParseNoteRefresh`, and `freshnessEvaluate` above.

const FRESHNESS_MARK_WEEKDAYS = [
  "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat",
];

const FRESHNESS_MARK_MONTHS = [
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

const FRESHNESS_MARK_CLOSED_REASONS = {
  x: "Done",
  X: "Done",
  "-": "Cancelled",
};

const FRESHNESS_MARK_STATUS_REASONS = {
  "*": "Next",
  "/": "In Progress",
  "?": "Blocked",
  x: "Done",
  X: "Done",
  "-": "Cancelled",
};

// The single folded `[refresh:: N]` after a fresh field, or null when the
// line's refresh field is absent, paren-wrapped, non-adjacent, duplicated,
// or invalid. Never throws.
function freshnessMarkFoldRefresh(text, freshField) {
  try {
    const fields = freshnessInlineFields(text, "refresh");
    if (fields.length !== 1) {
      return null;
    }
    const field = fields[0];
    if (text[field.start] !== "[") {
      return null;
    }
    if (field.start !== freshField.end + 1 || text[freshField.end] !== " ") {
      return null;
    }
    const days = freshnessParseRefreshValue(field.value);
    if (days === null) {
      return null;
    }
    return { field, days };
  } catch (error) {
    return null;
  }
}

// The single folded `[keeps:: N]` after the last folded fresh/refresh
// field, or null when the line's keeps field is absent,
// paren-wrapped, non-adjacent, duplicated, or invalid. Only one valid
// square-bracketed keeps field folds, exactly one space after
// `afterField`. Noncanonical keeps fields stay visible Dataview pills
// with repair styling. Never throws.
function freshnessMarkFoldKeeps(text, afterField) {
  try {
    const fields = freshnessInlineFields(text, "keeps");
    if (fields.length !== 1) {
      return null;
    }
    const field = fields[0];
    if (text[field.start] !== "[") {
      return null;
    }
    if (field.start !== afterField.end + 1 || text[afterField.end] !== " ") {
      return null;
    }
    const count = freshnessParseKeepsValue(field.value);
    if (count === null) {
      return null;
    }
    return { field, count };
  } catch (error) {
    return null;
  }
}

// Shared core for both source detectors: one square-bracketed fresh field
// with a strict, non-future date, plus adjacent refresh folding and
// adjacent keeps folding. Returns the fresh field, folds, and date, or
// null. Never throws.
function freshnessMarkSourceCore(text, today) {
  try {
    const freshFields = freshnessInlineFields(text, "fresh");
    if (freshFields.length !== 1) {
      return null;
    }
    const freshField = freshFields[0];
    if (text[freshField.start] !== "[") {
      return null;
    }
    const date = parseFreshDateStrict(freshField.value.trim());
    if (date === null || date > today) {
      return null;
    }
    const fold = freshnessMarkFoldRefresh(text, freshField);
    const anchor = fold === null ? freshField : fold.field;
    const keepsFold = freshnessMarkFoldKeeps(text, anchor);
    return { freshField, fold, keepsFold, date };
  } catch (error) {
    return null;
  }
}

// The folded keeps count on a mark source: the valid semantic streak
// (1-999), or null when no keeps field folds into the mark.
function freshnessMarkSourceKeeps(core) {
  try {
    if (!core || !core.keepsFold) {
      return null;
    }
    return core.keepsFold.count;
  } catch (error) {
    return null;
  }
}

// A Live Preview task line's mark source, or null when the line gets no
// mark. `fieldStart`/`fieldEnd` are UTF-16 offsets of the folded field
// text, excluding the folded space. Never throws.
function freshnessMarkSource(line, todayText) {
  try {
    if (typeof line !== "string") {
      return null;
    }
    if (freshnessTaskStatus(line) === null) {
      return null;
    }
    const today = freshnessNormalizeDateText(todayText);
    const core = freshnessMarkSourceCore(line, today);
    if (core === null) {
      return null;
    }
    const read = readFreshness(line, today);
    if (read.fresh === null || read.fresh !== core.date) {
      return null;
    }
    for (const lint of [
      "fresh_malformed",
      "fresh_future",
      "fresh_duplicate",
      "fresh_misplaced",
    ]) {
      if (read.lints.includes(lint)) {
        return null;
      }
    }
    const lastFold =
      core.keepsFold !== null && core.keepsFold !== undefined
        ? core.keepsFold.field
        : core.fold === null
          ? core.freshField
          : core.fold.field;
    const fieldEnd = lastFold.end;
    const fieldStart = core.freshField.start;
    return {
      fieldStart,
      fieldEnd,
      foldSpace: fieldStart > 0 && line[fieldStart - 1] === " ",
      text: line.slice(fieldStart, fieldEnd),
      fresh: core.date,
      refresh: core.fold === null ? null : core.fold.days,
      keeps: freshnessMarkSourceKeeps(core),
    };
  } catch (error) {
    return null;
  }
}

// A rendered-view text node's mark source (`foldSpace` never applies, so
// it is omitted). Skips the task-line and misplaced checks because Tasks
// may have split off the suffix. Never throws.
function freshnessMarkSourceInText(text, todayText) {
  try {
    if (typeof text !== "string") {
      return null;
    }
    const today = freshnessNormalizeDateText(todayText);
    const core = freshnessMarkSourceCore(text, today);
    if (core === null) {
      return null;
    }
    const lastFold =
      core.keepsFold !== null && core.keepsFold !== undefined
        ? core.keepsFold.field
        : core.fold === null
          ? core.freshField
          : core.fold.field;
    const fieldEnd = lastFold.end;
    const fieldStart = core.freshField.start;
    return {
      fieldStart,
      fieldEnd,
      text: text.slice(fieldStart, fieldEnd),
      fresh: core.date,
      refresh: core.fold === null ? null : core.fold.days,
      keeps: freshnessMarkSourceKeeps(core),
    };
  } catch (error) {
    return null;
  }
}

// Fixed English short date from the UTC calendar date, so tooltips are
// deterministic across time zones. Appends the year only when it differs
// from today's year. Never throws: bad input yields null.
function freshnessShortDate(dateText, todayText) {
  try {
    const date = parseFreshDateStrict(String(dateText || ""));
    const today = parseFreshDateStrict(String(todayText || ""));
    if (date === null || today === null) {
      return null;
    }
    const day = new Date(freshDateToUtc(date));
    if (Number.isNaN(day.getTime())) {
      return null;
    }
    const base =
      FRESHNESS_MARK_WEEKDAYS[day.getUTCDay()] +
      ", " +
      FRESHNESS_MARK_MONTHS[Number(date.slice(5, 7)) - 1] +
      " " +
      String(Number(date.slice(8, 10)));
    return date.slice(0, 4) === today.slice(0, 4)
      ? base
      : base + ", " + date.slice(0, 4);
  } catch (error) {
    return null;
  }
}

// The out-of-scope reason for a resolved-but-out-of-scope row, in the
// documented order: lane statuses, `isToday`, `isDailyNote`,
// `recurring`, `_templates`/`_conflicts` path segments, and
// `scheduled` (only when after today). Never throws.
function freshnessMarkReason(status, row, today) {
  try {
    const safe = row && typeof row === "object" ? row : {};
    if (
      status !== null &&
      status !== undefined &&
      status !== " " &&
      Object.hasOwn(FRESHNESS_MARK_STATUS_REASONS, status)
    ) {
      return FRESHNESS_MARK_STATUS_REASONS[status];
    }
    if (status !== null && status !== undefined && status !== " ") {
      return "status [" + status + "]";
    }
    if (safe.isToday) {
      return "linked today";
    }
    if (safe.isDailyNote) {
      return "in a daily note";
    }
    if (safe.recurring) {
      return "recurring";
    }
    if (
      String(safe.path || "")
        .split("/")
        .some(
          (segment) => segment === "_templates" || segment === "_conflicts",
        )
    ) {
      return "in _templates or _conflicts";
    }
    const scheduled = freshnessEvaluateValidScheduled(safe.scheduled);
    if (scheduled !== null && scheduled > today) {
      return (
        "scheduled for " + (freshnessShortDate(scheduled, today) || scheduled)
      );
    }
    return "hidden or dependency-blocked";
  } catch (error) {
    return "hidden or dependency-blocked";
  }
}

// Wrap `freshnessEvaluate` for one memo row: `{ state, tier, lane,
// dueOn, scheduled, status, reason, intervalDays, intervalSource,
// keeps, decide, decayKeeps, decayEnabled, decayCardCapable }`.
// A null `state` with a null `tier` and a reason means out of scope;
// a lane `tier` (pending/next) means due in the walk; an in-walk
// lane with a null tier and no reason is stamped today (M10). An
// evaluator `"new"` is treated as unresolved (null). `keeps` is the
// valid streak and `decide` whether a choice is due (never permission
// to act); both join model equality and consensus so ambiguous
// rendered matches stay neutral. `decayCardCapable` (from
// `options.cardCapable`, default false) records whether the compatible
// nav decision card is installed; only the display affordances read
// it, never the `decide` flag itself. Never throws.
function freshnessMarkResolution(row, todayText, config, options) {
  try {
    if (!row || typeof row !== "object") {
      return null;
    }
    const today = freshnessNormalizeDateText(todayText);
    const evaluated = freshnessEvaluate(row, today, config);
    // An evaluator `"new"` is unresolved (null) — except a due
    // tracker in PROJECTS, which reads as its tier with
    // the effective interval so marks agree with the queue.
    if (
      evaluated.state === "new" &&
      evaluated.tier !== "projects"
    ) {
      return null;
    }
    const status = freshnessTaskStatus(row.rawLine || "");
    let reason = null;
    if (evaluated.tier === null || evaluated.tier === undefined) {
      if (
        (evaluated.lane === "pending" || evaluated.lane === "next") &&
        evaluated.state === null
      ) {
        // In-walk lane stamped today (or otherwise not due) keeps no
        // reason; outside the walk (Today, daily note, disabled lane,
        // recurring, hidden) keeps the existing reason.
        const walkScope =
          evaluated.lane !== null &&
          Boolean(row.laneVisible) &&
          !row.recurring &&
          !row.isDailyNote &&
          !row.isToday;
        const laneDays = freshnessLaneIntervalDays(config, evaluated.lane);
        if (!(walkScope && laneDays !== null)) {
          reason = freshnessMarkReason(status, row, today);
        } else if (evaluated.fresh !== today) {
          // A walked lane that is not due is stamped today; any other
          // fresh date here would already be due, so treat it as out
          // of scope rather than guessing.
          reason = freshnessMarkReason(status, row, today);
        }
      } else if (evaluated.state === null) {
        reason = freshnessMarkReason(status, row, today);
      }
    }
    const decay =
      config && config.decay && typeof config.decay === "object"
        ? config.decay
        : { enabled: true, keeps: 3 };
    return {
      state: evaluated.state,
      tier: evaluated.tier || null,
      lane: evaluated.lane || null,
      dueOn: evaluated.dueOn,
      scheduled: freshnessEvaluateValidScheduled(row.scheduled),
      status,
      reason,
      intervalDays: evaluated.intervalDays,
      intervalSource: evaluated.intervalSource,
      keeps: evaluated.keeps,
      decide: evaluated.decide,
      decayKeeps:
        Number.isInteger(decay.keeps) && decay.keeps >= 0 ? decay.keeps : 3,
      decayEnabled: decay.enabled !== false,
      decayCardCapable: Boolean(
        options && typeof options === "object" && options.cardCapable === true,
      ),
    };
  } catch (error) {
    return null;
  }
}

function freshnessMarkEveryPhrase(days, source) {
  const head = days === 1 ? "every 1 day" : "every " + days + " days";
  if (source === "task") {
    return head + " (this task)";
  }
  if (source === "note") {
    return head + " (this note)";
  }
  if (source === "config") {
    return head + " (config)";
  }
  if (source === "pending") {
    return head + " (pending lane)";
  }
  if (source === "next") {
    return head + " (next lane)";
  }
  if (source === "project") {
    return head + " (project)";
  }
  if (source === "reference") {
    return head + " (reference)";
  }
  return head;
}

function freshnessMarkValidInterval(input) {
  if (
    input &&
    typeof input === "object" &&
    Number.isSafeInteger(input.days) &&
    input.days >= 1 &&
    input.days <= 365
  ) {
    return { days: input.days, source: input.source || "default" };
  }
  return { days: 7, source: "default" };
}

// The dot cap for a keep threshold: thresholds 1-2 use the threshold
// itself, while larger, custom, and zero thresholds cap at three to
// keep line width bounded. Overflow renders as `+N`; the exact count
// is always in accessible text. Never throws.
function freshnessMarkDotCap(limit) {
  try {
    if (limit === 1 || limit === 2) {
      return limit;
    }
    return 3;
  } catch (error) {
    return 3;
  }
}

// The tooltip keeps line for a nonzero streak, or null when there is
// no streak to report. Wording is truthful about card availability:
// the "asks" clause appears only when decay is on and the compatible
// nav decision card is installed; with decay off or in a mixed-version
// session the line counts only. Proper singulars; an explicit sentence
// for threshold zero. Never throws.
function freshnessMarkKeepsLine(keeps, options) {
  try {
    if (!Number.isInteger(keeps) || keeps <= 0) {
      return null;
    }
    const head =
      "Kept " + keeps + (keeps === 1 ? " review in a row" : " reviews in a row");
    const settings =
      options && typeof options === "object" ? options : {};
    if (!settings.active) {
      return head;
    }
    if (!settings.enabled) {
      return head + " · decay off";
    }
    if (settings.limit === 0) {
      return head + " · Bob asks every review";
    }
    return head + " · Bob asks at " + settings.limit;
  } catch (error) {
    return null;
  }
}

// The render model for one mark: `{ text, fresh, ageDays, label,
// intervalDays, intervalSource, intervalLabel, remaining, tone, glyph
// ("check" | "ring" | "refresh" | "leaf"), resolved, keeps, decide,
// dots, overflow, tooltip }`. When resolved the model uses the
// resolution's interval, otherwise `input.interval`. `keeps` is the
// folded streak (the resolution's evaluated count when resolved, else
// the source's folded count) and `decide` whether a choice is due;
// both join model equality and consensus. Dots render for any nonzero
// streak — including resting and unresolved marks, quietly — but the
// decision glyph appears only for an enabled, capable due choice:
// out-of-scope/closed tasks, decay-off rows, and mixed-version
// sessions (no compatible nav card) show historical dots and no leaf.
// Bad sources yield null. Never throws.
function freshnessMarkModel(input) {
  try {
    const args = input && typeof input === "object" ? input : null;
    if (args === null || !args.source || typeof args.source !== "object") {
      return null;
    }
    const source = args.source;
    const today = freshnessNormalizeDateText(args.today);
    const fresh = parseFreshDateStrict(String(source.fresh || ""));
    if (fresh === null) {
      return null;
    }
    const ageDays = freshDateDiffDays(fresh, today);
    if (!Number.isSafeInteger(ageDays) || ageDays < 0) {
      return null;
    }
    const resolution =
      args.resolution !== undefined && args.resolution !== null
        ? args.resolution
        : null;
    const interval = resolution
      ? freshnessMarkValidInterval({
          days: resolution.intervalDays,
          source: resolution.intervalSource,
        })
      : freshnessMarkValidInterval(args.interval);
    const status =
      args.status !== undefined && args.status !== null
        ? args.status
        : resolution && resolution.status !== undefined
          ? resolution.status
          : null;
    const closed =
      status === "x" || status === "X" || status === "-";
    const state = resolution ? resolution.state : null;
    const tier = resolution ? resolution.tier || null : null;
    const lane = resolution ? resolution.lane || null : null;
    let tone;
    if (closed) {
      tone = "resting";
    } else if (
      state === "rotten" ||
      state === "resurfaced" ||
      tier === "pending" ||
      tier === "next" ||
      tier === "recurring"
    ) {
      tone = "due";
    } else if (ageDays === 0) {
      tone = "today";
    } else if (resolution && state === null && tier === null) {
      tone = "resting";
    } else {
      tone = "aging";
    }
    let glyph = tone === "today" ? "check" : tone === "due" ? "refresh" : "ring";
    const remaining =
      Math.round(
        (Math.min(Math.max((interval.days - ageDays) / interval.days, 0), 1) *
          10000),
      ) / 10000;
    // The `/{N}d` suffix appears only when the effective interval
    // source is `task`, and never on the `today` tone; lane intervals
    // stay tooltip-only (M20).
    const intervalLabel =
      source.refresh !== null &&
      source.refresh !== undefined &&
      tone !== "today" &&
      interval.source === "task"
        ? "/" + source.refresh + "d"
        : null;
    const shortFresh = freshnessShortDate(fresh, today) || fresh;
    const relative =
      ageDays === 0
        ? "today"
        : ageDays === 1
          ? "yesterday"
          : ageDays + " days ago";
    const line1 =
      ageDays === 0
        ? "Confirmed today"
        : "Confirmed " + shortFresh + " · " + relative;
    const every = freshnessMarkEveryPhrase(interval.days, interval.source);
    let line2;
    const outOfScope =
      closed ||
      (resolution &&
        resolution.state === null &&
        (resolution.tier === null || resolution.tier === undefined) &&
        resolution.reason);
    if (outOfScope) {
      const reason = closed
        ? FRESHNESS_MARK_CLOSED_REASONS[status] || "status [" + status + "]"
        : resolution.reason || "hidden or dependency-blocked";
      line2 = "Not in the review queue: " + reason;
    } else if (resolution && (tier === "pending" || tier === "next")) {
      const dueOn =
        freshnessShortDate(resolution.dueOn, today) || resolution.dueOn;
      const laneWord = tier === "pending" ? "PENDING" : "NEXT";
      line2 = "Daily " + laneWord + " review due since " + dueOn + " · " + every;
    } else if (
      resolution &&
      (lane === "pending" || lane === "next") &&
      resolution.state === null &&
      (resolution.tier === null || resolution.tier === undefined)
    ) {
      const next = freshDateAddDays(fresh, interval.days);
      const shortNext = freshnessShortDate(next, today) || next;
      line2 = "Next review " + shortNext + " · " + every;
    } else if (resolution && resolution.state === "rotten") {
      const dueOn = freshnessShortDate(resolution.dueOn, today) || resolution.dueOn;
      line2 = "Due for review since " + dueOn + " · " + every;
    } else if (resolution && resolution.state === "resurfaced") {
      const when =
        freshnessShortDate(resolution.scheduled, today) ||
        resolution.scheduled ||
        resolution.dueOn;
      line2 = "Resurfaced " + when + ": scheduled after it was confirmed";
    } else {
      const next = freshDateAddDays(fresh, interval.days);
      const shortNext = freshnessShortDate(next, today) || next;
      line2 =
        today >= next
          ? "Review lease ended " + shortNext + " · " + every
          : "Next review " + shortNext + " · " + every;
    }
    // The leaf replaces `refresh` only for an enabled, capable due
    // choice (`docs/freshness.md` §2a): decay is on, the resolution says
    // a choice is due, and the compatible nav decision card is
    // installed. Everything else keeps its existing glyph and
    // counting-only wording.
    const cardCapable = Boolean(resolution && resolution.decayCardCapable);
    const showDecision =
      tone === "due" &&
      Boolean(resolution && resolution.decide) &&
      cardCapable &&
      resolution.decayEnabled !== false;
    if (showDecision) {
      glyph = "leaf";
    }
    let line3 = null;
    if (tone === "due") {
      if (tier === "pre") {
        line3 = "PRE checklist · complete to resolve";
      } else if (tier === "post") {
        line3 = "POST closeout · complete to close review";
      } else if (tier === "pending" || tier === "next") {
        line3 = "Alt+F keep · Alt+N release · Ctrl+Shift+Enter today";
      } else if (tier === "recurring") {
        line3 = "complete or reschedule to resolve";
      } else if (showDecision) {
        line3 = "Alt+F to decide";
      } else {
        line3 = "Alt+F to confirm";
      }
    }
    // Folded keep streak: the resolution's evaluated count when
    // resolved (so consensus sees the row's count), else the source's
    // folded count. Unresolved marks show historical dots quietly with
    // counting-only wording and never decide.
    const keeps =
      resolution &&
      Number.isInteger(resolution.keeps) &&
      resolution.keeps >= 0
        ? resolution.keeps
        : Number.isInteger(source.keeps) && source.keeps > 0
          ? source.keeps
          : 0;
    const decide = Boolean(resolution && resolution.decide);
    const limit =
      resolution && Number.isInteger(resolution.decayKeeps)
        ? resolution.decayKeeps
        : 3;
    const cap = freshnessMarkDotCap(limit);
    const shown = Math.min(keeps, cap);
    const dots = keeps > 0 ? "•".repeat(shown) : null;
    const overflow = keeps > cap ? "+" + (keeps - cap) : null;
    const keepsLine =
      resolution != null
        ? freshnessMarkKeepsLine(keeps, {
            active: cardCapable,
            enabled: resolution.decayEnabled !== false,
            limit,
          })
        : freshnessMarkKeepsLine(keeps, {
            active: false,
            enabled: true,
            limit,
          });
    let tooltip = line1 + "\n" + line2;
    if (keepsLine !== null) {
      tooltip += "\n" + keepsLine;
    }
    if (line3 !== null) {
      tooltip += "\n" + line3;
    }
    return {
      text: source.text,
      fresh,
      ageDays,
      label: ageDays === 0 ? "today" : ageDays + "d",
      intervalDays: interval.days,
      intervalSource: interval.source,
      intervalLabel,
      remaining,
      tone,
      glyph,
      resolved: resolution !== null,
      keeps,
      decide,
      dots,
      overflow,
      tooltip,
    };
  } catch (error) {
    return null;
  }
}

// Consensus across candidate models: the model when at least one
// candidate exists and all are deep-equal, else null. Never throws.
function freshnessMarkConsensus(models) {
  try {
    if (!Array.isArray(models) || models.length === 0) {
      return null;
    }
    const first = JSON.stringify(models[0]);
    for (const model of models) {
      if (JSON.stringify(model) !== first) {
        return null;
      }
    }
    return models[0] === null || models[0] === undefined ? null : models[0];
  } catch (error) {
    return null;
  }
}

// Listener-free mark element, so it survives Dataview's innerHTML
// round-trip. `doc` provides `createElement`, `createElementNS`, and
// `createTextNode` so tests can pass a fake document. Never throws:
// bad input yields null.
function buildFreshnessMarkElement(doc, model, options) {
  try {
    if (!doc || !model || typeof model !== "object") {
      return null;
    }
    const foldSpace = Boolean(options && options.foldSpace);
    const tone = model.tone;
    if (tone !== "today" && tone !== "aging" && tone !== "due" && tone !== "resting") {
      return null;
    }
    const span = doc.createElement("span");
    span.setAttribute("class", "bob-fresh-mark");
    span.setAttribute("data-tone", tone);
    span.setAttribute("data-resolved", model.resolved ? "true" : "false");
    span.setAttribute("data-fold-space", foldSpace ? "true" : "false");
    span.setAttribute(
      "data-decide",
      model.glyph === "leaf" ? "true" : "false",
    );
    span.setAttribute("role", "img");
    span.setAttribute("aria-label", String(model.tooltip || ""));
    span.setAttribute("data-tooltip-position", "top");
    const svg = doc.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("class", "bob-fresh-mark-glyph");
    svg.setAttribute("viewBox", "0 0 16 16");
    svg.setAttribute("aria-hidden", "true");
    const track = doc.createElementNS("http://www.w3.org/2000/svg", "circle");
    track.setAttribute("class", "bob-fresh-mark-track");
    track.setAttribute("cx", "8");
    track.setAttribute("cy", "8");
    track.setAttribute("r", "6");
    if (model.glyph === "check") {
      track.setAttribute("opacity", "1");
      svg.appendChild(track);
      const tick = doc.createElementNS("http://www.w3.org/2000/svg", "path");
      tick.setAttribute("d", "M5.4 8.2l1.8 1.8 3.4-3.6");
      svg.appendChild(tick);
    } else if (model.glyph === "refresh") {
      const arc = doc.createElementNS("http://www.w3.org/2000/svg", "path");
      arc.setAttribute(
        "d",
        "M14 8a6 6 0 1 1-6-6c1.68 0 3.29.67 4.49 1.83L14 5.33",
      );
      svg.appendChild(arc);
      const head = doc.createElementNS("http://www.w3.org/2000/svg", "path");
      head.setAttribute("d", "M14 2v3.33h-3.33");
      svg.appendChild(head);
    } else if (model.glyph === "leaf") {
      // Active decision due (`docs/freshness.md` §2a): a code-native leaf
      // in the established 16-unit box and 1.9 stroke, inheriting the due
      // capsule's subdued orange — no new theme variables, no bitmap.
      const body = doc.createElementNS("http://www.w3.org/2000/svg", "path");
      body.setAttribute(
        "d",
        "M12.8 3.2C7.6 3.4 4 6.6 3.4 12.6 9.4 12 12.6 8.4 12.8 3.2Z",
      );
      svg.appendChild(body);
      const vein = doc.createElementNS("http://www.w3.org/2000/svg", "path");
      vein.setAttribute("d", "M4.2 11.8C6.6 9.4 9 7 11.8 4.2");
      svg.appendChild(vein);
    } else {
      svg.appendChild(track);
      if (model.remaining > 0) {
        const arc = doc.createElementNS(
          "http://www.w3.org/2000/svg",
          "circle",
        );
        arc.setAttribute("class", "bob-fresh-mark-arc");
        arc.setAttribute("cx", "8");
        arc.setAttribute("cy", "8");
        arc.setAttribute("r", "6");
        arc.setAttribute("pathLength", "100");
        arc.setAttribute(
          "stroke-dasharray",
          (model.remaining * 100).toFixed(2) + " 100",
        );
        arc.setAttribute("transform", "rotate(-90 8 8)");
        svg.appendChild(arc);
      }
    }
    span.appendChild(svg);
    const label = doc.createElement("span");
    label.setAttribute("class", "bob-fresh-mark-label");
    label.appendChild(doc.createTextNode(String(model.label || "")));
    span.appendChild(label);
    // Folded keep pips: filled dots (about 0.34em with 0.14em gaps via
    // CSS), capped per threshold with `+N` overflow. The dots are
    // aria-hidden; the exact count lives in the accessible tooltip
    // text. Dots stay faint on every tone — never green on `today`,
    // subdued orange in a `due` capsule — with no red, border, or
    // achievement styling.
    if (typeof model.dots === "string" && model.dots !== "") {
      const pips = doc.createElement("span");
      pips.setAttribute("class", "bob-fresh-mark-dots");
      pips.setAttribute("aria-hidden", "true");
      pips.appendChild(
        doc.createTextNode(
          model.dots +
            (typeof model.overflow === "string" ? model.overflow : ""),
        ),
      );
      span.appendChild(pips);
    }
    if (model.intervalLabel !== null && model.intervalLabel !== undefined) {
      const suffix = doc.createElement("span");
      suffix.setAttribute("class", "bob-fresh-mark-interval");
      suffix.appendChild(doc.createTextNode(String(model.intervalLabel)));
      span.appendChild(suffix);
    }
    return span;
  } catch (error) {
    return null;
  }
}
// ---- src/135-freshness-rotten-log.js ----
// Rotten Log tooltip line for freshness marks.
// Source of truth for the marker/entry grammar:
// `ROTTEN_LOG_PARENT_RE` / `ROTTEN_LOG_ENTRY_RE` in
// `plugins/bob-navigation-hotkeys/src/010-requires-and-config.js`, and
// `readRottenLog` / `findManagedTaskLogParents` in
// `plugins/bob-navigation-hotkeys/src/030-bullet-blocks-and-logs.js`.
// This file mirrors those byte-for-byte so Live Preview and reading view
// count exactly what nav counts. Do not diverge without updating nav,
// the Rust `parse_managed_task_log_marker` in
// `src/native/capture/sub_bullet.rs`, and `docs/freshness.md` §11.
const FRESHNESS_ROTTEN_PARENT_RE =
  /^(?<indent>\s*(?:>\s*)*)(?<marker>(?:[-*+]|\d+[.)]))[ \t]+(?<emoji>🥀\uFE0F?[ \t]+)?\*\*(?<label>ROTTEN LOG|Rotten log):?\*\*[ \t]*$/;
const FRESHNESS_ROTTEN_ENTRY_RE =
  /^(?<indent>\s*(?:>\s*)*)(?<marker>(?:[-*+]|\d+[.)]))[ \t]+\*(?<date>\d{4}-\d{2}-\d{2})\* — (?<reason>.+) · kept (?<keeps>\d{1,3})×$/;
const FRESHNESS_ROTTEN_LIST_ITEM_RE =
  /^\s*(?:>\s*)*(?:[-*+]|\d+[.)])\s/;

function freshnessRottenIndentOf(line) {
  try {
    const match = /^(\s*(?:>\s*)*)/.exec(String(line || ""));
    return match ? match[1] : "";
  } catch (error) {
    return "";
  }
}

function freshnessRottenIndentWidth(line) {
  try {
    let width = 0;
    for (const character of freshnessRottenIndentOf(line)) {
      if (character === "\t") {
        width += 4 - (width % 4);
      } else if (character === ">") {
        width += 4;
      } else {
        width += 1;
      }
    }
    return width;
  } catch (error) {
    return 0;
  }
}

function freshnessRottenNearestParent(lines, childLine) {
  try {
    const source = Array.isArray(lines) ? lines : [];
    const childIndex = Math.floor(Number(childLine));
    if (!Number.isFinite(childIndex) || childIndex <= 0) return null;
    const childWidth = freshnessRottenIndentWidth(source[childIndex] || "");
    for (let line = childIndex - 1; line >= 0; line -= 1) {
      const text = String(source[line] || "");
      if (!text.trim() || freshnessRottenIndentWidth(text) >= childWidth) continue;
      if (FRESHNESS_ROTTEN_LIST_ITEM_RE.test(text)) return line;
    }
    return null;
  } catch (error) {
    return null;
  }
}

function freshnessRottenChildBlock(lines, parentLine) {
  try {
    const source = Array.isArray(lines) ? lines : [];
    const parentIndex = Math.floor(Number(parentLine));
    if (!Number.isFinite(parentIndex) || parentIndex < 0) {
      return { startLine: 0, endLineExclusive: 0 };
    }
    const startLine = parentIndex + 1;
    const parentWidth = freshnessRottenIndentWidth(
      String(source[parentIndex] || ""),
    );
    let endLineExclusive = startLine;
    for (let index = startLine; index < source.length; index += 1) {
      const text = String(source[index] || "");
      if (text.trim() === "") continue;
      if (freshnessRottenIndentWidth(text) > parentWidth) {
        endLineExclusive = index + 1;
        continue;
      }
      break;
    }
    return { startLine, endLineExclusive };
  } catch (error) {
    return { startLine: 0, endLineExclusive: 0 };
  }
}

function freshnessRottenParseMarker(line) {
  try {
    const match = FRESHNESS_ROTTEN_PARENT_RE.exec(String(line || ""));
    if (!match) return null;
    const groups = (match && match.groups) || {};
    return { indent: groups.indent || "", marker: groups.marker || "-" };
  } catch (error) {
    return null;
  }
}

function freshnessRottenParseEntry(line) {
  try {
    const match = FRESHNESS_ROTTEN_ENTRY_RE.exec(String(line || ""));
    if (!match) return null;
    const groups = (match && match.groups) || {};
    const count = Number(groups.keeps);
    if (!Number.isInteger(count) || count < 1 || count > 999) return null;
    const reason = String(groups.reason || "").trim();
    if (!reason) return null;
    return { date: groups.date, reason, keeps: count };
  } catch (error) {
    return null;
  }
}

// Read one task's direct-child Rotten Log. Returns
// `{ status, entries }` with `status` one of `missing` (no marker),
// `empty` (marker but no valid entries), `ok`, or `unknown`
// (two or more direct-child markers). Only direct children of the task
// count as markers, and only direct children of the marker count as
// entries, each exactly `*YYYY-MM-DD* — <reason> · kept N×` with N
// from 1 to 999. Never throws.
function freshnessMarkRottenLogHistory(lines, taskLine) {
  try {
    const source = Array.isArray(lines)
      ? lines
      : String(lines || "").split(/\r?\n/);
    const taskIndex = Math.floor(Number(taskLine));
    if (!Number.isFinite(taskIndex) || taskIndex < 0) {
      return { status: "missing", entries: [] };
    }
    const block = freshnessRottenChildBlock(source, taskIndex);
    const parents = [];
    for (let index = block.startLine; index < block.endLineExclusive; index += 1) {
      if (freshnessRottenNearestParent(source, index) !== taskIndex) continue;
      if (freshnessRottenParseMarker(source[index])) {
        parents.push(index);
      }
    }
    if (parents.length > 1) return { status: "unknown", entries: [] };
    if (parents.length === 0) return { status: "missing", entries: [] };
    const parent = parents[0];
    const childBlock = freshnessRottenChildBlock(source, parent);
    const entries = [];
    for (let index = childBlock.startLine; index < childBlock.endLineExclusive; index += 1) {
      if (freshnessRottenNearestParent(source, index) !== parent) continue;
      const parsed = freshnessRottenParseEntry(source[index]);
      if (parsed) entries.push(parsed);
    }
    if (!entries.length) return { status: "empty", entries: [] };
    return { status: "ok", entries };
  } catch (error) {
    return { status: "missing", entries: [] };
  }
}

// Short `Oct 16` date for the rotten line, using the same
// `FRESHNESS_MARK_MONTHS` names that `freshnessShortDate` uses but
// without the weekday, with `, YYYY` appended when the year differs
// from today's. Bad input yields null. Never throws.
function freshnessMarkRottenLogShortDate(dateText, todayText) {
  try {
    const date = String(dateText || "");
    const today = String(todayText || "");
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
    if (!match) return null;
    const month = Number(match[2]);
    const day = Number(match[3]);
    if (!Number.isInteger(month) || month < 1 || month > 12) return null;
    if (!Number.isInteger(day) || day < 1 || day > 31) return null;
    const name = FRESHNESS_MARK_MONTHS[month - 1];
    if (!name) return null;
    const base = `${name} ${day}`;
    const todayYear = /^(\d{4})-\d{2}-\d{2}$/.exec(today);
    if (!todayYear) return base;
    return todayYear[1] === match[1] ? base : `${base}, ${match[1]}`;
  } catch (error) {
    return null;
  }
}

// Truncate a reason to 48 characters plus `…`, counting code points
// so an emoji is never split. Never throws.
function freshnessMarkRottenTruncateReason(reason) {
  try {
    const points = Array.from(String(reason || ""));
    if (points.length <= 48) return points.join("");
    return points.slice(0, 48).join("") + "…";
  } catch (error) {
    return String(reason || "");
  }
}

// Display-only rotten line for a history:
// `🥀 N keeps logged · last <date> — <reason>`, or
// `🥀 1 keep logged · …` for one entry. `<date>` is `Oct 16`
// (with `, YYYY` when the year differs from today's); the newest
// entry's reason truncates to 48 characters plus `…`;
// `🤷 no reason given` shows as is. Returns null when there is
// nothing to show (missing, empty, or unknown/ambiguous logs).
// Never throws.
function freshnessMarkRottenLogLine(history, today) {
  try {
    const status = history && history.status;
    if (status === "unknown" || status === "ambiguous") return null;
    const entries = history && Array.isArray(history.entries)
      ? history.entries
      : [];
    if (!entries.length) return null;
    const latest = entries[0] || {};
    const date = freshnessMarkRottenLogShortDate(latest.date, today);
    if (!date) return null;
    const rawReason = String(latest.reason || "").trim() || "🤷 no reason given";
    const reason = freshnessMarkRottenTruncateReason(rawReason);
    const count = entries.length;
    const head = count === 1 ? "1 keep logged" : `${count} keeps logged`;
    return `🥀 ${head} · last ${date} — ${reason}`;
  } catch (error) {
    return null;
  }
}

// Display-only summary for one task's direct-child Rotten Log. `lines`
// is the raw source note and `taskLine` is zero-based. A malformed or
// duplicated marker is unknown, never an invented zero-count history.
function freshnessMarkRottenLogSummary(lines, taskLine, todayText) {
  try {
    const history = freshnessMarkRottenLogHistory(lines, taskLine);
    if (!history || history.status !== "ok") return null;
    return freshnessMarkRottenLogLine(history, todayText);
  } catch (error) {
    return null;
  }
}

function freshnessRottenEntryHasEmphasis(item, date) {
  try {
    if (!item) return false;
    const wanted = String(date || "");
    if (!wanted) return false;
    const stack = [item];
    let guard = 0;
    while (stack.length > 0 && guard < 200) {
      guard += 1;
      const node = stack.pop();
      if (!node) continue;
      const tag = String(node.tagName || node.nodeName || "").toUpperCase();
      if (tag === "EM" || tag === "I") {
        if (String(node.textContent || "").includes(wanted)) return true;
      }
      const kids = node.children || node.childNodes || [];
      for (const kid of Array.from(kids)) {
        if (kid && kid.nodeType !== 3) stack.push(kid);
      }
    }
    if (typeof item.querySelectorAll === "function") {
      for (const el of Array.from(item.querySelectorAll("em,i"))) {
        if (String(el.textContent || "").includes(wanted)) return true;
      }
    }
    return false;
  } catch (error) {
    return false;
  }
}

function freshnessMarkRottenLogSummaryFromListItem(taskItem, todayText) {
  try {
    const children = Array.from((taskItem && taskItem.children) || []);
    const lists = children.filter((node) => /^(UL|OL)$/i.test(node.tagName || ""));
    const markers = [];
    for (const list of lists) {
      for (const item of Array.from(list.children || [])) {
        if (!/^(LI)$/i.test(item.tagName || "")) continue;
        const label = String(item.childNodes && item.childNodes.length
          ? Array.from(item.childNodes).filter((child) => child.nodeType === 3 || !/^(UL|OL)$/i.test(child.tagName || "")).map((child) => child.textContent || child.nodeValue || "").join("")
          : item.textContent || "").trim();
        if (/^(?:🥀\uFE0F?[ \t]+)?(?:\*\*)?(?:ROTTEN LOG|Rotten log)(?:\*\*)?:?$/.test(label)) {
          markers.push(item);
        }
      }
    }
    if (markers.length !== 1) return null;
    const marker = markers[0];
    const nestedLists = Array.from(marker.children || []).filter((node) => /^(UL|OL)$/i.test(node.tagName || ""));
    const entries = [];
    for (const list of nestedLists) {
      for (const item of Array.from(list.children || [])) {
        if (!/^(LI)$/i.test(item.tagName || "")) continue;
        const text = String(item.textContent || "").trim();
        const match = text.match(
          /^(\d{4}-\d{2}-\d{2})\s+—\s+(.+?)\s+·\s+kept\s+(\d{1,3})×$/,
        );
        if (!match) continue;
        const count = Number(match[3]);
        if (!Number.isInteger(count) || count < 1 || count > 999) continue;
        const reason = String(match[2] || "").trim();
        if (!reason) continue;
        if (!freshnessRottenEntryHasEmphasis(item, match[1])) continue;
        entries.push({ date: match[1], reason, keeps: count });
      }
    }
    if (!entries.length) return null;
    return freshnessMarkRottenLogLine({ status: "ok", entries }, todayText);
  } catch (error) {
    return null;
  }
}

function freshnessMarkTaskListItem(node, root) {
  try {
    let current = node;
    let guard = 0;
    while (current && current !== root && guard < 100) {
      guard += 1;
      if (/^(LI)$/i.test(current.tagName || "")) return current;
      current = current.parentNode || null;
    }
    return null;
  } catch (error) {
    return null;
  }
}

function freshnessMarkInTaskQuery(node, root) {
  try {
    let current = node;
    let guard = 0;
    while (current && current !== root && guard < 100) {
      guard += 1;
      const classes = String(current.className || (current.getAttribute && current.getAttribute("class")) || "");
      if (/(?:^|\s)(?:block-language-dataview|dataview-result-list|dataview-result-table|block-language-tasks|plugin-tasks-query-result)(?:\s|$)/.test(classes)) return true;
      current = current.parentNode || null;
    }
    return false;
  } catch (error) {
    return false;
  }
}

// Splice a rotten line before the action line (`Alt+F…`, checklist
// tiers, `complete or reschedule…`). When no action line is present
// the rotten line appends at the end (after the keeps line).
// Never throws; bad input returns the model unchanged.
function freshnessMarkWithRottenLine(model, rottenLine) {
  try {
    if (!model || !rottenLine) return model;
    const lines = String(model.tooltip || "").split("\n");
    const last = lines[lines.length - 1] || "";
    if (/^(?:Alt\+F|PRE checklist|POST closeout|complete or reschedule)/.test(last)) {
      lines.splice(lines.length - 1, 0, rottenLine);
    } else {
      lines.push(rottenLine);
    }
    model.tooltip = lines.join("\n");
    return model;
  } catch (error) {
    return model;
  }
}

// Read only the task's child block through the CodeMirror `Text` API
// (`doc.line(n)`, `doc.lines`), starting at the task line. Stops at
// the first nonblank line indented at or above the task's
// indentation. Caps at 5,000 lines. Never calls `doc.toString`.
// Returns an array with the task line first, or null. Never throws.
function freshnessRottenLinesFromDoc(doc, taskLine) {
  try {
    if (!doc || typeof doc.line !== "function") return null;
    if (!Number.isInteger(taskLine) || taskLine < 0) return null;
    const total = typeof doc.lines === "number" ? doc.lines : null;
    if (total !== null && (!Number.isFinite(total) || total <= 0)) return null;
    const taskOneBased = taskLine + 1;
    if (total !== null && taskOneBased > total) return null;
    let taskText = null;
    try {
      taskText = doc.line(taskOneBased).text;
    } catch (error) {
      return null;
    }
    if (typeof taskText !== "string") return null;
    const taskWidth = freshnessRottenIndentWidth(taskText);
    const out = [taskText];
    const limit = total !== null ? Math.min(total, taskOneBased + 5000) : taskOneBased + 5000;
    for (let n = taskOneBased + 1; n <= limit; n += 1) {
      let text = null;
      try {
        text = doc.line(n).text;
      } catch (error) {
        break;
      }
      if (typeof text !== "string") break;
      if (text.trim() === "") {
        out.push(text);
        continue;
      }
      if (freshnessRottenIndentWidth(text) <= taskWidth) break;
      out.push(text);
    }
    return out;
  } catch (error) {
    return null;
  }
}

function freshnessMarkModelWithRottenLog(input, docOrLines, taskLine) {
  try {
    const model = freshnessMarkModel(input);
    if (!model) return model;
    const today = input && typeof input.today === "string" ? input.today : undefined;
    let lines = null;
    if (Array.isArray(docOrLines)) {
      lines = docOrLines;
    } else if (typeof docOrLines === "string") {
      lines = String(docOrLines).split(/\r?\n/);
    } else if (docOrLines && typeof docOrLines.line === "function") {
      lines = freshnessRottenLinesFromDoc(docOrLines, taskLine);
      if (lines) {
        const history = freshnessMarkRottenLogHistory(lines, 0);
        if (!history || history.status !== "ok") return model;
        const line = freshnessMarkRottenLogLine(history, today);
        if (!line) return model;
        return freshnessMarkWithRottenLine(model, line);
      }
      return model;
    } else {
      return model;
    }
    const history = freshnessMarkRottenLogHistory(lines, taskLine);
    if (!history || history.status !== "ok") return model;
    const line = freshnessMarkRottenLogLine(history, today);
    if (!line) return model;
    return freshnessMarkWithRottenLine(model, line);
  } catch (error) {
    try {
      return freshnessMarkModel(input);
    } catch (inner) {
      return null;
    }
  }
}
// ---- src/135-priority-marks.js ----
// --- Task priority marks: pure mark-core ----------------------------------
// Owned by the `### Priority marks` display contract in bob-cli
// `docs/projects.md`. Pure helpers only: canonical-field source
// detection, the lenient ladder-config reader, the mark model and
// tooltip, a listener-free DOM builder, and the Live Preview widget.
// Every helper is synchronous and never throws; bad input yields
// null. Mirrors the freshness-mark code paths in
// `130-freshness-marks.js` and reuses `freshnessTaskStatus` and
// `freshnessMarkPosInCode` (code exclusion) from the sibling
// fragments. The glyph is chosen by stored Tasks value, never by
// ladder position, so marks stay truthful without config.

// The five stored Tasks priority values. Anything else (including
// `P2`, `urgent`, and uppercase spellings) is non-canonical and gets
// no mark.
const PRIORITY_MARK_VALUES = ["highest", "high", "medium", "low", "lowest"];

// Bars filled per stored value on the 4-bar signal staircase.
const PRIORITY_MARK_FILLED = {
  high: 4,
  medium: 3,
  low: 2,
  lowest: 1,
  highest: 0,
};

// Capitalize a stored value for tooltip text (`high` -> `High`).
// Never throws.
function priorityMarkCapitalized(value) {
  try {
    const text = String(value || "");
    if (text === "") {
      return "";
    }
    return text.slice(0, 1).toUpperCase() + text.slice(1).toLowerCase();
  } catch (error) {
    return "";
  }
}

// The single canonical `[priority:: value]` / `(priority:: value)`
// field on `line`, or null. Canonical means: exactly one
// `/priority\s*::/gi` occurrence on the line, the key exactly
// `priority`, a matching bracket pair, padding spaces only, and a
// lowercase stored value. (A dedicated matcher, not
// `freshnessInlineFields`, because the canonical form allows padding
// spaces inside the brackets.) Returns `{ value, fieldStart,
// fieldEnd }` with UTF-16 offsets, or null. Never throws.
function priorityMarkCanonicalField(line) {
  try {
    const text = String(line || "");
    if (text === "") {
      return null;
    }
    const occurrences = text.match(/priority\s*::/gi) || [];
    if (occurrences.length !== 1) {
      return null;
    }
    const pattern = new RegExp(
      "\\[ *priority:: *(highest|high|medium|low|lowest) *\\]" +
        "|\\( *priority:: *(highest|high|medium|low|lowest) *\\)",
      "g",
    );
    const match = pattern.exec(text);
    if (!match) {
      return null;
    }
    // Defensive: the single-occurrence gate above already rules out
    // a second field, but never fold when two match.
    if (pattern.exec(text) !== null) {
      return null;
    }
    const value =
      match[1] !== undefined ? match[1] : match[2];
    return {
      value,
      fieldStart: match.index,
      fieldEnd: match.index + match[0].length,
    };
  } catch (error) {
    return null;
  }
}

// A Live Preview task line's priority-mark source, or null when the
// line gets no mark. `fieldStart`/`fieldEnd` are UTF-16 offsets of
// the field text, excluding the folded space. Never throws.
function priorityMarkSource(lineText) {
  try {
    if (typeof lineText !== "string") {
      return null;
    }
    if (freshnessTaskStatus(lineText) === null) {
      return null;
    }
    const found = priorityMarkCanonicalField(lineText);
    if (found === null) {
      return null;
    }
    return {
      value: found.value,
      fieldStart: found.fieldStart,
      fieldEnd: found.fieldEnd,
      foldSpace:
        found.fieldStart > 0 && lineText[found.fieldStart - 1] === " ",
    };
  } catch (error) {
    return null;
  }
}

// A rendered-view text node's priority-mark source (`foldSpace`
// never applies, so it is omitted). Skips the task-line check
// because Tasks may have split off the suffix. Never throws.
function priorityMarkSourceInText(text) {
  try {
    if (typeof text !== "string") {
      return null;
    }
    const found = priorityMarkCanonicalField(text);
    if (found === null) {
      return null;
    }
    return {
      value: found.value,
      fieldStart: found.fieldStart,
      fieldEnd: found.fieldEnd,
    };
  } catch (error) {
    return null;
  }
}

// Lenient ladder-config reader: the first `properties[]` entry with
// `name === "priority"` and `values === "priority"`. Keeps levels
// with a non-empty string label, a scalar value, and integer
// `0 <= min_days <= max_days`; skips bad levels and never shows
// Notices (nav owns config validation). Returns a frozen list of
// frozen `{ label, value, minDays, maxDays }`, or null when the
// ladder is unknown (missing, unreadable, or invalid config, no
// matching entry, no valid levels, or mobile). Never throws.
function coercePriorityLadder(parsedYaml) {
  try {
    if (
      !parsedYaml ||
      typeof parsedYaml !== "object" ||
      Array.isArray(parsedYaml)
    ) {
      return null;
    }
    const properties = parsedYaml.properties;
    if (!Array.isArray(properties)) {
      return null;
    }
    let entry = null;
    for (const candidate of properties) {
      try {
        if (
          candidate &&
          typeof candidate === "object" &&
          !Array.isArray(candidate) &&
          candidate.name === "priority" &&
          candidate.values === "priority"
        ) {
          entry = candidate;
          break;
        }
      } catch (error) {
        continue;
      }
    }
    if (entry === null) {
      return null;
    }
    const rawLevels = entry.levels;
    if (!Array.isArray(rawLevels)) {
      return null;
    }
    const kept = [];
    for (const raw of rawLevels) {
      try {
        if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
          continue;
        }
        const label = raw.label;
        if (typeof label !== "string" || label.trim() === "") {
          continue;
        }
        const rawValue = raw.value;
        if (
          rawValue === null ||
          rawValue === undefined ||
          typeof rawValue === "object"
        ) {
          continue;
        }
        const value = String(rawValue);
        if (value === "") {
          continue;
        }
        const minRaw =
          raw.min_days !== undefined ? raw.min_days : raw.minDays;
        const maxRaw =
          raw.max_days !== undefined ? raw.max_days : raw.maxDays;
        if (
          typeof minRaw !== "number" ||
          typeof maxRaw !== "number" ||
          !Number.isInteger(minRaw) ||
          !Number.isInteger(maxRaw) ||
          minRaw < 0 ||
          maxRaw < 0 ||
          minRaw > maxRaw
        ) {
          continue;
        }
        kept.push(
          Object.freeze({
            label: label.trim(),
            value,
            minDays: minRaw,
            maxDays: maxRaw,
          }),
        );
      } catch (error) {
        continue;
      }
    }
    if (kept.length === 0) {
      return null;
    }
    return Object.freeze(kept);
  } catch (error) {
    return null;
  }
}

// The `Rolls …` tooltip line for a ladder level: equal bounds read
// `Rolls 5 days ahead`, 1-1 reads `Rolls 1 day ahead`. Never throws.
function priorityMarkRollsLine(minDays, maxDays) {
  try {
    if (minDays === maxDays) {
      return minDays === 1
        ? "Rolls 1 day ahead"
        : "Rolls " + minDays + " days ahead";
    }
    return "Rolls " + minDays + "\u2013" + maxDays + " days ahead";
  } catch (error) {
    return "Rolls ahead";
  }
}

// The render model for one mark: `{ value, glyph ("bars" |
// "urgent"), filled, label, tooltip, key }`. The glyph is chosen by
// stored Tasks value, never by ladder position; labels and windows
// come from the ladder. `label` is null when the value is off the
// ladder or the ladder is unknown. The tooltip never contains `::`,
// because Dataview's reading-view pass re-scans `innerHTML` for
// inline fields. Bad values yield null. Never throws.
