  try {
    if (typeof lineText !== "string") {
      return 0;
    }
    if (fieldStart <= contentStart) {
      return 0;
    }
    let run = 0;
    let index = fieldStart - 1;
    while (index >= contentStart && lineText[index] === " ") {
      run += 1;
      index -= 1;
    }
    return run;
  } catch (error) {
    return 0;
  }
