  try {
    if (typeof text !== "string" || text === "") {
      return Object.freeze([]);
    }
    const fields = dateMarkCanonicalFields(text);
    const sources = [];
    for (const field of fields) {
      try {
        sources.push(
          Object.freeze({
            field: field.field,
            date: field.date,
            fieldStart: field.fieldStart,
            fieldEnd: field.fieldEnd,
            foldLength: 0,
          }),
        );
      } catch (error) {
        continue;
      }
    }
    return Object.freeze(sources);
  } catch (error) {
    return Object.freeze([]);
  }
