        chipEl.setAttribute("title", safe.tooltip);
        chipEl.setAttribute("aria-label", safe.aria);
        chipEl.setAttribute(
          "class",
          `bob-plan-chip bob-note-ready-heading` +
            `${safe.over ? " bob-plan-over" : ""}` +
            `${safe.placeholder ? " bob-plan-unavailable" : ""}` +
            `${safe.exempt ? " is-exempt" : ""}`,
        );
