                      source && (source.kind === "pre" || source.kind === "post")
                        ? new ChecklistTaskMarkWidget(source.kind)
                        : source && source.kind === "ref"
                          ? new RefTaskMarkWidget()
                          : new TaskTagMarkWidget();
